const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outDir = path.join(rootDir, "public", "handbook");

const css = `:root{--paper:#F6F7FA;--panel:#FFFFFF;--ink:#161D2B;--ink-soft:#465063;--line:#D8DCE6;--green:#22418A;--green-deep:#15294F;--green-tint:#E8EDF7;--amber:#A8650D;--amber-tint:#FBF2E3;--red:#9A3324;--red-tint:#F9ECE9;--mono:'IBM Plex Mono',ui-monospace,monospace;--sans:'Pretendard Variable',Pretendard,-apple-system,sans-serif}*{margin:0;padding:0;box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{font-family:var(--sans);background:var(--paper);color:var(--ink);line-height:1.75;font-size:16px}.shell{display:grid;grid-template-columns:264px 1fr;max-width:1280px;margin:0 auto}nav{position:sticky;top:0;height:100vh;overflow-y:auto;border-right:1px solid var(--line);padding:32px 20px 48px;background:var(--paper)}main{min-width:0;padding:0 56px 120px;background:var(--paper)}@media(max-width:900px){.shell{grid-template-columns:1fr}nav{position:static;height:auto;border-right:none;border-bottom:1px solid var(--line)}main{padding:0 20px 80px}}.nav-brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--green);font-weight:600;margin-bottom:4px}.nav-title{font-size:15px;font-weight:700;margin-bottom:24px;letter-spacing:0}nav a{display:flex;gap:10px;align-items:baseline;text-decoration:none;color:var(--ink-soft);padding:7px 8px;border-radius:0;font-size:13.5px;line-height:1.4}nav a:hover{background:var(--green-tint);color:var(--green-deep)}nav a .code{font-family:var(--mono);font-size:10.5px;color:var(--green);flex-shrink:0;letter-spacing:.04em}header.hero{padding:72px 0 48px;border-bottom:1px solid var(--ink)}.hero-serial{font-family:var(--mono);font-size:12px;letter-spacing:.12em;color:var(--green);display:flex;gap:16px;flex-wrap:wrap;margin-bottom:24px}.hero-serial span{border:1px solid var(--line);padding:3px 10px;border-radius:0;background:var(--panel)}h1{font-size:clamp(30px,4.5vw,46px);font-weight:800;letter-spacing:0;line-height:1.18}.hero-sub{margin-top:18px;font-size:17px;color:var(--ink-soft);max-width:720px}.hero-meta{margin-top:28px;font-family:var(--mono);font-size:11.5px;color:var(--ink-soft);letter-spacing:.05em}section{padding-top:72px}.ch-head{display:flex;align-items:baseline;gap:14px;border-bottom:2px solid var(--ink);padding-bottom:12px;margin-bottom:28px}.ch-code{font-family:var(--mono);font-size:12px;font-weight:600;color:var(--green);letter-spacing:.1em;flex-shrink:0}h2{font-size:26px;font-weight:800;letter-spacing:0}p{margin-bottom:14px}p.lede{font-size:17px;color:var(--ink-soft)}code{font-family:var(--mono);font-size:.86em;background:var(--green-tint);color:var(--green-deep);padding:1px 6px;border-radius:0}.callout{border:1px solid var(--line);border-left:3px solid var(--green);background:var(--panel);padding:18px 22px;border-radius:0;margin:22px 0}.callout.gm{border-left-color:var(--ink);background:#ECEEF3}.co-label{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;font-weight:600;color:var(--green);display:block;margin-bottom:6px}table{width:100%;border-collapse:collapse;margin:22px 0;font-size:14px;background:var(--panel);border:1px solid var(--line)}th{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-align:left;font-weight:600;color:var(--green-deep);background:var(--green-tint);padding:10px 14px;border-bottom:1px solid var(--line)}td{padding:11px 14px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.6}.semantic-card{background:var(--green-tint);border:1px solid var(--line);border-radius:0;padding:22px 26px;margin:24px 0;font-size:14px;line-height:1.9}.semantic-card .sc-label{font-family:var(--mono);color:var(--green-deep);font-size:10.5px;letter-spacing:.14em;display:block;margin-bottom:8px}.snippet-card{font-family:var(--mono);background:var(--ink);color:#E7EAF1;border-radius:0;padding:22px 26px;margin:24px 0;font-size:13.5px;line-height:1.9;overflow-x:auto;white-space:pre-wrap}footer{margin-top:96px;padding-top:24px;border-top:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--ink-soft);letter-spacing:.05em;line-height:2}`;

const item = (q, decision, failure, evidence, followups) => ({ q, decision, failure, evidence, followups });

const pages = [
  {
    id: "engineering-frontend-core-qa",
    title: "프론트엔드 핵심 Q&A",
    source: "프론트엔드 핵심",
    subtitle: "브라우저 런타임, UI 계약, 접근성, 상태, 네트워크 경계를 구술로 방어하는 훈련 페이지입니다.",
    questions: [
      item("프론트엔드의 책임을 어떻게 정의하나요?", "프론트엔드는 화면을 그리는 계층이 아니라 사용자 의도를 안전한 상태 전이와 서버 계약으로 연결하는 runtime boundary입니다. DOM 구조, 입력, 네트워크, 접근성, 성능, 오류 복구를 하나의 제품 계약으로 다룹니다.", "컴포넌트 구현만 말하면 loading, empty, error, permission denied, offline, stale data가 빠져 실제 사용자 흐름에서 깨집니다.", "screen state matrix, API contract, accessibility tree, RUM metric", [{ q: "UI와 API 계약 중 무엇을 먼저 고정하나요?", answer: "사용자 여정의 상태 행렬을 먼저 고정하고 그 상태를 만들 수 있는 API 응답 계약을 맞춥니다. loading, empty, error, permission denied, stale data가 화면에 어떻게 드러나는지 정해야 필드의 required/nullable, error code, pagination 같은 서버 계약도 안정됩니다." }, { q: "상태가 많아지면 어디에 모델링하나요?", answer: "일시적인 입력과 open 상태는 컴포넌트에 두고, 공유 가능한 필터·탭·페이지는 URL에 두며, 서버에서 온 목록과 상세는 server cache에 둡니다. 권한, offline, optimistic update처럼 경계를 넘는 상태는 별도 상태 전이표로 소유자와 만료 조건을 적습니다." }, { q: "화면 구현 완료를 어떤 증거로 판단하나요?", answer: "성공 화면 캡처만으로는 부족하고 상태별 스토리, API fixture, keyboard-only 경로, 접근성 tree, route별 RUM 이벤트가 있어야 합니다. 핵심 CTA가 느린 네트워크와 401/403에서도 복구 경로를 보이면 완료로 볼 수 있습니다." }]),
      item("브라우저 렌더링 파이프라인에서 비용 경계는 어디인가요?", "HTML 파싱, CSSOM, style 계산, layout, paint, composite 흐름으로 설명하고, 변경이 어느 단계까지 invalidation시키는지 기준으로 최적화합니다.", "layout을 반복 유발하거나 transform으로 해결할 수 있는 변화를 width/top 변경으로 처리하면 long task와 jank가 생깁니다.", "Performance trace, Layout/Paint event, layer border, frame chart", [{ q: "layout thrashing은 왜 발생하나요?", answer: "DOM을 읽고 쓰는 작업이 한 frame 안에서 번갈아 일어나면 브라우저가 최신 layout 값을 내기 위해 강제 계산을 반복합니다. 예를 들어 목록 item마다 offsetHeight를 읽고 바로 style을 바꾸면 style recalculation과 layout event가 연쇄로 늘어납니다." }, { q: "transform이 항상 좋은가요?", answer: "항상 좋지는 않습니다. transform과 opacity는 layout을 덜 건드릴 수 있지만 새 layer를 만들면 GPU memory와 composite 비용이 늘고, 텍스트 선명도나 hit area가 어긋날 수 있어 Performance trace와 layer border로 확인합니다." }, { q: "paint와 composite를 어떻게 구분하나요?", answer: "paint는 픽셀을 다시 그리는 단계이고 composite는 이미 그려진 layer를 합성하는 단계입니다. DevTools Performance에서 Paint event, layer 변화, frame chart를 함께 보면 색상·그림자 변경인지 layer 이동인지 구분할 수 있습니다." }]),
      item("접근성을 기능 완료 기준에 어떻게 넣나요?", "semantic HTML, landmark, heading order, accessible name, keyboard path, focus management, screen reader announcement를 acceptance criteria로 둡니다.", "마우스로만 확인하면 keyboard trap, focus loss, 잘못된 aria, live region 누락이 출시 후 발견됩니다.", "axe result, keyboard-only recording, screen reader smoke test, DOM snapshot", [{ q: "button 대신 div를 쓰면 무엇이 빠지나요?", answer: "button의 기본 focus, Enter/Space activation, disabled 의미, accessible name 계산이 빠집니다. div로 대체하면 role, tabIndex, key handler, focus style, aria-disabled를 직접 맞춰야 하므로 보통 native button을 쓰는 편이 안전합니다." }, { q: "aria-label은 언제 위험한가요?", answer: "보이는 텍스트와 aria-label이 다르면 스크린리더와 화면 사용자가 서로 다른 이름을 듣고 보게 됩니다. 번역 누락이나 상태 미반영도 생기므로 아이콘 단독 버튼처럼 시각 이름이 없을 때만 쓰고 accessibility tree로 확인합니다." }, { q: "모달 닫힌 뒤 focus는 어디로 가야 하나요?", answer: "대부분 모달을 연 trigger로 돌아가야 합니다. trigger가 삭제되었거나 다음 작업이 명확하면 성공 메시지 heading이나 오류 필드로 보내되, Tab 순서가 body로 빠지지 않는지 keyboard recording으로 검증합니다." }]),
      item("상태 관리는 어떻게 선택하나요?", "상태의 소유자, 수명, 공유 범위, 서버 동기화 여부로 local state, URL state, external store, server cache를 나눕니다.", "모든 상태를 전역 store에 넣으면 stale data, 불필요한 rerender, 테스트 어려움, undo/redo 혼선이 커집니다.", "state ownership map, render count, URL restore test, cache invalidation log", [{ q: "서버 상태와 클라이언트 상태는 왜 다르나요?", answer: "서버 상태는 원본 소유자가 서버라 stale, refetch, invalidation, optimistic reconcile이 필요합니다. 클라이언트 상태는 입력값, hover, modal open처럼 브라우저 세션 안에서만 의미가 있어 서버 cache와 같은 규칙으로 다루면 과도하게 복잡해집니다." }, { q: "URL에 어떤 상태를 넣어야 하나요?", answer: "공유와 복원이 필요한 검색어, 필터, 정렬, 페이지, 선택된 탭은 URL에 둡니다. 커서 위치, draft 입력, dropdown open처럼 순간적인 UI 상태는 URL에 넣으면 history가 오염되고 뒤로가기 의미가 흐려집니다." }, { q: "전역 상태가 필요한 신호는 무엇인가요?", answer: "여러 route에서 같은 상태를 읽고 쓰며, refresh나 권한 변경에 맞춰 일관되게 갱신해야 하면 전역 상태 후보입니다. 단순 prop drilling 불편만으로 전역화하면 render 범위가 넓어지고 stale data 원인이 숨습니다." }]),
      item("loading, empty, error 상태는 왜 별도로 설계하나요?", "각 상태는 사용자의 다음 행동과 복구 경로가 다릅니다. skeleton, empty action, retry, permission 안내, partial data를 명확히 나눠야 합니다.", "성공 화면만 만들면 네트워크 실패와 권한 실패가 모두 빈 화면으로 보이고 support cost가 늘어납니다.", "state story, error fixture, retry log, visual regression capture", [{ q: "empty와 error를 어떻게 구분하나요?", answer: "empty는 요청이 성공했고 표시할 데이터가 없는 상태이며, error는 요청이나 권한, 파싱, 네트워크가 실패한 상태입니다. empty에는 생성이나 필터 초기화 action을 주고, error에는 재시도·문의용 traceId·권한 안내를 줍니다." }, { q: "부분 성공은 어떻게 보여주나요?", answer: "성공한 데이터는 유지하되 실패한 영역을 독립적으로 표시합니다. 대시보드 카드 일부만 실패했다면 전체 화면을 error로 바꾸지 않고 카드별 retry와 마지막 갱신 시간을 보여주는 편이 사용자의 작업을 덜 막습니다." }, { q: "재시도 버튼은 언제 숨기나요?", answer: "권한 없음, 잘못된 입력, 삭제된 리소스처럼 같은 요청을 반복해도 성공 가능성이 낮으면 숨기거나 다른 행동을 제공합니다. network error, 5xx, timeout처럼 일시 실패 가능성이 있으면 retry를 두고 중복 요청 방지를 같이 처리합니다." }]),
      item("Form 설계에서 가장 먼저 보는 것은 무엇인가요?", "입력 normalize, validation timing, error placement, submit idempotency, dirty state, browser autofill, IME 조합을 먼저 봅니다.", "onChange 검증만으로 처리하면 IME, paste, autofill, async validation, double submit에서 깨집니다.", "form state diagram, validation fixture, double submit test, IME test", [{ q: "client validation과 server validation은 왜 둘 다 필요한가요?", answer: "client validation은 즉시 피드백과 불필요한 요청 감소를 담당하고, server validation은 신뢰 경계에서 최종 데이터 무결성을 보장합니다. 브라우저 우회, 오래된 번들, 권한 변경이 있으므로 서버 오류 코드를 필드 오류로 다시 매핑해야 합니다." }, { q: "submit 중 버튼을 disable하면 충분한가요?", answer: "충분하지 않습니다. Enter 제출, 네트워크 재전송, 탭 중복, 느린 응답이 있을 수 있어 pending 상태와 request id, 서버 멱등성 키, 성공 후 중복 navigation 처리가 같이 필요합니다." }, { q: "필드 오류와 전역 오류는 어떻게 나누나요?", answer: "필드 오류는 사용자가 특정 입력을 고치면 해결되는 문제에 붙입니다. 인증 만료, 서버 장애, 결제 실패처럼 폼 전체 흐름이나 외부 상태가 원인인 경우는 전역 오류로 보여주고 recovery action을 분리합니다." }]),
      item("컴포넌트 분리는 어떤 기준으로 하나요?", "파일 크기가 아니라 책임, state ownership, side effect, 재사용 압력, 테스트 경계를 기준으로 분리합니다.", "presentational/container 구분을 기계적으로 적용하면 prop drilling이나 숨은 side effect가 생기고, 반대로 거대한 컴포넌트는 변경 blast radius가 커집니다.", "component responsibility table, story coverage, unit test boundary, dependency graph", [{ q: "재사용 컴포넌트는 언제 만들면 안 되나요?", answer: "사용처가 둘뿐인데 요구가 서로 다르거나 접근성 규칙이 안정되지 않았으면 일반화하지 않는 편이 낫습니다. premature abstraction은 variant 폭발과 예외 prop을 만들기 때문에 먼저 반복되는 상태와 API 모양을 확인합니다." }, { q: "hook으로 빼면 항상 좋아지나요?", answer: "항상 좋아지지 않습니다. hook은 상태와 side effect 재사용에는 좋지만 UI 계약을 숨기거나 호출 순서 제약을 만들 수 있습니다. DOM 접근, subscription, async race를 포함하면 cleanup과 테스트 경계도 같이 설계해야 합니다." }, { q: "컴포넌트 API는 어떻게 안정화하나요?", answer: "필수 상태, 접근성 invariant, 이벤트 payload, controlled/uncontrolled 여부를 문서화하고 Storybook 상태별 예제로 고정합니다. 외부 사용처가 의존할 prop 이름과 의미는 breaking change 정책으로 관리합니다." }]),
      item("라우팅 상태와 화면 상태는 어떻게 나누나요?", "공유 가능한 탐색 상태는 URL에 두고, 일시적 입력·hover·open 상태는 컴포넌트에 둡니다. 검색, 필터, 페이지, 탭은 복원 가능성이 중요합니다.", "필터를 local state에만 두면 새로고침/공유/뒤로가기에서 사용자가 같은 화면으로 돌아오지 못합니다.", "URL contract, back-forward test, deep link smoke test, analytics page_view", [{ q: "modal state를 URL에 넣어야 할 때는?", answer: "상세 보기, 초대 승인, 결제 단계처럼 공유·새로고침·뒤로가기가 제품 의미를 가지면 URL에 넣습니다. 단순 tooltip이나 임시 설정 panel처럼 페이지 맥락 안에서만 의미가 있으면 local state가 맞습니다." }, { q: "query param 변경이 너무 잦으면?", answer: "입력 중에는 local draft로 관리하고 commit 시점에 URL을 갱신합니다. 검색어는 debounce나 제출 시점, slider는 적용 버튼 등으로 history entry가 과도하게 쌓이지 않게 replace와 push 기준을 나눕니다." }, { q: "뒤로가기 동작은 어떻게 검증하나요?", answer: "필터 변경, 페이지 이동, modal open/close, form dirty 상태를 포함한 back-forward 시나리오를 Playwright로 확인합니다. URL, 화면 상태, focus, analytics page_view가 같은 의미로 움직이는지 봅니다." }]),
      item("디자인 시스템 컴포넌트를 사용할 때 무엇을 검토하나요?", "variant, size, disabled/loading/error state, keyboard interaction, token 사용, escape hatch, breaking change 정책을 봅니다.", "디자인 시스템을 우회한 ad hoc 스타일이 늘면 브랜드 일관성뿐 아니라 접근성, dark mode, density 대응이 무너집니다.", "component contract, token diff, Storybook states, visual regression", [{ q: "variant가 너무 많아지면 어떻게 줄이나요?", answer: "시각 이름이 아니라 제품 의도를 기준으로 합칩니다. primary, danger, ghost처럼 의미가 겹치면 사용 빈도와 접근성 contrast를 보고 제거하며, 일회성 색상은 token 예외로 남기지 않습니다." }, { q: "제품별 예외는 어디에 두나요?", answer: "컴포넌트 내부를 fork하기보다 token, slot, composition 같은 명시된 확장 지점에 둡니다. 접근성이나 keyboard 동작을 바꾸는 예외는 디자인 시스템 계약을 깨므로 별도 컴포넌트로 분리해 검토합니다." }, { q: "토큰 변경의 영향은 어떻게 확인하나요?", answer: "색, spacing, typography, motion token 변경은 Storybook 상태별 screenshot과 핵심 화면 visual regression으로 확인합니다. contrast, density, dark mode, mobile overflow가 함께 바뀌는지 보는 것이 중요합니다." }]),
      item("데이터 fetching 위치를 어떻게 정하나요?", "페이지 진입에 필요한 데이터는 route/page boundary에서, 사용자 조작 후 필요한 데이터는 interaction boundary에서 가져옵니다. prefetch와 cache key는 사용자 intent와 stale 허용치로 정합니다.", "하위 컴포넌트마다 fetch하면 waterfall, 중복 요청, loading 상태 분산, error 처리 누락이 생깁니다.", "network waterfall, cache key list, request dedupe metric, suspense boundary", [{ q: "prefetch는 언제 낭비가 되나요?", answer: "다음 행동 가능성이 낮거나 모바일 데이터 비용이 큰 화면에서 큰 payload를 미리 받으면 낭비입니다. hover prefetch도 touch 기기에는 의미가 약하므로 route 중요도, cache hit, 취소 가능성을 보고 제한합니다." }, { q: "staleTime은 어떻게 정하나요?", answer: "데이터 변경 빈도와 사용자가 오래된 값을 봤을 때의 비용으로 정합니다. 권한, 가격, 재고처럼 민감한 값은 짧게 두고, 문서나 프로필처럼 느리게 바뀌는 값은 길게 둘 수 있습니다." }, { q: "waterfall은 어디서 확인하나요?", answer: "DevTools Network waterfall과 framework trace에서 route loader, component fetch, image, script 요청 순서를 봅니다. 같은 cache key 중복, 하위 컴포넌트 지연 fetch, Suspense boundary 배치를 함께 확인합니다." }]),
      item("프론트엔드에서 time과 timezone은 어떻게 다루나요?", "저장은 UTC, 표시는 사용자 locale/timezone, 입력은 의도한 business timezone을 명시합니다. 상대 시간과 마감 시간은 서버 기준 clock과 drift를 고려합니다.", "브라우저 locale만 믿으면 DST, 해외 사용자, 서버 집계 기준이 엇갈려 날짜가 하루 밀리는 문제가 생깁니다.", "timezone fixture, DST test, server timestamp contract, locale snapshot", [{ q: "date-only 값은 UTC로 저장하면 안전한가요?", answer: "항상 안전하지 않습니다. 생일이나 영업일처럼 시간대와 무관한 date-only는 instant가 아니라 calendar date로 저장해야 합니다. UTC midnight으로 바꾸면 미국과 한국 사용자 사이에서 전날이나 다음날로 보일 수 있습니다." }, { q: "서버 시간이 필요한 이유는?", answer: "마감, 세션 만료, 할인 종료처럼 판정 기준이 필요한 기능은 클라이언트 clock을 믿으면 조작과 drift에 취약합니다. 서버 timestamp와 남은 시간을 내려받고 브라우저에서는 표시와 countdown만 담당하게 합니다." }, { q: "상대 시간 표시는 어떻게 테스트하나요?", answer: "현재 시각을 고정한 fixture로 방금, 1분 전, 하루 전, DST 전후, locale별 문구를 테스트합니다. 시간이 흐르며 hydration mismatch가 생기지 않도록 SSR 값과 client 갱신 시점도 확인합니다." }]),
      item("권한에 따라 UI를 숨기면 보안이 되나요?", "UI hide는 UX 편의일 뿐 보안 경계는 서버 인가입니다. 프론트엔드는 권한별 affordance와 오류 복구를 제공하고 서버 401/403을 정확히 처리해야 합니다.", "버튼을 숨겼다고 API 호출이 막히지 않으며, 캐시된 데이터나 URL 직접 접근에서 권한 누락이 드러납니다.", "permission matrix, 401/403 fixture, route guard test, server audit log", [{ q: "403과 404를 UI에서 어떻게 다루나요?", answer: "403은 리소스는 있지만 현재 사용자에게 권한이 없다는 복구 안내가 필요하고, 404는 리소스가 없거나 공개하지 않는다는 탐색 복구가 필요합니다. 보안상 존재 여부를 숨겨야 하는 API는 서버 계약에 맞춰 UI 문구를 조정합니다." }, { q: "권한 변경 후 캐시는 어떻게 무효화하나요?", answer: "권한 변경 이벤트나 401/403 응답을 받으면 사용자 scope의 query cache와 메뉴, route guard 데이터를 함께 invalidate합니다. 탭이 여러 개라면 BroadcastChannel이나 storage event로 logout과 permission refresh를 전파합니다." }, { q: "관리자 화면의 route guard는 충분한가요?", answer: "충분하지 않습니다. route guard는 잘못된 접근을 줄이는 UX 장치이고, 실제 인가는 API와 서버 action에서 매번 확인해야 합니다. deep link, 오래된 bundle, 캐시된 응답도 401/403 fixture로 검증합니다." }]),
      item("i18n을 나중에 붙이면 왜 어려워지나요?", "문장 조립, 숫자/날짜/통화, 복수형, 텍스트 길이, RTL 가능성을 컴포넌트 API와 레이아웃에 반영해야 합니다.", "한글/영문만 보고 고정 폭을 잡으면 독일어 길이, 아랍어 방향, plural rule, date format에서 UI가 깨집니다.", "locale snapshot, pseudo localization, overflow capture, ICU message lint", [{ q: "문자열 concat이 왜 위험한가요?", answer: "언어마다 어순, 조사, 복수형, 성별 규칙이 달라 조각을 이어 붙이면 자연스럽게 번역할 수 없습니다. ICU message처럼 변수와 조건을 포함한 문장 단위로 넘겨야 번역자가 맥락을 유지합니다." }, { q: "아이콘과 텍스트 순서는 어떻게 바뀌나요?", answer: "RTL에서는 inline 방향과 정렬, chevron 의미, 시작·끝 위치가 바뀔 수 있습니다. CSS logical property와 dir 속성을 사용하고 아이콘이 방향 의미를 갖는지 locale snapshot으로 확인합니다." }, { q: "번역 누락은 어떻게 검출하나요?", answer: "빌드 단계에서 key 누락과 미사용 key를 검사하고, pseudo localization으로 길이 증가와 깨진 placeholder를 찾습니다. 런타임 fallback 문구가 그대로 노출되는지도 error logging에 포함합니다." }]),
      item("프론트엔드 로그에는 무엇을 남겨야 하나요?", "사용자 식별 정보가 아니라 session/request id, route, feature, error code, recovery action, release version을 남깁니다. PII와 token은 redaction합니다.", "console.log 수준으로 남기면 운영에서 집계할 수 없고, 반대로 payload를 그대로 보내면 개인정보 유출이 됩니다.", "client log schema, redaction test, sourcemap release id, error dashboard", [{ q: "client error와 server error를 어떻게 연결하나요?", answer: "API 응답의 requestId나 traceId를 client log에 함께 남겨 같은 실패를 서버 로그와 묶습니다. route, release version, user action, network status도 포함하면 프론트 오류와 백엔드 오류를 구분하기 쉽습니다." }, { q: "PII redaction은 어디서 하나요?", answer: "로그 전송 wrapper에서 schema 기반으로 email, phone, token, free-text input을 제거하거나 hash 처리합니다. 컴포넌트마다 조심하는 방식은 누락되기 쉬우므로 수집 경계에서 막고 테스트 fixture로 확인합니다." }, { q: "console error를 모두 수집하면 되나요?", answer: "그대로 모두 수집하면 extension noise와 PII 위험이 커집니다. source map release id, 오류 fingerprint, route, severity를 붙이고 known benign error와 third-party error를 분리해 sampling합니다." }]),
      item("hydration mismatch는 왜 발생하나요?", "서버가 만든 HTML과 클라이언트 첫 렌더 결과가 다를 때 발생합니다. 시간, random, browser-only API, locale, auth 상태를 SSR 경계에서 안정화해야 합니다.", "개발에서는 경고만 보이고 지나가도 실제로는 이벤트 연결, layout shift, SEO 품질에 영향을 줄 수 있습니다.", "hydration warning log, SSR snapshot, deterministic render test, Web Vitals CLS", [{ q: "window 접근은 어디서 해야 하나요?", answer: "SSR 렌더 중에는 window가 없으므로 브라우저 전용 값은 effect, client-only boundary, lazy initialization 안에서 읽습니다. 첫 HTML에 영향을 주는 값이면 서버에서 동일한 값을 주입하거나 hydration 전 placeholder를 고정합니다." }, { q: "random id는 어떻게 안정화하나요?", answer: "React의 useId처럼 SSR과 client가 같은 순서로 생성하는 API를 쓰거나 서버에서 id를 내려줍니다. Math.random, Date.now로 markup id를 만들면 label-for 연결과 hydration 결과가 달라질 수 있습니다." }, { q: "auth 상태는 SSR에서 어떻게 다루나요?", answer: "쿠키나 세션으로 서버에서 초기 auth 상태를 판단해 HTML과 client bootstrap data를 맞춥니다. client에서만 auth를 알 수 있다면 권한 있는 콘텐츠를 SSR로 노출하지 않고 loading 또는 anonymous shell을 고정합니다." }]),
      item("Error Boundary는 무엇을 해결하고 무엇을 못 하나요?", "렌더링 중 발생한 React subtree 오류를 격리하고 fallback을 보여줍니다. async handler, server error, event handler 오류는 별도 처리와 logging이 필요합니다.", "Error Boundary만 두고 data error를 throw 처리하지 않으면 사용자에게 복구 버튼이나 원인 코드가 전달되지 않습니다.", "boundary placement map, fallback story, error reporting event, retry fixture", [{ q: "boundary를 너무 넓게 두면?", answer: "작은 widget 오류가 전체 route fallback으로 바뀌어 사용자가 다른 정상 영역까지 잃습니다. 결제, grid, sidebar처럼 독립 복구가 가능한 영역은 boundary를 나누고 공통 shell은 유지하는 편이 좋습니다." }, { q: "event handler 오류는 어떻게 잡나요?", answer: "React Error Boundary는 event handler 안의 예외를 자동으로 잡지 않습니다. handler 내부 try/catch, promise rejection 처리, error reporting wrapper를 두고 사용자에게는 실패 toast나 inline error를 보여줘야 합니다." }, { q: "fallback에서 어떤 정보를 보여주나요?", answer: "사용자가 할 수 있는 재시도, 이전 화면 이동, 문의용 오류 코드, 영향을 받은 영역을 보여줍니다. stack trace나 민감한 payload는 숨기고, logging에는 release id와 boundary 이름을 남깁니다." }]),
      item("프론트엔드 PR에서 어떤 증거를 남겨야 하나요?", "주요 state screenshot, keyboard path, network trace, performance before/after, test result, rollout/rollback 조건을 남깁니다.", "코드 diff만 있으면 리뷰어가 사용자 흐름, 성능 변화, 접근성 회귀를 재현하기 어렵습니다.", "PR evidence packet, Playwright trace, Lighthouse/Web Vitals, visual diff", [{ q: "작은 UI 변경에도 증거가 필요한가요?", answer: "위험이 낮은 copy 변경은 간단한 screenshot이면 충분할 수 있지만, 버튼, form, route, auth, analytics에 닿으면 상태별 증거가 필요합니다. 변경 크기보다 사용자 흐름과 실패 비용으로 증거 수준을 정합니다." }, { q: "성능 수치가 없으면 무엇을 남기나요?", answer: "수치가 없더라도 변경 전후 DOM 수, bundle diff, network waterfall, render count, 예상 영향 범위를 남깁니다. 성능에 닿는 변경이면 최소한 DevTools trace나 Web Vitals 관측 계획을 함께 적습니다." }, { q: "롤백 가능성은 어떻게 설명하나요?", answer: "feature flag로 끌 수 있는지, 이전 API 계약과 호환되는지, cache나 migration 때문에 되돌림이 막히는지 적습니다. release version, guardrail metric, 담당자도 함께 남기면 장애 대응이 빨라집니다." }]),
      item("서버 응답 스키마 변경에 프론트는 어떻게 대응하나요?", "optional/required, nullable, enum 확장, field removal, versioning을 타입과 runtime validation으로 방어합니다.", "TypeScript 타입만 믿으면 실제 API drift, null, unknown enum에서 런타임 UI가 깨집니다.", "contract test, schema diff, unknown enum fixture, runtime parser log", [{ q: "nullable과 optional은 왜 다른가요?", answer: "optional은 필드가 없을 수 있다는 뜻이고 nullable은 필드는 있지만 값이 null일 수 있다는 뜻입니다. UI에서는 기본값, 숨김, 명시적 빈 상태가 달라지므로 parser와 rendering fixture에서 따로 다뤄야 합니다." }, { q: "enum 값이 추가되면 어떻게 하나요?", answer: "unknown enum을 안전한 fallback label과 telemetry로 처리해야 합니다. switch default에서 throw만 하면 새 서버 값 배포 순간 화면이 깨지므로, 미지원 상태를 표시하고 schema diff를 추적합니다." }, { q: "GraphQL이면 문제가 사라지나요?", answer: "사라지지 않습니다. GraphQL도 nullable, union, enum 확장, resolver 오류, client cache drift가 있습니다. fragment와 generated type을 쓰더라도 runtime error와 partial data 상태를 UI에 매핑해야 합니다." }]),
      item("브라우저 저장소는 어떻게 고르나요?", "수명, 민감도, 동기/비동기 API, 용량, cross-tab 동기화 기준으로 memory, sessionStorage, localStorage, IndexedDB, cookie를 고릅니다.", "access token을 localStorage에 두거나 대용량 데이터를 동기 storage에 넣으면 보안과 main thread 성능 문제가 생깁니다.", "storage policy, XSS threat model, quota test, cross-tab sync test", [{ q: "cookie가 항상 안전한가요?", answer: "항상 안전하지 않습니다. httpOnly cookie는 JS 탈취를 줄이지만 CSRF, SameSite, Secure, domain/path 설정이 맞아야 합니다. 민감 데이터 자체를 cookie에 넣기보다 세션 식별자와 서버 검증으로 제한합니다." }, { q: "IndexedDB는 언제 쓰나요?", answer: "대용량 구조화 데이터, offline queue, draft, binary cache처럼 비동기 저장과 용량이 필요한 경우에 씁니다. 단순 feature flag나 작은 UI 설정은 복잡도를 고려해 memory, cookie, localStorage와 비교합니다." }, { q: "로그아웃 때 무엇을 지워야 하나요?", answer: "access/session 관련 memory state, server cache, IndexedDB draft 중 사용자 scope 데이터, localStorage 설정, BroadcastChannel 상태를 정리합니다. 여러 탭이 열려 있으면 logout event를 전파해 stale 권한 화면을 닫아야 합니다." }]),
      item("웹소켓이나 SSE를 도입할 때 무엇을 보나요?", "실시간성 요구, 재연결, backoff, ordering, missed event replay, auth refresh, tab visibility를 봅니다.", "연결만 열면 끝이라고 보면 네트워크 전환, 중복 이벤트, 오래된 토큰, hidden tab 리소스 낭비에서 깨집니다.", "connection state machine, reconnect log, event cursor, stale token fixture", [{ q: "SSE와 WebSocket 선택 기준은?", answer: "서버에서 클라이언트로 단방향 이벤트를 보내면 SSE가 단순하고 HTTP 친화적입니다. 양방향 저지연 조작, presence, 협업 편집처럼 client 메시지가 많으면 WebSocket을 고려합니다." }, { q: "놓친 이벤트는 어떻게 복구하나요?", answer: "event id나 cursor를 저장하고 재연결 시 마지막 처리 지점 이후를 replay합니다. replay가 불가능하면 snapshot refetch로 상태를 수렴시키고 중복 이벤트는 idempotent reducer로 처리합니다." }, { q: "토큰 만료 중 연결은 어떻게 되나요?", answer: "연결이 401/close code로 종료되면 refresh를 시도하고 성공 후 cursor 기준으로 재연결합니다. refresh 실패는 logout 또는 권한 오류 UI로 수렴시키고 무한 reconnect loop를 막습니다." }]),
      item("feature flag를 프론트에서 어떻게 운영하나요?", "flag는 rollout, experiment, kill switch, permission을 구분하고 default, cache, exposure logging, stale flag 제거 정책을 둡니다.", "flag가 권한처럼 사용되거나 제거되지 않으면 복잡도가 누적되고 사용자별 UI 불일치가 생깁니다.", "flag inventory, exposure event, kill switch drill, stale flag cleanup PR", [{ q: "flag 기본값은 무엇으로 두나요?", answer: "네트워크 실패나 SSR 누락 때 사용자에게 더 안전한 쪽으로 둡니다. 결제나 삭제 같은 위험 기능은 off가 기본이고, 이미 공개된 핵심 기능은 fallback UI가 유지되도록 기본값을 정합니다." }, { q: "SSR에서 flag는 어떻게 주입하나요?", answer: "서버에서 평가한 flag snapshot을 HTML bootstrap data로 내려 client 첫 렌더와 맞춥니다. client에서 다시 평가할 때 값이 바뀌면 hydration mismatch와 layout shift가 생길 수 있어 rollout key와 cache 시간을 명확히 둡니다." }, { q: "권한과 flag는 왜 다르나요?", answer: "권한은 사용자가 행동할 수 있는 보안·비즈니스 규칙이고 서버가 최종 판단합니다. flag는 배포와 실험을 조절하는 운영 장치라서 flag가 켜져도 서버 인가가 없으면 action은 실패해야 합니다." }]),
      item("파일 업로드 UI는 무엇이 어렵나요?", "파일 크기/타입 검증, preview memory, progress, cancel, retry, direct upload URL 만료, 바이러스 검사 상태를 포함해야 합니다.", "input만 붙이면 대용량 파일, 중단된 네트워크, 중복 업로드, object URL leak, server scan pending에서 문제가 납니다.", "upload state machine, cancel test, object URL cleanup, server scan status fixture", [{ q: "확장자 검증만으로 충분한가요?", answer: "충분하지 않습니다. 확장자는 쉽게 바꿀 수 있으므로 MIME, magic byte, 서버 측 스캔과 크기 제한이 필요합니다. 프론트 검증은 빠른 피드백이고 신뢰 경계는 서버에 둡니다." }, { q: "progress 100%와 처리 완료는 같은가요?", answer: "다릅니다. progress 100%는 브라우저가 bytes 전송을 끝냈다는 뜻이고, 서버 저장, 변환, 바이러스 검사, metadata 생성은 아직 진행 중일 수 있습니다. UI는 uploaded와 processing, ready 상태를 분리해야 합니다." }, { q: "업로드 취소는 서버에도 전달해야 하나요?", answer: "가능하면 전달해야 합니다. direct upload나 multipart upload는 client abort만으로 서버 임시 파일이 사라지지 않을 수 있어 cancel endpoint, multipart abort, cleanup job을 함께 둡니다." }]),
      item("테이블이나 그리드 화면은 어떤 계약이 필요하나요?", "정렬/필터/페이지, column visibility, row identity, selection persistence, virtual scroll, inline edit validation을 명시해야 합니다.", "index를 row key로 쓰거나 selection을 화면 순서에 묶으면 정렬/필터 후 잘못된 행이 수정됩니다.", "row id contract, grid interaction test, virtualization capture, edit rollback fixture", [{ q: "row key는 왜 안정적이어야 하나요?", answer: "정렬, 필터, pagination, realtime update 후에도 같은 데이터를 같은 행으로 인식해야 selection과 inline edit가 안전합니다. index key를 쓰면 화면 순서가 바뀔 때 다른 사용자의 행에 편집 상태가 붙을 수 있습니다." }, { q: "가상 스크롤에서 접근성은?", answer: "DOM에 일부 row만 존재하므로 screen reader가 전체 행 수, 현재 위치, keyboard navigation을 이해하도록 aria-rowcount, aria-rowindex, focus management를 보완해야 합니다. 중요한 데이터는 export나 non-virtual fallback도 검토합니다." }, { q: "inline edit 실패는 어떻게 복구하나요?", answer: "서버 실패 시 원래 값으로 되돌리거나 오류 상태를 cell에 유지하고 재시도·취소를 제공합니다. optimistic update를 했다면 row version과 validation message를 이용해 충돌과 권한 실패를 구분합니다." }]),
      item("모바일 웹 대응에서 무엇을 먼저 확인하나요?", "viewport, safe area, touch target, virtual keyboard, scroll locking, network quality, reduced data를 봅니다.", "데스크톱 기준 레이아웃만 줄이면 키보드가 input을 가리고, fixed footer와 주소창 변화로 CTA가 사라집니다.", "mobile viewport screenshot, touch target audit, keyboard overlay test, RUM by device", [{ q: "100vh가 모바일에서 위험한 이유는?", answer: "모바일 브라우저 주소창과 toolbar가 접히고 펼쳐지면서 실제 viewport 높이가 변합니다. 100vh에 fixed CTA를 맞추면 가상 키보드나 safe area에 가려질 수 있어 dvh/svh/lvh와 keyboard overlay를 함께 확인합니다." }, { q: "터치 타겟 크기는 어떻게 잡나요?", answer: "손가락 입력 오차와 한 손 사용을 고려해 충분한 hit area와 간격을 둡니다. 시각 아이콘이 작아도 button padding으로 target을 키우고, 가까운 destructive action은 accidental tap 방지를 넣습니다." }, { q: "모바일 성능은 데스크톱과 무엇이 다르나요?", answer: "CPU, 메모리, 네트워크, 배터리, thermal throttling이 더 제한적입니다. desktop trace가 좋아도 저사양 Android의 INP, image decode, JS parse time, scroll FPS를 따로 봐야 합니다." }]),
      item("프론트엔드에서 race condition은 어떻게 생기나요?", "빠른 입력, route 전환, 중복 요청, 오래된 응답, optimistic update 실패에서 생깁니다. request id, abort, cache version, mutation queue로 제어합니다.", "마지막으로 도착한 응답을 무조건 반영하면 사용자가 현재 보는 필터와 다른 데이터가 화면에 표시됩니다.", "stale response fixture, AbortController test, mutation log, cache version trace", [{ q: "AbortController는 서버 작업도 취소하나요?", answer: "브라우저 요청 소비를 중단하고 연결을 끊을 수는 있지만 서버 작업이 이미 시작되었다면 자동으로 롤백되지는 않습니다. 서버가 cancellation signal이나 idempotency key를 지원하는지 확인해야 합니다." }, { q: "optimistic update 실패는 어떻게 되돌리나요?", answer: "변경 전 snapshot이나 inverse patch를 저장해 실패 시 cache를 복구하고 사용자에게 원인과 재시도 행동을 보여줍니다. 여러 mutation이 겹치면 queue와 entity version으로 순서를 맞춰야 합니다." }, { q: "검색 입력은 debounce만 하면 충분한가요?", answer: "충분하지 않습니다. debounce는 요청 수를 줄일 뿐 오래된 응답이 나중에 도착하는 문제를 막지 못합니다. query key, request id, AbortController, 현재 입력값 비교로 stale response 반영을 막아야 합니다." }]),
      item("컴포넌트 API에서 children과 render prop은 언제 쓰나요?", "구조를 호출자가 제어해야 하면 children, 내부 상태를 공유하며 렌더링을 위임해야 하면 render prop을 고려합니다.", "과도하게 유연한 API는 사용처마다 접근성과 레이아웃 책임이 흩어져 디자인 시스템 품질을 떨어뜨립니다.", "usage examples, a11y invariant test, API review note, breaking change policy", [{ q: "compound component는 언제 적합한가요?", answer: "Tabs, Menu, Dialog처럼 여러 하위 요소가 한 상태와 keyboard pattern을 공유할 때 적합합니다. 내부 context로 selection과 focus를 관리하되 role, aria 연결, 필수 child 누락을 개발 모드에서 경고합니다." }, { q: "slot API의 위험은?", answer: "slot이 너무 열려 있으면 사용처가 접근성 필수 요소나 layout 제약을 깨기 쉽습니다. header, trigger, item처럼 의미가 분명한 slot만 열고, dangerous escape hatch는 리뷰 기준을 둡니다." }, { q: "유연성과 일관성은 어떻게 균형 잡나요?", answer: "스타일 자유도보다 interaction과 접근성 invariant를 먼저 고정합니다. variant와 slot은 제품에서 반복되는 차이를 수용하는 수준으로 제한하고, 임의 DOM 교체가 필요하면 별도 컴포넌트로 분리합니다." }]),
      item("프론트엔드에서 보이는 버그와 실제 원인을 어떻게 연결하나요?", "증상을 DOM, network, state, render, backend response, browser compatibility로 분해하고 재현 fixture를 고정합니다.", "화면 캡처만 보고 CSS부터 바꾸면 데이터 race나 API contract 오류를 가릴 수 있습니다.", "repro steps, HAR, React Profiler, DOM snapshot, browser matrix", [{ q: "재현이 안 되는 버그는 어떻게 추적하나요?", answer: "release version, browser, device, route, feature flag, network status, requestId를 로그에 남겨 조건을 좁힙니다. session replay가 있다면 PII masking 범위 안에서 DOM 변화와 API 실패를 함께 봅니다." }, { q: "브라우저별 차이는 어디서 확인하나요?", answer: "browser matrix에 따라 Safari/iOS WebView/Firefox/Chrome에서 같은 fixture를 실행하고, caniuse와 MDN compat로 API 지원을 확인합니다. CSS layout, input, storage, media 정책은 브라우저 차이가 자주 납니다." }, { q: "사용자 세션 로그는 어디까지 봐야 하나요?", answer: "문제 해결에 필요한 route, action, error code, timing, requestId까지만 봅니다. 입력 원문, token, 민감한 화면 내용은 redaction하고 접근 권한과 보존 기간을 제한해야 합니다." }]),
      item("프론트엔드 핵심 답변에서 시니어와 주니어의 차이는 무엇인가요?", "시니어 답변은 사용자 흐름, 브라우저 비용, 서버 계약, 접근성, 관측성, 롤백까지 연결합니다. 주니어 답변은 라이브러리 API와 성공 경로에 머무르는 경우가 많습니다.", "실패 상태와 검증 증거를 말하지 못하면 외부 검증에서 실제 운영 가능성을 방어하기 어렵습니다.", "FRONTEND QA TRAINING PACKET, PR evidence, release health window, incident note", [{ q: "경험이 없는 영역은 어떻게 답하나요?", answer: "직접 운영한 범위와 설계로 아는 범위를 분리해 말합니다. 예를 들어 WebSocket 경험이 적다면 reconnect, cursor replay, auth refresh를 어떤 fixture로 검증할지 설명해 추정과 사실을 구분합니다." }, { q: "트레이드오프를 어떻게 짧게 말하나요?", answer: "선택지, 얻는 것, 잃는 것, 검증 방법 순서로 말합니다. 예를 들어 client cache를 늘리면 network는 줄지만 stale 권한 위험이 커지므로 invalidation과 403 fixture가 필요하다고 압축합니다." }, { q: "검증 증거를 하나만 고르면 무엇인가요?", answer: "사용자 핵심 흐름을 담은 Playwright trace나 상태별 fixture를 고릅니다. 화면, network, console, timing을 함께 보여주므로 접근성이나 성능 전문 지표가 없을 때도 운영 가능한 근거가 됩니다." }]),
    ],
  },
  {
    id: "engineering-frontend-interaction-qa",
    title: "프론트엔드 인터랙션 Q&A",
    source: "프론트엔드 인터랙션",
    subtitle: "포인터, 키보드, focus, undo, optimistic UI, 복잡한 조작 흐름을 상태 기계로 답하는 훈련 페이지입니다.",
    questions: [
      item("좋은 인터랙션 설계의 출발점은 무엇인가요?", "이벤트 핸들러가 아니라 사용자의 의도, 상태, 전이, 취소, 실패 복구를 먼저 모델링합니다. idle, armed, active, committing, failed 같은 상태가 있어야 테스트와 접근성이 붙습니다.", "click handler만 구현하면 double submit, pointercancel, route change, stale response에서 상태가 꼬입니다.", "interaction state machine, transition table, QA scenario, accessibility acceptance", [{ q: "상태 기계가 과한 경우는?", answer: "hover 색상처럼 전이가 두세 개이고 실패나 비동기 복구가 없으면 명시적 상태 기계까지는 과합니다. 반대로 drag, wizard, optimistic mutation처럼 pointer, keyboard, network, route 전환이 함께 걸리면 idle/active/committing/failed를 전이표로 두는 편이 QA fixture를 만들기 쉽습니다." }, { q: "전이를 어디에 문서화하나요?", answer: "컴포넌트 근처에는 상태 이름과 이벤트를 코드 상수나 reducer로 두고, 제품 문서에는 사용자 행동별 전이표를 둡니다. 예를 들어 `pointerdown -> armed`, `Escape -> canceled`, `mutation reject -> failed`처럼 써야 keyboard test와 analytics result event가 같은 언어를 씁니다." }, { q: "실패 상태는 화면에 어떻게 드러나야 하나요?", answer: "실패 상태는 사용자가 다음 행동을 선택할 수 있게 보여야 합니다. optimistic 변경은 원래 값으로 되돌리거나 retry/undo를 제공하고, focus는 오류 메시지나 실패한 컨트롤로 이동하며, QA fixture에는 409, 403, timeout, stale response를 각각 넣습니다." }]),
      item("drag and drop에서 가장 위험한 부분은 무엇인가요?", "pointer lifecycle, keyboard 대체 조작, drop target 계산, scroll container, 취소/rollback을 함께 설계해야 합니다.", "마우스 기준으로만 만들면 touch, pen, keyboard, iframe, pointercancel에서 조작이 끊기고 접근성 검증을 통과하지 못합니다.", "pointer trace, keyboard DnD test, drop target fixture, rollback scenario", [{ q: "pointer capture는 왜 쓰나요?", answer: "드래그 중 포인터가 원래 요소 밖으로 나가도 move/up 이벤트를 같은 요소에서 받기 위해 씁니다. capture를 쓰면 iframe 경계, pointercancel, lostpointercapture를 함께 처리해야 하며, 취소 시 ghost와 선택 상태를 rollback하는 fixture가 필요합니다." }, { q: "드래그 중 스크롤은 어떻게 처리하나요?", answer: "scroll container의 edge auto-scroll, touch에서의 page scroll 충돌, sticky header offset을 별도로 계산합니다. 드래그 좌표는 viewport가 아니라 container 기준으로 보정하고, Playwright나 pointer trace로 스크롤 중 drop target이 바뀌는 케이스를 검증합니다." }, { q: "키보드 사용자는 어떻게 재정렬하나요?", answer: "grab 상태를 Space나 Enter로 토글하고 Arrow로 위치를 이동한 뒤 다시 Space/Enter로 확정하게 합니다. 이동 결과는 aria-live로 짧게 알리고 focus는 이동한 item에 유지하며, 같은 state machine을 keyboard DnD test fixture로 돌립니다." }]),
      item("focus management의 완료 기준은 무엇인가요?", "focus는 사용자의 현재 작업 위치입니다. modal, popover, route change, validation error, async content 삽입 뒤 focus 이동과 복귀 위치를 명시합니다.", "DOM이 바뀌었는데 focus가 body로 빠지면 keyboard 사용자와 screen reader 사용자가 흐름을 잃습니다.", "focus path test, tab order recording, screen reader smoke, modal fixture", [{ q: "focus trap은 언제 필요한가요?", answer: "modal처럼 배경 조작을 막고 현재 결정에 머물러야 하는 UI에서 필요합니다. popover나 combobox는 trap보다 roving focus나 active descendant가 맞을 수 있으며, trap fixture는 Tab 순환, Shift+Tab, Escape, trigger 제거 케이스를 포함해야 합니다." }, { q: "닫힌 뒤 focus는 어디로 돌아가나요?", answer: "기본은 overlay를 연 trigger입니다. trigger가 삭제되었거나 route가 바뀌었으면 새 화면의 heading, 완료 메시지, 다음 가능한 action으로 보내고 body로 빠지지 않게 focus restoration test를 둡니다." }, { q: "validation error에 focus를 옮겨야 하나요?", answer: "submit 실패처럼 사용자가 즉시 수정해야 하는 오류라면 첫 오류 필드나 오류 summary로 focus를 옮깁니다. onChange 중 매번 focus를 빼앗으면 입력을 방해하므로, submit 시점과 async validation 완료 시점을 나눠 screen reader announcement를 확인합니다." }]),
      item("키보드 인터랙션은 어떻게 설계하나요?", "WAI-ARIA pattern을 참고해 Tab, Arrow, Enter, Space, Escape의 의미를 컴포넌트별로 고정합니다.", "브라우저 기본 동작과 충돌하거나 role만 바꾸고 key handling을 빼면 조작 가능한 듯 보이지만 실제로는 접근 불가 UI가 됩니다.", "keyboard spec, role/aria audit, Playwright keyboard test, screen reader note", [{ q: "Enter와 Space는 같은가요?", answer: "native button에서는 둘 다 activation이지만 text input에서는 Enter가 submit이나 선택 확정이고 Space는 문자 입력입니다. custom role을 쓰면 기본 동작을 잃기 쉬우므로 keydown/keyup 시점과 중복 click 발생 여부를 keyboard fixture로 확인합니다." }, { q: "Arrow navigation은 언제 쓰나요?", answer: "menu, tablist, grid, combobox처럼 한 composite widget 안에서 항목을 이동할 때 씁니다. 일반 페이지 탐색은 Tab 순서에 맡기고, roving tabindex나 aria-activedescendant를 선택해 focus 표시와 screen reader announcement가 맞는지 검증합니다." }, { q: "Escape는 무엇을 닫아야 하나요?", answer: "가장 안쪽의 열린 modal, popover, menu, drag armed 상태부터 닫아야 합니다. Escape가 route navigation이나 입력 취소와 충돌하는 경우 우선순위를 문서화하고, 닫은 뒤 focus가 trigger나 편집 중 필드로 돌아가는지 확인합니다." }]),
      item("optimistic UI는 언제 도입하나요?", "성공 확률이 높고 실패 복구가 명확하며 중복/순서 문제를 제어할 수 있을 때 사용합니다.", "실패 시 rollback, 서버 최종 상태 reconcile, 중복 mutation 처리 없이 쓰면 화면과 서버가 어긋납니다.", "mutation ledger, rollback fixture, server reconcile log, duplicate click test", [{ q: "좋아요 버튼과 결제 버튼은 왜 다르나요?", answer: "좋아요는 실패해도 원래 상태로 rollback하거나 retry하면 피해가 작지만, 결제는 외부 side effect와 금전 상태가 걸려 UI만 되돌리면 안 됩니다. 결제는 pending state, idempotency key, 서버 최종 결과 조회, 중복 제출 방지를 우선합니다." }, { q: "실패했을 때 toast만 띄우면 되나요?", answer: "아니요. optimistic 변경 자체를 rollback하거나 실패 상태로 고정해 사용자가 현재 서버 상태를 알 수 있어야 합니다. toast는 보조 알림이고, 버튼 상태, inline error, retry/undo action, analytics error result가 같이 남아야 합니다." }, { q: "동시 optimistic update는 어떻게 합치나요?", answer: "mutation ledger에 client id, 대상 entity, 순서, inverse patch를 남기고 서버 응답이 도착할 때 최신 pending 목록과 재계산합니다. 같은 row를 빠르게 수정하는 fixture와 stale response fixture로 늦은 응답이 최신 UI를 덮지 않는지 확인합니다." }]),
      item("undo 기능은 어떻게 설계하나요?", "되돌릴 수 있는 command와 되돌릴 수 없는 side effect를 분리하고, undo window, server commit timing, audit log를 정합니다.", "이미 외부 알림이나 결제가 나간 작업을 단순 UI undo로 처리하면 사용자는 취소됐다고 믿지만 시스템은 진행됩니다.", "command log, undo timeout, compensation API, audit event", [{ q: "undo와 cancel은 무엇이 다른가요?", answer: "cancel은 작업이 commit되기 전에 armed, editing, pending 상태를 중단하는 것이고 undo는 이미 적용된 command를 반대 command로 되돌리는 것입니다. 그래서 undo에는 audit log, compensation API, 만료 시간, analytics undo event가 필요합니다." }, { q: "server commit 후 undo는 어떻게 하나요?", answer: "서버가 inverse operation을 지원해야 합니다. 삭제는 soft delete로 복구하고, 이동은 이전 위치를 command log에 남기며, 외부 알림처럼 되돌릴 수 없는 side effect는 undo 대신 취소 가능 시간이나 confirmation을 둡니다." }, { q: "삭제 undo에서 데이터 보존 기간은?", answer: "undo window와 서버 보존 기간을 분리해 정합니다. UI에서는 5초 undo를 제공하더라도 서버는 감사와 복구 정책에 맞춰 soft delete 상태를 더 오래 보관할 수 있고, fixture는 window 만료 후 복구 버튼이 사라지는지를 봅니다." }]),
      item("toast는 어떤 정보를 담아야 하나요?", "결과, 영향 범위, 다음 행동, 복구 가능성을 짧게 알려야 합니다. 중요한 오류는 toast만으로 끝내지 않고 inline error나 persistent status를 둡니다.", "모든 오류를 toast로 처리하면 screen reader announcement, 재시도, 사용자가 놓친 오류 추적이 어렵습니다.", "toast policy, aria-live test, error persistence fixture, retry action log", [{ q: "성공 toast는 항상 필요한가요?", answer: "항상 필요하지 않습니다. 버튼 상태, inline saved marker, route 전환처럼 결과가 화면에 명확하면 toast를 줄이는 편이 낫습니다. 사용자가 배경 작업이나 bulk action 결과를 놓칠 수 있을 때만 영향 범위와 undo/retry를 담습니다." }, { q: "aria-live politeness는?", answer: "성공 저장, 검색 결과 수 변경처럼 흐름을 끊지 않아도 되는 내용은 polite가 맞습니다. 세션 만료, 위험한 실패처럼 즉시 알아야 하는 내용만 assertive를 쓰고, 같은 메시지가 반복 낭독되지 않게 live region fixture를 둡니다." }, { q: "toast queue가 쌓이면 어떻게 하나요?", answer: "같은 원인의 toast는 합치고, 우선순위와 최대 개수를 둔 뒤 오래된 정보는 persistent log나 notification center로 넘깁니다. bulk action은 item별 toast 100개 대신 성공/실패 집계와 실패 행 링크를 제공합니다." }]),
      item("modal과 drawer는 어떻게 구분하나요?", "modal은 현재 작업을 막고 결정을 요구할 때, drawer는 맥락을 유지한 보조 작업이나 상세 탐색에 적합합니다.", "모든 것을 modal로 만들면 deep link, mobile viewport, focus trap, history handling이 복잡해집니다.", "interaction pattern decision, focus trap test, mobile screenshot, route behavior", [{ q: "modal 안에 modal은 허용하나요?", answer: "가능하면 피하고 단일 modal 안에서 step이나 confirm 영역으로 풀어야 합니다. 꼭 필요하면 stack 순서, aria-hidden 처리, Escape 우선순위, focus trap 중첩, backdrop pointer 차단을 fixture로 검증해야 합니다." }, { q: "drawer를 URL과 연결해야 하나요?", answer: "상세 조회나 공유 가능한 편집처럼 새로고침, deep link, 뒤로가기가 의미 있으면 URL에 연결합니다. 단순 보조 필터나 임시 설정이면 local open state가 낫고, URL drawer는 route 전환 시 focus restoration과 page_view 정책을 같이 정합니다." }, { q: "ESC 동작은 어떻게 정하나요?", answer: "Escape는 가장 최근에 열린 overlay를 닫되, dirty form이나 저장 중 상태에서는 바로 닫지 않고 guard를 거칩니다. 닫힘이 cancel인지 discard인지 copy로 분명히 하고, 닫은 뒤 trigger focus와 analytics cancel event를 확인합니다." }]),
      item("popover와 tooltip은 무엇이 다른가요?", "tooltip은 보조 설명이고 focus 가능한 콘텐츠를 담지 않습니다. popover는 상호작용 가능한 작은 레이어이며 열림/닫힘, focus, outside click 정책이 필요합니다.", "tooltip 안에 버튼을 넣으면 keyboard와 screen reader 사용자가 접근하기 어렵습니다.", "overlay pattern spec, focus test, hover/focus parity, outside click fixture", [{ q: "hover 전용 정보는 왜 위험한가요?", answer: "touch 기기와 keyboard 사용자는 hover를 만들 수 없고, screen reader는 hover 설명을 같은 방식으로 얻지 못합니다. 꼭 필요한 정보는 visible text나 focus-triggered tooltip으로 제공하고 hover/focus parity fixture를 둡니다." }, { q: "mobile에서 tooltip은?", answer: "모바일에서는 tooltip보다 inline helper text, info button으로 여는 popover, bottom sheet가 안정적입니다. tap으로 연다면 밖 탭, 뒤로가기, focus 이동, safe area, viewport resize를 함께 설계합니다." }, { q: "outside click과 blur는 어떻게 다르나요?", answer: "outside click은 pointer target이 overlay 밖인지 보는 것이고 blur는 focus가 빠져나갔는지 보는 것입니다. mouse down으로 focus가 먼저 바뀌는 순서, portal, shadow DOM을 고려해 pointerdown/click/blur 순서를 fixture로 고정합니다." }]),
      item("입력 지연을 줄이는 인터랙션 전략은 무엇인가요?", "입력 즉시 feedback을 주고 비싼 계산은 debounce, transition, worker, virtualization으로 분리합니다.", "debounce만 걸면 느린 느낌은 줄 수 있지만 CPU long task나 render 폭증의 원인은 남아 있습니다.", "input latency trace, INP, React Profiler, worker timing", [{ q: "debounce와 throttle 차이는?", answer: "debounce는 입력이 멈춘 뒤 한 번 실행해 검색 요청이나 저장 draft에 맞고, throttle은 일정 간격마다 실행해 scroll/resize pointer move에 맞습니다. 둘 다 UI feedback은 즉시 주고, 실제 network나 계산만 지연해야 입력이 먹히는 느낌을 유지합니다." }, { q: "startTransition은 무엇을 해결하나요?", answer: "React에서 긴 렌더 업데이트를 낮은 우선순위로 밀어 입력값 반영 같은 긴급 업데이트를 먼저 처리하게 합니다. 서버 요청, CPU 연산 자체를 빠르게 만들지는 않으므로 Profiler와 INP trace로 렌더 병목인지 확인해야 합니다." }, { q: "worker로 보내면 항상 빨라지나요?", answer: "항상 그렇지는 않습니다. serialization, transfer 비용, worker 초기화 시간이 계산 비용보다 크면 느려질 수 있습니다. 큰 필터링이나 파싱은 worker timing fixture로 main thread long task 감소와 입력 latency 개선을 같이 봅니다." }]),
      item("검색 자동완성은 어떻게 설계하나요?", "debounce, abort, stale response guard, keyboard navigation, loading/empty/error 상태, analytics event를 포함합니다.", "이전 요청 응답이 늦게 도착하면 최신 query 결과를 덮어쓰고, 키보드 선택이 mouse hover와 불일치할 수 있습니다.", "AbortController test, combobox a11y test, stale response fixture, search event log", [{ q: "minimum query length는 왜 필요한가요?", answer: "짧은 query는 결과 품질이 낮고 요청량이 폭증하기 쉽습니다. 최소 길이 전에는 안내 상태를 보여주고 analytics에는 no-query action을 보내지 않으며, IME composing 중 요청하지 않는 fixture도 둡니다." }, { q: "추천 결과를 cache해도 되나요?", answer: "가능하지만 query, locale, 권한, 사용자 세그먼트가 cache key에 들어가야 합니다. stale 추천이 허용되는 시간과 permission change 시 invalidate 기준을 정하고, 늦은 응답이 최신 query를 덮지 않게 request id를 비교합니다." }, { q: "Enter 키는 언제 검색/선택인가요?", answer: "활성 추천 항목이 있으면 선택, 없으면 현재 query로 검색처럼 combobox 상태에 따라 정합니다. aria-activedescendant, hover와 keyboard highlight 동기화, Enter 후 route 전환과 page_view 이벤트를 fixture로 검증합니다." }]),
      item("복잡한 wizard flow는 어떻게 모델링하나요?", "step, guard, validation, save draft, back navigation, resumability, server state를 명시합니다.", "단순 step index만 두면 조건부 분기, 뒤로가기, 중간 저장, 권한 만료에서 잘못된 단계로 이동합니다.", "wizard state chart, deep link test, draft persistence fixture, guard table", [{ q: "URL에 step을 넣어야 하나요?", answer: "새로고침, 공유, 뒤로가기, 이탈 후 복귀가 요구되면 step을 URL에 둡니다. 다만 guard를 통과하지 않은 step은 route loader에서 이전 유효 step으로 보내고, focus는 step heading으로 복원해야 합니다." }, { q: "중간 저장 실패는?", answer: "draft를 saved/saving/failed 상태로 나누고 실패 시 다음 step 진입을 막을지 local draft로 계속 진행할지 정합니다. 실패 배너, retry, conflict 처리, unload guard를 포함한 fixture가 필요합니다." }, { q: "완료 후 뒤로가기는?", answer: "완료 상태를 별도 terminal state로 보고 이전 step으로 돌아갈 수 있는지 제품 정책을 정합니다. 결제나 제출 완료처럼 되돌릴 수 없으면 뒤로가기는 완료 화면이나 상세 route로 보내고, 재제출을 막는 idempotency key를 둡니다." }]),
      item("inline edit는 어떻게 안전하게 만들까요?", "view/edit/saving/saved/failed 상태, optimistic 여부, validation, escape/cancel, focus 복귀를 설계합니다.", "blur 시 자동 저장만 쓰면 사용자가 취소했다고 생각한 값이 저장되거나 네트워크 실패가 숨겨질 수 있습니다.", "inline edit state test, save failure fixture, keyboard flow, audit log", [{ q: "Enter와 Escape는?", answer: "일반적으로 Enter는 저장, Escape는 편집 취소와 원래 값 복귀입니다. textarea나 IME composing에서는 Enter 의미가 달라질 수 있으므로 key handling을 분기하고, 취소 후 focus가 편집 trigger나 셀에 남는지 확인합니다." }, { q: "저장 중 다른 행 편집은?", answer: "같은 entity나 같은 필드 집합이면 충돌을 줄이기 위해 잠그거나 queue에 넣습니다. 독립 행은 허용할 수 있지만 row별 saving state, optimistic patch, 실패 rollback이 분리되어야 합니다." }, { q: "충돌 발생 시 어떻게 보이나요?", answer: "서버가 409나 version mismatch를 주면 사용자의 draft, 서버 최신값, 덮어쓰기/병합/취소 action을 보여줍니다. 조용히 덮어쓰지 말고 focus를 conflict panel로 보내며 audit log에 선택 결과를 남깁니다." }]),
      item("selection interaction에서 무엇을 주의하나요?", "row identity, select all scope, filtering/pagination, disabled rows, bulk action 권한을 명확히 합니다.", "현재 화면만 선택인지 전체 결과 선택인지 모호하면 사용자가 예상보다 많은 데이터를 변경할 수 있습니다.", "selection contract, bulk action confirmation, row id fixture, permission test", [{ q: "select all은 현재 페이지인가요 전체인가요?", answer: "둘 중 하나를 copy와 state로 명확히 구분해야 합니다. 현재 페이지 전체 선택 후 '검색 결과 전체 선택'으로 확장하는 패턴을 쓰면 bulk action confirmation에 대상 수, 필터, 제외 항목을 함께 보여줘야 합니다." }, { q: "필터 변경 후 selection은?", answer: "선택 범위가 필터 결과에 묶여 있으면 필터 변경 시 selection을 초기화하거나 새 결과에 맞춰 재계산해야 합니다. stable row id를 기준으로 유지하는 경우에도 보이지 않는 선택 항목 수를 persistent bar로 알려야 합니다." }, { q: "비활성 행은 어떻게 표시하나요?", answer: "선택할 수 없는 이유가 권한, 상태, 잠금 중 무엇인지 row level로 설명해야 합니다. checkbox disabled만 두지 말고 aria-disabled, tooltip이나 inline reason, bulk action에서 제외되는 fixture를 둡니다." }]),
      item("scroll interaction은 왜 까다롭나요?", "nested scroll, sticky header, virtual list, anchor navigation, scroll restoration, mobile address bar를 고려해야 합니다.", "body scroll lock을 잘못 걸면 배경이 움직이거나 iOS에서 input focus가 깨집니다.", "scroll restoration test, mobile Safari capture, virtual list measurement, sticky offset check", [{ q: "scrollIntoView는 항상 안전한가요?", answer: "아닙니다. sticky header에 가리거나 nested container가 아닌 body를 움직일 수 있고, virtual list에서는 대상 DOM이 아직 없을 수 있습니다. offset 계산, container 지정, reduced motion, focus 이동 순서를 fixture로 확인합니다." }, { q: "body scroll lock은?", answer: "modal이나 drawer에서 배경 스크롤을 막을 때 쓰지만 iOS Safari, virtual keyboard, overscroll에서 깨지기 쉽습니다. lock 전 scroll position을 저장하고 해제 시 복원하며, touchmove 차단이 overlay 내부 scroll까지 막지 않는지 봅니다." }, { q: "anchor와 fixed header는?", answer: "anchor target에 scroll-margin-top을 두거나 router scroll restoration에서 header 높이를 반영합니다. route 전환 후 async content가 늦게 들어오는 경우 두 번 스크롤될 수 있어 layout stable 시점과 focus heading 이동을 함께 테스트합니다." }]),
      item("gesture를 추가할 때 기준은 무엇인가요?", "gesture는 보조 경로여야 하며 명시적 버튼/키보드 대체 조작과 충돌하지 않아야 합니다.", "swipe 삭제 같은 gesture만 제공하면 발견 가능성과 접근성이 낮고 실수 비용이 큽니다.", "gesture fallback map, touch target audit, accidental activation test, undo fixture", [{ q: "gesture discoverability는?", answer: "gesture는 보이지 않기 때문에 첫 사용 hint, 명시적 버튼, context menu 같은 대체 경로가 있어야 합니다. 삭제나 결제처럼 위험한 action은 swipe만으로 확정하지 말고 staged reveal, confirmation, undo를 둡니다." }, { q: "touch와 mouse event 중 무엇을 쓰나요?", answer: "가능하면 Pointer Events로 mouse, touch, pen을 같은 lifecycle에서 처리합니다. pointercancel, pointer capture, primary pointer, touch-action CSS를 같이 설정하고 keyboard 대체 조작은 별도로 제공합니다." }, { q: "실수 방지는 어떻게 하나요?", answer: "거리와 속도 threshold, 방향 잠금, preview 상태, undo window를 둡니다. accidental activation fixture에는 짧은 스크롤, 한 손 조작, edge swipe, route 뒤로가기 gesture 충돌을 넣습니다." }]),
      item("disabled 상태와 loading 상태는 어떻게 다르나요?", "disabled는 사용할 수 없는 조건, loading은 현재 처리 중인 상태입니다. 이유와 진행 상태, 취소 가능성을 구분해야 합니다.", "처리 중 버튼을 disabled만 하면 screen reader가 이유를 알기 어렵고, 실패 후 복구 경로가 사라질 수 있습니다.", "button state matrix, aria-disabled audit, submit pending test, retry fixture", [{ q: "aria-disabled와 disabled 차이는?", answer: "`disabled`는 native control을 focus와 submit에서 제외하지만, `aria-disabled`는 의미만 전달하고 동작 차단은 직접 해야 합니다. menu item이나 custom button처럼 focus를 유지해야 할 때 aria-disabled를 쓰되 Enter/Space handler도 막아야 합니다." }, { q: "loading 중 focus는?", answer: "가능하면 현재 버튼에 focus를 유지하고 상태 텍스트나 spinner의 accessible name으로 진행 중임을 알립니다. route 전환이나 modal 닫힘이 발생하면 다음 화면 heading이나 결과 영역으로 focus를 보내고 중복 제출은 pending state로 막습니다." }, { q: "왜 비활성인지 설명해야 하나요?", answer: "사용자가 해결할 수 있는 조건이면 설명해야 합니다. 예를 들어 권한 없음, 필수 입력 누락, quota 초과는 reason text나 validation summary를 제공하고, permission change fixture로 버튼 표시와 서버 403 복구가 일치하는지 확인합니다." }]),
      item("confirmation dialog는 언제 필요한가요?", "되돌리기 어렵거나 영향 범위가 큰 작업에 필요합니다. 하지만 반복 작업에는 undo나 staged review가 더 나을 수 있습니다.", "모든 작업에 confirm을 붙이면 사용자는 기계적으로 확인하고, 정작 위험한 작업의 신호가 약해집니다.", "destructive action policy, undo alternative, bulk impact copy, audit event", [{ q: "삭제에는 항상 confirm이 필요한가요?", answer: "soft delete와 undo가 충분하면 매번 confirm이 필요하지 않을 수 있습니다. 영구 삭제, 대량 삭제, 외부 알림 발송처럼 되돌리기 어려운 side effect가 있으면 confirmation이 맞고, 버튼 copy에는 대상과 영향 범위를 넣습니다." }, { q: "문구에는 무엇이 들어가야 하나요?", answer: "대상 이름, 개수, 되돌릴 수 있는지, 권한이나 하위 리소스 영향, 다음 상태를 담아야 합니다. '정말?' 같은 모호한 문구보다 '프로젝트 12개를 보관 처리'처럼 bulk scope가 드러나야 합니다." }, { q: "권한 있는 사용자도 확인해야 하나요?", answer: "권한은 실행 가능 여부이고 confirmation은 실수 방지입니다. 관리자라도 영향 범위가 크면 확인이 필요하며, audit event에는 누가 어떤 대상에 어떤 confirmation을 거쳐 실행했는지 남깁니다." }]),
      item("command palette를 설계할 때 무엇을 봐야 하나요?", "검색, keyboard shortcut, permission filtering, recent/frequent ranking, action preview, undo 가능성을 봅니다.", "보이지 않는 명령을 노출하거나 권한 없는 action이 섞이면 신뢰와 보안 경계가 흔들립니다.", "command registry, shortcut map, permission fixture, action audit log", [{ q: "shortcut 충돌은 어떻게 관리하나요?", answer: "route별 scope와 input focused 상태를 나눠 registry에서 관리합니다. 브라우저/OS 기본 단축키를 덮지 않고, modal이나 editor가 열려 있을 때 우선순위를 바꾸며 keyboard fixture로 충돌을 확인합니다." }, { q: "명령 결과 preview는?", answer: "파괴적이거나 대상이 많은 명령은 실행 전에 대상, 권한, 예상 결과를 preview로 보여줘야 합니다. 예를 들어 'Archive 23 filtered issues'처럼 scope가 명확해야 하고 실행 후 undo나 audit event를 연결합니다." }, { q: "모바일에서는 어떻게 하나요?", answer: "keyboard 중심 palette를 그대로 강요하지 말고 bottom sheet 검색, 최근 action, 명시적 버튼으로 대체합니다. focus trap, virtual keyboard viewport, touch target, 뒤로가기 닫힘을 mobile fixture로 확인합니다." }]),
      item("실시간 협업 UI는 무엇이 어렵나요?", "presence, cursor, conflict resolution, optimistic update, latency compensation, offline reconnect를 설계해야 합니다.", "마지막 저장값으로 덮어쓰면 사용자의 작업이 조용히 사라집니다.", "conflict fixture, presence heartbeat, CRDT/OT decision note, reconnect log", [{ q: "충돌은 사용자에게 보여줘야 하나요?", answer: "자동 병합이 안전한 텍스트 위치 변경은 조용히 처리할 수 있지만, 같은 필드의 의미 있는 값 충돌은 보여줘야 합니다. 사용자의 draft와 원격 변경을 비교하고, 선택 결과를 state machine의 resolved 상태로 전이시킵니다." }, { q: "presence가 stale하면?", answer: "heartbeat 만료 시간을 두고 stale presence는 흐리게 표시하거나 제거합니다. 네트워크 재연결 시 이전 cursor를 그대로 믿지 말고 server snapshot을 다시 받고, presence event는 analytics보다 운영 debug log 성격으로 다룹니다." }, { q: "offline edit는 허용하나요?", answer: "데이터 모델이 merge 가능하고 conflict UI가 준비되어 있으면 허용할 수 있습니다. 결제, 권한 변경, unique constraint처럼 서버 검증이 중요한 작업은 offline queue보다 read-only나 draft 저장으로 제한합니다." }]),
      item("micro-interaction은 언제 성능 문제가 되나요?", "짧은 animation도 레이아웃을 건드리거나 많은 요소에 동시에 적용되면 INP와 frame rate를 해칩니다.", "hover, focus, active 효과를 모두 box-shadow/filter/layout 변화로 만들면 저사양 기기에서 입력 지연이 생깁니다.", "Performance trace, FPS capture, INP by device, animation property audit", [{ q: "box-shadow는 왜 비쌀 수 있나요?", answer: "큰 blur shadow가 많은 요소에 동시에 바뀌면 paint 비용이 커지고 scroll이나 hover 중 frame budget을 넘길 수 있습니다. hover/focus 효과는 opacity, transform, outline처럼 비용이 낮은 속성으로 대체 가능한지 Performance trace로 확인합니다." }, { q: "hover 없는 기기는?", answer: "touch 기기에서는 hover가 없거나 첫 tap이 hover처럼 동작해 activation을 방해할 수 있습니다. `hover: none`, `pointer: coarse` 조건에서 active/focus visible 상태와 명시적 affordance가 있는지 mobile fixture로 봅니다." }, { q: "focus ring을 없애도 되나요?", answer: "없애면 안 됩니다. 디자인에 맞게 커스텀할 수는 있지만 keyboard 사용자가 현재 위치를 볼 수 있어야 하고, focus-visible 기준으로 pointer 클릭과 keyboard focus를 나눠 visual regression과 keyboard test를 통과해야 합니다." }]),
      item("접근성 announcement는 어떻게 정하나요?", "사용자 작업 결과와 비동기 상태 변화 중 화면에 즉시 보이지 않는 것을 aria-live로 알립니다.", "모든 변화를 assertive로 읽으면 screen reader 사용자의 작업을 방해하고 중요한 알림이 묻힙니다.", "aria-live policy, screen reader capture, async status fixture, toast audit", [{ q: "polite와 assertive 차이는?", answer: "polite는 현재 낭독이 끝난 뒤 읽고, assertive는 더 급하게 끼어듭니다. 저장 완료, 결과 수 변경은 polite로 충분하고, 세션 만료나 destructive failure처럼 즉시 행동이 필요한 경우만 assertive를 씁니다." }, { q: "loading도 읽어야 하나요?", answer: "사용자가 기다려야 하거나 버튼이 pending으로 바뀌는 경우는 '저장 중' 같은 상태를 알려야 합니다. 매우 짧은 loading은 낭독 소음이 될 수 있어 지연 threshold를 두고, 완료/실패 announcement와 짝을 맞춥니다." }, { q: "반복 알림은 어떻게 줄이나요?", answer: "같은 메시지는 dedupe하고 count나 마지막 결과로 합칩니다. 자동완성 결과 수, toast queue, 협업 presence처럼 자주 바뀌는 상태는 throttle된 aria-live 정책과 screen reader capture로 검증합니다." }]),
      item("context menu는 어떻게 안전하게 만들죠?", "마우스 우클릭뿐 아니라 keyboard trigger, focus, permission, destructive action guard, mobile 대체 UI를 둡니다.", "커스텀 메뉴가 브라우저 기본 기능을 막고 keyboard 접근을 제공하지 않으면 사용성이 떨어집니다.", "context menu a11y test, permission filter, mobile fallback capture, action log", [{ q: "브라우저 기본 메뉴를 막아도 되나요?", answer: "앱 객체에 대한 명령이 명확한 영역에서는 막을 수 있지만, 텍스트 입력이나 링크처럼 기본 복사/열기 기능이 중요한 곳은 막지 않는 편이 낫습니다. 막는 경우에도 keyboard와 mobile 대체 메뉴를 제공해야 합니다." }, { q: "키보드에서 어떻게 여나요?", answer: "Context Menu 키나 Shift+F10, 또는 명시적 more button으로 열 수 있어야 합니다. 열릴 때 첫 메뉴 항목이나 현재 선택 항목에 focus를 두고 Arrow/Escape 동작을 menu pattern에 맞춥니다." }, { q: "메뉴 밖 클릭은?", answer: "밖 pointerdown은 메뉴를 닫되, 메뉴 action 클릭과 blur 순서가 충돌하지 않게 처리합니다. 닫힌 뒤 focus는 trigger나 선택 row로 돌아가야 하며, destructive action은 메뉴 닫힘과 별개로 confirmation이나 undo를 거칩니다." }]),
      item("인터랙션 테스트는 어떤 수준으로 나누나요?", "state machine 단위 테스트, component interaction test, Playwright E2E, accessibility smoke로 나눕니다.", "E2E만 믿으면 느리고 원인 파악이 어렵고, unit만 믿으면 실제 포커스/키보드/브라우저 동작을 놓칩니다.", "test pyramid, user-event tests, Playwright trace, axe report", [{ q: "user-event와 fireEvent 차이는?", answer: "user-event는 click, typing, tab처럼 실제 사용자 동작에 가까운 이벤트 순서를 만들고 focus 변화도 포함합니다. fireEvent는 단일 이벤트를 직접 쏘기 때문에 edge case 재현에는 유용하지만 keyboard/pointer 상호작용 검증의 기본값으로는 부족합니다." }, { q: "모든 브라우저에서 E2E를?", answer: "모든 케이스를 모든 브라우저에서 돌리기보다 핵심 journey와 브라우저 차이가 큰 focus, input, scroll, pointer gesture를 matrix로 나눕니다. Chromium 전체, WebKit/Safari smoke, mobile viewport fixture처럼 위험 기반으로 잡습니다." }, { q: "flaky test는 어떻게 줄이나요?", answer: "시간 sleep 대신 상태 전이를 기다리고, network fixture와 clock을 제어하며, animation은 test mode에서 줄입니다. 실패 시 Playwright trace, screenshot, event log를 남겨 pointer/focus/route 어느 단계에서 흔들렸는지 보게 합니다." }]),
      item("route 전환 중 사용자 입력은 어떻게 다루나요?", "pending navigation, unsaved changes, abortable requests, optimistic mutation, focus restoration을 설계합니다.", "사용자가 저장 중 이동하면 요청은 성공했지만 화면은 이전 상태를 보여주거나 반대로 변경을 잃을 수 있습니다.", "navigation guard test, pending mutation log, abort signal fixture, focus restore", [{ q: "unsaved changes prompt는 언제?", answer: "사용자가 작성한 draft가 있고 route 전환으로 잃을 수 있을 때만 띄웁니다. 서버에 이미 저장됐거나 자동 저장이 성공한 상태에서는 띄우지 않고, browser back, internal link, modal close를 같은 dirty state guard로 처리합니다." }, { q: "route loader 실패는?", answer: "이전 화면을 유지할지 error boundary route로 갈지 정해야 합니다. 실패 화면에는 retry, 권한 오류, offline 구분을 두고 focus는 error heading으로 보내며, analytics에는 page_view가 아니라 route_load_failed 같은 result event를 남깁니다." }, { q: "뒤로가기 중 mutation은?", answer: "pending mutation은 abort 가능한 요청이면 취소하고, 이미 서버에 도달한 요청이면 완료 후 cache를 reconcile해야 합니다. optimistic UI가 적용된 상태라면 history 이동 후에도 mutation ledger가 남아 stale 화면을 다시 그리지 않게 합니다." }]),
      item("복잡한 인터랙션의 QA 시나리오는 어떻게 만들까요?", "happy path보다 rapid click, keyboard-only, mobile touch, network slow, permission change, stale data를 먼저 넣습니다.", "시나리오가 성공 흐름만 있으면 실제 운영에서 나오는 race와 취소 이벤트를 잡지 못합니다.", "interaction QA matrix, network throttle trace, permission fixture, stale response test", [{ q: "QA에 꼭 넣을 3가지는?", answer: "keyboard-only 경로, 느린 네트워크와 stale response, 권한 변경이나 403 복구를 우선 넣습니다. 여기에 pointercancel 또는 rapid click을 더하면 state machine의 취소와 중복 제출 전이가 드러납니다." }, { q: "네트워크 지연은 어떻게 재현하나요?", answer: "MSW, Playwright route fulfill delay, DevTools throttling으로 latency, timeout, out-of-order response를 만듭니다. 자동완성은 이전 query가 늦게 오는 fixture, optimistic mutation은 reject와 duplicate click fixture를 둡니다." }, { q: "권한 변경은 어떻게 테스트하나요?", answer: "초기에는 버튼이 보이지만 action 직전 403이 나는 fixture와, 화면에 머무는 동안 role이 내려가는 fixture를 분리합니다. UI는 버튼 숨김만이 아니라 실패 후 상태 수렴, focus 위치, audit log, analytics error result까지 확인합니다." }]),
      item("인터랙션과 analytics는 어떻게 연결하나요?", "사용자 의도 단위로 event를 정의하고 exposure, action, result, error를 나눕니다.", "DOM click만 추적하면 의미 없는 이벤트가 쌓이고 실패/취소/재시도 같은 중요한 흐름을 놓칩니다.", "event taxonomy, funnel chart, error result event, privacy review", [{ q: "click event와 action event 차이는?", answer: "click event는 DOM 발생 사실이고 action event는 사용자가 의도한 작업입니다. 같은 저장 action이 keyboard shortcut, button click, command palette에서 발생해도 하나의 action schema로 묶고 result, error code, source를 속성으로 둡니다." }, { q: "중복 이벤트는 어떻게 막나요?", answer: "state machine의 committing 전이에서 한 번만 보내고, retry와 undo는 별도 event로 분리합니다. route 전환 중 page_view 중복, double click, optimistic retry를 event id나 mutation id로 dedupe하는 QA log가 필요합니다." }, { q: "개인정보는 어디서 제거하나요?", answer: "event 생성 경계에서 raw input, email, token, 검색어 원문 같은 값을 보내지 않게 schema로 제한합니다. 필요한 경우 category나 length 같은 파생값만 보내고, privacy review와 debug event log로 payload를 확인합니다." }]),
      item("인터랙션 구현에서 senior-level 리뷰 포인트는 무엇인가요?", "상태 전이, 입력 장치 다양성, 접근성, 실패 복구, 관측 증거, 테스트 fixture가 있는지 봅니다.", "시각적으로 동작하는 데모만 있으면 실제 사용자의 빠른 조작과 보조기술 환경에서 깨질 수 있습니다.", "INTERACTION STATE MACHINE MODEL, pointer lifecycle contract, keyboard capture, PR evidence", [{ q: "리뷰에서 바로 막아야 할 위험은?", answer: "keyboard 경로가 없거나 focus가 사라지는 overlay, rollback 없는 optimistic update, permission check 없이 노출된 destructive action, route 전환 중 draft 유실은 막아야 합니다. 각각은 사용자가 작업을 잃거나 잘못된 action을 실행하는 직접 위험입니다." }, { q: "데모와 운영 기능 차이는?", answer: "데모는 정상 click만 보여줘도 충분해 보이지만 운영 기능은 pointercancel, 빠른 재클릭, 403, 느린 응답, mobile viewport, screen reader announcement를 견뎌야 합니다. 그래서 PR에는 trace, fixture, state table이 필요합니다." }, { q: "증거가 부족하면 무엇을 요구하나요?", answer: "관련 state machine이나 transition table, keyboard/focus 녹화, Playwright trace, 실패 API fixture, analytics debug log 중 변경 위험에 맞는 증거를 요구합니다. UI 캡처만으로는 route, permission, network race를 판단할 수 없습니다." }]),
      item("경험이 없는 인터랙션 질문은 어떻게 답하나요?", "직접 운영 경험과 설계 지식을 분리해 말하고, 상태 기계, 접근성 패턴, 실패 fixture로 검증하겠다고 답합니다.", "해본 것처럼 말하면 꼬리질문에서 실제 장애, 측정, 테스트 증거를 요구받을 때 무너집니다.", "experience boundary note, prototype plan, a11y pattern reference, validation checklist", [{ q: "모르면 모른다고 해야 하나요?", answer: "네, 직접 운영 경험이 없으면 없다고 말하고 대신 어떤 위험을 검증할지 제시합니다. 예를 들어 DnD 경험이 적다면 pointer lifecycle, keyboard 대체, rollback fixture, mobile touch test를 기준으로 설계하겠다고 답합니다." }, { q: "대체 경험은 어떻게 연결하나요?", answer: "비슷한 상태 전이 경험을 연결합니다. wizard의 guard와 draft 저장 경험은 modal flow나 route 전환 guard에, optimistic update 경험은 inline edit와 undo 설계에 연결하되 다른 점도 함께 말합니다." }, { q: "검증 계획은 얼마나 구체적이어야 하나요?", answer: "도구 이름보다 fixture가 구체적이어야 합니다. 'Playwright로 테스트'가 아니라 keyboard-only로 modal 열고 닫기, 403 후 버튼 상태 수렴, stale autocomplete 응답 무시, undo window 만료처럼 입력과 기대 상태를 적습니다." }]),
    ],
  },
  {
    id: "engineering-frontend-motion-qa",
    title: "프론트엔드 모션·애니메이션 Q&A",
    source: "프론트엔드 모션·애니메이션",
    subtitle: "motion token, easing, FLIP, interrupt, reduced motion, 성능 검증을 답변으로 훈련합니다.",
    questions: [
      item("제품 모션의 목적은 무엇인가요?", "모션은 장식이 아니라 상태 변화, 공간 관계, 주의 이동, 조작 결과를 설명하는 피드백입니다.", "목적 없이 추가하면 지연처럼 느껴지고 접근성·성능 비용만 늘어납니다.", "motion purpose table, interaction state map, user timing capture, visual regression", [{ q: "모션을 빼야 하는 기준은?", answer: "상태 이해나 조작 피드백에 기여하지 않고 입력 지연, 멀미, layout shift, focus 혼란만 만든다면 빼는 쪽이 맞습니다. 특히 reduced motion에서 instant/fade로 바꿔도 의미가 유지되면 장식성 이동은 기본 경험에서 줄입니다." }, { q: "브랜드 모션과 제품 모션 차이는?", answer: "브랜드 모션은 톤과 인상을 만들지만 제품 모션은 버튼 pending, drawer 이동, 리스트 재정렬처럼 상태와 공간 관계를 설명해야 합니다. 제품 모션은 duration/easing token, interrupt, 접근성 대체가 명확해야 운영 품질로 볼 수 있습니다." }, { q: "사용자가 느끼는 속도는 어떻게 확인하나요?", answer: "실제 입력 직후 피드백이 몇 ms 안에 보이는지, animation이 작업 완료를 늦게 보이게 하지 않는지 trace와 사용성 녹화로 봅니다. 같은 250ms라도 ease-out 피드백은 빠르게 느껴지고 delay가 붙은 transition은 느리게 느껴질 수 있습니다." }]),
      item("duration과 easing은 어떻게 정하나요?", "변화 거리, 중요도, 입력 직접성, interrupt 가능성을 기준으로 token화합니다. 작은 UI feedback은 짧고, 공간 전환은 관계를 이해할 만큼만 둡니다.", "모든 animation을 같은 duration/easing으로 두면 느리거나 급작스럽게 보이고 시스템 일관성이 떨어집니다.", "motion token table, easing comparison, frame capture, reduced-motion variant", [{ q: "200ms가 항상 적절한가요?", answer: "아닙니다. hover/focus 피드백은 80-150ms가 자연스럽고, 큰 panel 이동이나 route transition은 180-300ms 범위에서 거리와 중요도에 맞춥니다. reduced motion에서는 이동 duration을 0에 가깝게 줄이거나 짧은 fade token으로 바꿉니다." }, { q: "ease-out은 언제 쓰나요?", answer: "사용자 입력에 대한 응답처럼 빨리 시작하고 부드럽게 멈춰야 할 때 씁니다. enter나 drawer open에는 ease-out이 맞고, exit는 빠르게 사라지는 ease-in, 양방향 state change는 ease-in-out이나 spring token을 별도로 둡니다." }, { q: "spring은 어떻게 제어하나요?", answer: "stiffness, damping, mass를 토큰화하고 overshoot 허용 범위를 컴포넌트별로 제한합니다. interrupt가 잦은 drag나 reorder에는 target 변경 시 속도를 이어가되, modal이나 form error처럼 안정감이 필요한 UI에는 bounce를 줄입니다." }]),
      item("reduced motion은 어떻게 지원하나요?", "prefers-reduced-motion을 읽고 transform 이동, parallax, autoplay를 줄이거나 fade/instant 전환으로 대체합니다.", "옵션을 무시하면 전정기관 민감 사용자에게 실제 불편을 만들고 접근성 기준을 놓칩니다.", "reduced motion audit, media query test, visual snapshot, release gate", [{ q: "모든 animation을 제거해야 하나요?", answer: "모두 제거하는 것이 아니라 큰 이동, parallax, zoom, 자동 loop처럼 불편을 줄 수 있는 motion을 줄입니다. 상태 피드백은 opacity fade, instant change, progress text처럼 덜 자극적인 방식으로 남겨 사용자가 변화를 이해하게 합니다." }, { q: "CSS와 JS animation 모두 적용되나요?", answer: "CSS는 `@media (prefers-reduced-motion: reduce)`로 token을 바꾸고, JS animation은 hook이나 runtime 설정에서 같은 preference를 읽어야 합니다. Framer Motion이나 WAAPI를 쓰면 reduced motion mode에서 duration, transform, autoplay를 별도 분기합니다." }, { q: "사용자 설정 변경은 즉시 반영해야 하나요?", answer: "네. OS 설정이 바뀌면 media query change를 구독해 새 animation부터 reduced token을 적용하고, 진행 중인 loop나 parallax는 cancel해야 합니다. 설정 변경 후 route transition과 skeleton shimmer가 계속 도는지 캡처로 확인합니다." }]),
      item("FLIP 기법은 무엇을 해결하나요?", "First, Last, Invert, Play로 layout 변화 결과를 transform animation으로 보여줘 layout 비용을 줄이고 공간 이동을 설명합니다.", "측정과 적용 타이밍을 잘못 잡으면 forced layout과 flicker가 생깁니다.", "layout measurement trace, transform-only audit, before/after capture, list reorder fixture", [{ q: "FLIP도 layout을 읽지 않나요?", answer: "읽습니다. 차이는 layout을 매 프레임 변경하지 않고 First/Last를 제한된 시점에 측정한 뒤 transform으로 재생한다는 점입니다. read/write 순서를 분리하고 Performance trace에서 forced reflow가 반복되지 않는지 봐야 합니다." }, { q: "가상 리스트에서 가능한가요?", answer: "가능하지만 보이는 item과 stable key에 한정해야 합니다. virtualizer가 DOM을 재사용하므로 First/Last 측정은 item identity와 scroll offset을 같이 보정하고, 화면 밖 item은 animation보다 instant placement가 안전합니다." }, { q: "interrupt 중에는 어떻게 하나요?", answer: "현재 transform을 읽어 새 First로 삼거나 animation을 cancel하고 최신 layout target으로 다시 계산합니다. reorder가 연속으로 들어오면 완료 callback에 의존하지 말고 state machine이 최신 order와 animation handle을 별도로 관리해야 합니다." }]),
      item("CSS animation과 JS animation은 어떻게 고르나요?", "단순 상태 전환은 CSS, gesture/physics/interrupt 제어가 필요한 것은 JS animation library나 Web Animations API를 고려합니다.", "모든 것을 JS로 만들면 bundle과 main thread 비용이 커지고, 모든 것을 CSS로 하면 상태 제어와 취소가 어려울 수 있습니다.", "animation decision record, bundle diff, main-thread trace, cancellation test", [{ q: "Web Animations API 장점은?", answer: "CSS처럼 compositor 친화적인 속성을 쓰면서도 JS에서 play, pause, reverse, cancel, finish를 제어할 수 있습니다. exit transition이나 rapid toggle처럼 interrupt 처리가 필요한 경우 CSS transitionend보다 animation handle을 추적하기 쉽습니다." }, { q: "requestAnimationFrame은 언제?", answer: "gesture 좌표, canvas, scroll progress처럼 매 프레임 값을 직접 계산해야 할 때 씁니다. 단순 opacity/transform transition에는 과하고, RAF를 쓴다면 layout read/write 분리와 cancel cleanup, long task 여부를 trace로 확인합니다." }, { q: "library 선택 기준은?", answer: "필요한 기능이 layout animation, gesture, spring, presence transition인지 먼저 정하고 bundle size, SSR, reduced motion, tree-shaking, cancel API를 봅니다. 단순 button feedback이면 CSS token으로 충분한 경우가 많습니다." }]),
      item("layout을 건드리는 animation은 왜 위험한가요?", "width, height, top, left는 layout/paint를 유발할 수 있고 많은 요소에 전파됩니다. transform/opacity는 composite 단계로 처리될 가능성이 큽니다.", "레이아웃 animation이 리스트나 grid에 걸리면 frame drop과 INP 악화가 생깁니다.", "Performance trace, layout event count, composite layer audit, FPS capture", [{ q: "height auto animation은?", answer: "`height: auto`는 브라우저가 중간 값을 직접 보간하기 어려워 측정과 layout 비용이 커집니다. 콘텐츠 expand는 max-height hack보다 measured height, FLIP, 또는 transform clip 전략을 쓰고 trace에서 layout event가 반복되는지 확인합니다." }, { q: "will-change는 항상 좋은가요?", answer: "아닙니다. 필요한 짧은 구간에만 쓰지 않으면 layer가 늘어 GPU memory와 paint 비용이 증가합니다. hover 가능한 카드 전체에 상시 `will-change`를 뿌리기보다 active transition 직전 추가하고 종료 후 제거하는 식이 낫습니다." }, { q: "filter는 안전한가요?", answer: "blur나 drop-shadow filter는 composite만으로 끝나지 않고 큰 paint 비용을 만들 수 있습니다. 작은 opacity/transform보다 비싸므로 scroll 중이거나 많은 item에 적용하는 경우 Performance trace와 저사양 기기 FPS 캡처가 필요합니다." }]),
      item("presence transition에서 중요한 것은 무엇인가요?", "enter/exit 상태, unmount 지연, focus, aria-hidden, pointer-event 차단을 명확히 해야 합니다.", "exit animation 중 DOM이 남아 있으면 focus나 click을 잡아 사용자가 보이지 않는 요소와 상호작용할 수 있습니다.", "presence state test, focus trap capture, pointer event audit, DOM cleanup check", [{ q: "exit 중 focus는?", answer: "닫히는 요소 안에 focus가 있으면 exit 시작 전에 trigger나 다음 의미 있는 영역으로 옮겨야 합니다. modal은 focus trap을 먼저 해제하지 말고 반환 위치를 정한 뒤 aria-hidden과 pointer-events 상태를 함께 바꿉니다." }, { q: "display none과 opacity 0 차이는?", answer: "`display: none`은 layout과 접근성 트리에서 빠지지만 opacity 0은 보이지 않아도 focus와 click 대상이 될 수 있습니다. exit animation에는 opacity 0과 transform을 쓰더라도 aria-hidden, inert, pointer-events를 상태에 맞춰야 합니다." }, { q: "unmount cleanup은 언제?", answer: "exit animation이 끝났거나 cancel되어 최종 상태가 결정된 직후입니다. reduced motion에서는 duration이 0일 수 있으므로 transitionend만 기다리지 말고 timeout guard나 animation finished/cancel 상태로 cleanup을 보장합니다." }]),
      item("interruptible animation은 어떻게 설계하나요?", "진행 중 animation을 취소·역전·합성할 수 있어야 빠른 toggle과 route change에서 자연스럽습니다.", "완료 callback에만 상태를 묶으면 rapid click에서 UI가 중간 상태에 갇힙니다.", "rapid toggle fixture, animation cancel log, state machine, route change test", [{ q: "cancel 후 final state는?", answer: "사용자의 최신 의도와 도메인 상태가 final state입니다. animation cancel 시 시각 위치는 현재 값에서 새 target으로 이어가되, aria-expanded나 route state 같은 의미 상태는 최신 action 기준으로 즉시 수렴해야 합니다." }, { q: "animation promise는 어떻게 처리하나요?", answer: "promise 완료를 비즈니스 상태 전이의 유일한 조건으로 두지 않습니다. cancel, reject, reduced motion skip을 모두 처리하고, 컴포넌트 unmount 시 pending promise가 stale state update를 하지 않도록 animation id나 AbortSignal로 가드합니다." }, { q: "spring 중 target 변경은?", answer: "현재 위치와 velocity를 보존해 새 target으로 재계산하면 급격한 점프가 줄어듭니다. 다만 form error, confirmation dialog처럼 안정성이 중요한 UI는 spring overshoot를 제한하고 target 변경 로그를 rapid toggle fixture에서 확인합니다." }]),
      item("scroll-linked animation은 왜 조심해야 하나요?", "scroll은 입력과 직접 연결되어 있어 main thread 작업이 끼면 즉시 jank가 납니다. CSS scroll timeline, IntersectionObserver, throttling을 고려합니다.", "scroll handler에서 layout read/write를 반복하면 frame budget을 초과합니다.", "scroll performance trace, passive listener audit, frame drop metric, mobile capture", [{ q: "parallax는 언제 빼야 하나요?", answer: "콘텐츠 이해에 필요하지 않고 저사양 모바일, reduced motion, 긴 문서에서 frame drop이나 멀미를 만들면 빼야 합니다. 남긴다면 transform-only, 낮은 이동 거리, reduced motion instant/fade 대체, 모바일 성능 trace를 조건으로 둡니다." }, { q: "IntersectionObserver 한계는?", answer: "교차 여부나 대략적인 진입 타이밍에는 좋지만 픽셀 단위 scroll progress나 매 프레임 parallax에는 맞지 않습니다. threshold가 많으면 callback 부담이 커지고, layout 측정과 섞이면 scroll jank가 생길 수 있습니다." }, { q: "passive listener는 왜 필요한가요?", answer: "브라우저가 scroll을 막을 가능성이 없다고 판단해 입력 처리를 기다리지 않게 합니다. wheel/touchmove에서 preventDefault가 필요 없는 경우 passive로 두고, handler 안에서는 layout read/write를 줄이며 trace에서 scroll blocking listener 경고를 봅니다." }]),
      item("skeleton UI는 animation인가요?", "skeleton은 loading 중 layout 안정성과 기대 형성을 위한 feedback입니다. 실제 콘텐츠 구조와 크기를 반영해야 합니다.", "반짝이는 회색 박스만 넣으면 CLS를 줄이지 못하고 사용자는 진행 상태를 오해합니다.", "skeleton/content size diff, CLS metric, loading state story, slow network capture", [{ q: "spinner보다 항상 낫나요?", answer: "항상은 아닙니다. 콘텐츠 구조를 예측할 수 있고 공간을 미리 잡아 CLS를 줄일 때 skeleton이 좋고, 짧은 action pending이나 구조가 불확실한 작업에는 button spinner와 상태 텍스트가 더 명확합니다." }, { q: "skeleton은 얼마나 보여야 하나요?", answer: "너무 짧으면 flicker가 되고 너무 길면 가짜 진행처럼 보입니다. 최소 표시 시간과 timeout/error 전환을 정하고, shimmer는 reduced motion에서 정지하거나 은은한 static placeholder로 바꿉니다." }, { q: "접근성 announcement는?", answer: "skeleton 자체를 장황하게 읽히게 하지 말고 영역에 `aria-busy`와 상태 텍스트를 제공합니다. 로딩 완료나 실패처럼 사용자가 행동해야 하는 변화는 polite live region으로 알리고 반복 shimmer는 보조기술에 노출하지 않습니다." }]),
      item("page transition은 언제 적합한가요?", "같은 제품 공간 안에서 탐색 관계를 설명할 때 적합하고, 정보 탐색 속도가 중요한 화면에서는 최소화해야 합니다.", "모든 route에 큰 transition을 넣으면 navigation latency처럼 느껴지고 browser back/forward와 충돌합니다.", "navigation timing, route transition policy, back-forward test, reduced motion capture", [{ q: "SPA와 MPA에서 차이는?", answer: "SPA는 route state와 animation lifecycle을 앱이 제어하므로 exit/enter와 data loading을 맞출 수 있습니다. MPA는 브라우저 navigation이 중심이라 View Transition API 같은 지원이 없으면 과한 transition보다 빠른 LCP와 focus heading 이동이 중요합니다." }, { q: "뒤로가기 transition은?", answer: "history 방향을 감지해 forward와 반대 방향으로 짧게 보여줄 수 있지만, browser back은 사용자가 빠른 복귀를 기대합니다. bfcache, scroll restoration, reduced motion에서 transition이 focus나 이전 scroll 위치를 깨지 않는지 확인합니다." }, { q: "데이터 로딩과 어떻게 맞추나요?", answer: "animation이 API 지연을 가리는 용도로 늘어나면 안 됩니다. skeleton, optimistic shell, pending indicator를 따로 두고 transition duration은 token 범위에 고정하며, route loader 실패 시 error boundary로 focus를 이동합니다." }]),
      item("micro-interaction token은 무엇을 포함하나요?", "duration, easing, delay, distance, opacity, scale, reduced-motion 대체, 사용 가능한 상태를 포함합니다.", "토큰 없이 화면별로 값이 퍼지면 제품 전체가 불안정하게 느껴지고 유지보수가 어렵습니다.", "motion token inventory, CSS variable diff, component story, visual regression", [{ q: "delay는 언제 쓰나요?", answer: "tooltip처럼 의도 확인이 필요한 hover나 staggered list처럼 관계를 설명할 때 제한적으로 씁니다. 버튼 feedback, form error, navigation에는 delay가 입력 지연처럼 느껴질 수 있어 0에 가깝게 두고 token에 허용 컴포넌트를 명시합니다." }, { q: "scale feedback은 안전한가요?", answer: "작은 press feedback에는 0.98-0.99 정도의 scale이 쓸 수 있지만 text blur, layout overlap, hit target 축소를 확인해야 합니다. reduced motion에서는 scale 대신 색, outline, shadow 같은 비이동 피드백으로 바꿉니다." }, { q: "토큰 변경 영향은?", answer: "duration/easing token 하나가 버튼, modal, drawer, toast에 동시에 영향을 줄 수 있습니다. token diff를 컴포넌트 usage audit과 visual regression에 연결하고, major motion 변경은 QA matrix에 reduced motion과 low-end trace를 포함합니다." }]),
      item("3D transform을 UI에 쓸 때 주의할 점은?", "공간감을 줄 수 있지만 읽기성, motion sickness, layer memory, hit testing을 확인해야 합니다.", "과한 perspective와 rotation은 텍스트 가독성과 pointer target을 해칠 수 있습니다.", "layer memory trace, readability capture, pointer hit test, reduced motion variant", [{ q: "GPU 가속이면 무조건 좋은가요?", answer: "아닙니다. layer promotion은 composite를 빠르게 할 수 있지만 layer 수와 texture memory가 늘어 모바일에서 오히려 느려질 수 있습니다. Performance trace와 layer panel로 paint 감소와 memory 증가를 같이 봐야 합니다." }, { q: "텍스트에 transform을?", answer: "작은 translate는 괜찮을 수 있지만 rotate, scale, perspective는 가독성과 subpixel rendering을 해칠 수 있습니다. 본문이나 숫자처럼 읽기가 핵심인 텍스트는 transform motion을 줄이고 opacity나 container motion으로 대체합니다." }, { q: "hit area는 어떻게 검증하나요?", answer: "시각적으로 움직인 위치와 실제 pointer target이 일치하는지 Playwright pointer test와 수동 touch capture로 확인합니다. transform된 card 내부 버튼은 stacking context와 pointer-events, focus ring 위치까지 함께 봐야 합니다." }]),
      item("Lottie 같은 asset animation은 어떻게 검토하나요?", "파일 크기, frame rate, 렌더러(SVG/canvas), loop 여부, 접근성 대체 텍스트, theme 대응을 봅니다.", "마케팅 asset을 그대로 넣으면 bundle 증가, CPU 사용량, contrast 문제, reduced motion 누락이 생깁니다.", "asset budget, CPU trace, reduced motion fallback, visual QA", [{ q: "loop animation은 언제 멈추나요?", answer: "사용자의 주의를 계속 빼앗거나 CPU를 쓰는 loop는 완료, viewport 이탈, tab hidden, reduced motion에서 멈춰야 합니다. 장식 loop라면 한두 번 재생 후 정지하고 중요한 상태 변화는 text/icon으로도 전달합니다." }, { q: "SVG renderer와 canvas renderer 차이는?", answer: "SVG renderer는 DOM 접근과 scaling이 좋지만 요소가 많으면 layout/paint 비용이 커집니다. Canvas renderer는 DOM 부담은 줄지만 접근성 fallback과 hit testing을 별도로 설계해야 하며, 둘 다 CPU trace와 asset size를 봐야 합니다." }, { q: "다크모드 대응은?", answer: "asset 안의 색이 theme token과 연결되는지 확인해야 합니다. 하드코딩된 밝은 색 Lottie는 다크모드 contrast를 깨기 쉬우므로 theme별 asset, CSS variable 연동, 또는 reduced/static fallback을 준비합니다." }]),
      item("motion과 accessibility 충돌은 어떻게 해결하나요?", "정보 전달은 motion 하나에 의존하지 않고 text/icon/state로 중복 제공하며, motion은 보조 피드백으로 둡니다.", "색 변화나 흔들림만으로 오류를 알리면 보조기술과 일부 사용자에게 전달되지 않습니다.", "non-motion cue audit, aria message, contrast check, reduced motion test", [{ q: "shake animation은 괜찮나요?", answer: "오류 보조 신호로 짧게 쓸 수는 있지만 유일한 신호가 되면 안 됩니다. field error text, aria-describedby, focus 이동, live announcement를 제공하고 reduced motion에서는 shake를 제거하거나 border/summary로 대체합니다." }, { q: "오류 강조는 어떻게?", answer: "색, 아이콘, 문구, focus, aria-invalid를 함께 사용합니다. motion은 오류 위치를 잠깐 드러내는 보조 역할로 제한하고, duration은 짧게 두며 반복 흔들림이나 자동 scroll은 reduced motion에서 끕니다." }, { q: "모션 없이 상태를 어떻게 알리나요?", answer: "버튼 label, status text, icon, aria-live, disabled/pending state, focus placement로 알립니다. 예를 들어 저장 완료는 toast fade가 없어도 '저장됨' 상태와 polite announcement가 있으면 의미 전달이 됩니다." }]),
      item("animation 성능 예산은 어떻게 잡나요?", "목표 기기, frame budget, INP, long task, layer count, bundle size를 기준으로 잡습니다.", "데스크톱에서 부드러워도 저사양 모바일에서 main thread와 GPU memory가 동시에 부족할 수 있습니다.", "device matrix, FPS/INP metric, long task trace, bundle analyzer", [{ q: "60fps면 충분한가요?", answer: "기본 목표로는 좋지만 핵심은 입력 직후 jank가 없고 frame budget을 넘는 long task가 없는지입니다. 60Hz에서는 약 16.7ms, 120Hz에서는 약 8.3ms라 같은 animation도 고주사율 기기에서 더 엄격해집니다." }, { q: "120Hz 기기는?", answer: "120Hz에서는 frame budget이 절반이므로 scroll-linked animation이나 blur filter가 더 쉽게 끊겨 보입니다. 모든 UI를 120fps로 보장하기보다 핵심 gesture와 scroll 화면을 실제 기기에서 trace로 확인합니다." }, { q: "성능 측정 기기는 어떻게 고르나요?", answer: "팀 개발 장비가 아니라 사용자 분포의 저사양 Android, iOS Safari, 오래된 노트북 같은 하위 구간을 포함합니다. RUM segment와 device matrix를 연결하고, Performance trace에는 CPU throttle뿐 아니라 실제 mobile capture도 둡니다." }]),
      item("hover animation은 어떤 한계가 있나요?", "touch 기기에는 hover가 없거나 sticky hover처럼 동작할 수 있습니다. focus/active 상태와 동등한 피드백이 필요합니다.", "hover에만 중요한 정보를 숨기면 모바일과 키보드 사용자에게 기능이 보이지 않습니다.", "hover/focus parity test, touch device capture, CSS media query audit, keyboard path", [{ q: "hover media query는?", answer: "`@media (hover: hover) and (pointer: fine)`에서만 hover 전용 motion을 강화하고, coarse pointer에서는 active/focus 피드백과 명시적 버튼을 제공합니다. tooltip이나 action reveal은 touch에서 tap 한번을 낭비하지 않게 별도 UI가 필요합니다." }, { q: "tooltip과 hover card 차이는?", answer: "tooltip은 짧은 보조 설명이고 hover card는 더 많은 정보나 상호작용을 담을 수 있습니다. hover card가 focusable content를 포함하면 keyboard trigger, Escape, blur/hover leave, reduced motion exit까지 overlay pattern으로 다뤄야 합니다." }, { q: "focus-visible은 왜 쓰나요?", answer: "마우스 클릭에는 과한 focus ring을 줄이면서 keyboard 사용자는 현재 위치를 볼 수 있게 합니다. hover animation과 같은 수준의 focus feedback을 제공해야 하며, reduced motion에서도 ring이나 outline은 사라지면 안 됩니다." }]),
      item("animation cleanup은 왜 중요한가요?", "timer, requestAnimationFrame, observer, animation instance를 route change와 unmount에서 정리해야 memory leak과 stale update를 막습니다.", "unmounted component state update나 계속 도는 RAF는 성능 저하와 테스트 flaky를 만듭니다.", "cleanup test, memory profile, RAF count, route change fixture", [{ q: "CSS animation도 cleanup이 필요한가요?", answer: "CSS 자체는 브라우저가 관리하지만 animation class, transitionend listener, exit 중 남긴 DOM, `will-change` 같은 상태는 정리해야 합니다. infinite animation은 tab hidden이나 reduced motion에서 멈추는 정책도 필요합니다." }, { q: "observer는 어디서 해제하나요?", answer: "IntersectionObserver, ResizeObserver, MutationObserver는 컴포넌트 unmount나 대상 element 변경 시 disconnect합니다. scroll-triggered animation에서 observer가 stale node를 잡고 있으면 route change 후에도 callback이 돌아 성능과 상태를 흔듭니다." }, { q: "animation library instance는?", answer: "library가 반환하는 controls, timeline, spring subscription은 unmount와 target 변경 시 stop/cancel/unsubscribe합니다. 완료 callback이 늦게 와도 최신 animation id와 일치할 때만 cleanup이나 state update를 실행하게 합니다." }]),
      item("모션 QA는 무엇을 캡처해야 하나요?", "normal, rapid toggle, reduced motion, slow device, mobile viewport, keyboard-only를 캡처합니다.", "정상 속도 시연 영상만 있으면 interrupt와 접근성 회귀를 놓칩니다.", "motion QA matrix, video capture, performance trace, visual regression", [{ q: "영상 증거는 꼭 필요한가요?", answer: "timing, easing, interrupt처럼 정적 screenshot으로 보기 어려운 변경에는 짧은 영상이 유용합니다. 다만 영상만으로는 frame drop 원인을 알 수 없으므로 Performance trace, reduced motion snapshot, keyboard/focus 캡처를 같이 둡니다." }, { q: "눈으로 보는 QA의 한계는?", answer: "미세한 layout shift, transitionend 누락, focus loss, 저사양 기기 long task는 눈으로 놓치기 쉽습니다. frame chart, CLS/INP attribution, Playwright trace, visual regression이 사람이 보는 QA를 보완합니다." }, { q: "자동화 가능한 부분은?", answer: "reduced motion snapshot, key state screenshot, route transition 후 focus 위치, animation class cleanup, layout shift metric은 자동화할 수 있습니다. easing의 감성 품질이나 멀미 반응은 수동 캡처와 사용자 피드백이 필요합니다." }]),
      item("Framer Motion 같은 라이브러리는 어떻게 평가하나요?", "bundle size, SSR 호환성, layout animation, gesture 지원, reduced motion, exit transition, maintenance를 봅니다.", "기능이 많다는 이유로 도입하면 작은 UI에 과한 런타임 비용과 API lock-in이 생깁니다.", "library decision record, bundle diff, SSR smoke, reduced motion test", [{ q: "CSS로 충분한 기준은?", answer: "hover, focus, accordion, toast fade처럼 상태가 단순하고 cancel 요구가 낮으면 CSS transition과 token으로 충분합니다. drag, shared layout, spring interrupt, presence exit가 핵심 요구일 때 library 비용을 검토합니다." }, { q: "라이브러리 교체 비용은?", answer: "component API, motion token 매핑, SSR behavior, test fixture, designer handoff 표현까지 바뀝니다. 직접 import가 넓게 퍼지지 않도록 wrapper나 motion primitive를 두면 교체 비용과 reduced motion 정책 누락을 줄일 수 있습니다." }, { q: "tree-shaking은 확인했나요?", answer: "문서만 믿지 말고 실제 route bundle diff와 analyzer로 확인합니다. gesture나 layout 기능을 조금 쓰려고 전체 runtime이 들어오는지, SSR build에서 side effect가 생기는지 smoke와 bundle budget에 포함합니다." }]),
      item("transition과 animation은 어떤 상태 변화에 써야 하나요?", "transition은 상태 변화 사이의 보간이고 animation은 keyframe timeline입니다. 트리거와 제어 방식이 다릅니다.", "hover나 class toggle에 keyframe을 남발하면 제어와 중단 처리가 복잡해질 수 있습니다.", "CSS audit, state transition story, keyframe inventory, cancellation fixture", [{ q: "keyframe이 필요한 경우는?", answer: "중간 단계가 의미 있거나 반복되는 timeline이 필요할 때입니다. 예를 들어 skeleton shimmer, progress pulse, multi-step onboarding cue는 keyframe이 맞지만 단순 hover 색상 변화는 transition이 더 제어하기 쉽습니다." }, { q: "transitionend는 신뢰 가능한가요?", answer: "항상 신뢰하면 안 됩니다. 속성이 바뀌지 않거나 duration이 0이거나 element가 display none/unmount되면 발생하지 않을 수 있습니다. cleanup은 timeout guard, animation handle, reduced motion branch와 함께 설계합니다." }, { q: "delay가 UX에 미치는 영향은?", answer: "delay는 의도 확인에는 도움이 되지만 버튼 반응이나 route 전환에서는 입력 지연처럼 느껴집니다. hover tooltip delay와 action feedback delay를 분리하고, mobile/touch에서는 hover delay가 발견성을 더 낮출 수 있습니다." }]),
      item("animation event에 비즈니스 로직을 묶어도 되나요?", "핵심 상태 변경은 animation 완료에 의존하지 않아야 합니다. animation event는 시각적 cleanup 정도로 제한합니다.", "transitionend가 발생하지 않거나 reduced motion에서 생략되면 비즈니스 상태가 진행되지 않을 수 있습니다.", "state/animation separation test, reduced motion fixture, event fallback, timeout guard", [{ q: "완료 후 unmount는?", answer: "시각적 exit 완료 후 DOM을 제거하는 것은 괜찮지만 의미 상태는 이미 닫힘으로 전이되어 있어야 합니다. reduced motion에서는 즉시 unmount될 수 있으므로 animation event 없이도 cleanup 경로가 동일하게 동작해야 합니다." }, { q: "reduced motion에서는?", answer: "duration이 0이거나 transform animation을 건너뛰기 때문에 transitionend/animationend가 없을 수 있습니다. 비즈니스 로직은 사용자 action이나 서버 결과에 묶고, reduced branch에서는 cleanup을 동기적으로 실행합니다." }, { q: "이벤트 누락은 어떻게 대비하나요?", answer: "event listener에만 의존하지 않고 timeout guard, cancel handler, unmount cleanup을 둡니다. QA에는 display none 전환, rapid toggle, route change, prefers-reduced-motion 케이스를 넣어 stale DOM과 pending promise를 확인합니다." }]),
      item("motion에서 z-index와 stacking context는 왜 문제인가요?", "transform, opacity, position 등이 새로운 stacking context를 만들어 overlay 순서와 click target을 바꿀 수 있습니다.", "animation을 추가한 뒤 dropdown이 modal 뒤로 숨거나 보이지 않는 layer가 click을 가로챌 수 있습니다.", "stacking context audit, overlay story, pointer target test, z-index token", [{ q: "transform이 stacking context를 만드나요?", answer: "네. transform, opacity less than 1, filter, perspective 등은 새 stacking context를 만들 수 있습니다. card hover에 transform을 추가한 뒤 dropdown, tooltip, focus ring이 예상 z-index 위에 올라오는지 overlay story로 확인해야 합니다." }, { q: "portal을 쓰면 해결인가요?", answer: "일부 overlay 순서 문제는 해결하지만 전부는 아닙니다. portal도 top layer, modal stacking policy, focus trap, pointer-events, scroll lock과 맞아야 하며 trigger 위치 측정은 transform된 ancestor의 좌표계를 반영해야 합니다." }, { q: "z-index token은 어떻게 설계하나요?", answer: "base, raised, dropdown, sticky, modal, toast처럼 레이어 의미별 token을 두고 임의 숫자를 금지합니다. motion이 layer promotion을 만들 때 token 순서를 우회하지 않는지 stacking context audit과 pointer target test에 포함합니다." }]),
      item("responsive motion은 어떻게 다르게 설계하나요?", "화면 크기, 입력 방식, 성능 예산에 따라 거리와 duration, gesture를 조정합니다.", "desktop drawer motion을 mobile에 그대로 쓰면 이동 거리가 길고 가상 키보드와 겹칠 수 있습니다.", "viewport motion matrix, touch capture, keyboard overlay test, device performance trace", [{ q: "모바일 duration은 줄이나요?", answer: "화면 이동 거리가 길어질 수 있어 무조건 줄이기보다 distance와 입력 직접성을 같이 봅니다. bottom sheet drag처럼 손가락을 따라오는 motion은 즉각적이어야 하고, 전체 화면 전환은 짧은 duration과 reduced motion 대체를 둡니다." }, { q: "safe area와 motion은?", answer: "bottom sheet, toast, FAB가 이동할 때 notch와 home indicator 영역을 침범하지 않아야 합니다. safe-area inset을 final position뿐 아니라 animation 경로에도 반영하고, keyboard open 상태에서 transform이 입력창을 가리지 않는지 봅니다." }, { q: "orientation change 중에는?", answer: "진행 중 animation을 cancel하고 새 viewport 기준으로 layout과 target을 다시 계산하는 편이 안전합니다. 이전 transform을 유지하면 화면 밖으로 panel이 남을 수 있으므로 orientation fixture와 resize observer cleanup을 확인합니다." }]),
      item("모션을 디자인 핸드오프에 어떻게 담나요?", "상태별 timing, easing, distance, trigger, interrupt, reduced motion, 예외 조건을 문서화합니다.", "프로토타입 영상만 전달하면 구현자가 수치를 추정하게 되고 제품 전반의 일관성이 깨집니다.", "motion spec, token table, prototype reference, implementation checklist", [{ q: "디자이너와 어떤 값을 합의하나요?", answer: "duration, easing curve, delay, distance, scale, opacity, trigger, exit timing, reduced motion 대체를 token 이름으로 합의합니다. 수치가 없으면 구현자가 임의로 맞추게 되므로 component story와 token table에 함께 남깁니다." }, { q: "프로토타입과 실제 구현 차이는?", answer: "프로토타입은 frame rate, data loading, interrupt, focus, reduced motion을 생략하는 경우가 많습니다. 실제 구현에서는 transition이 API pending, route change, unmount cleanup과 만나는 지점을 별도 spec으로 보완해야 합니다." }, { q: "변경 관리는?", answer: "motion token 변경을 디자인 토큰 diff로 관리하고 영향 컴포넌트 목록과 visual regression을 연결합니다. 주요 easing/duration 변경은 QA matrix에 저사양 trace, reduced motion, keyboard-only 캡처를 포함해 릴리스합니다." }]),
      item("motion 회귀는 어떻게 자동화하나요?", "시각 회귀, Playwright screenshot/video, trace marker, reduced motion snapshot으로 주요 상태를 고정합니다.", "눈으로만 확인하면 미세한 timing 변경, focus loss, layout shift를 놓칠 수 있습니다.", "visual regression baseline, Playwright video, trace marker, CLS metric", [{ q: "animation 때문에 스냅샷이 흔들리면?", answer: "테스트 모드에서 duration을 0으로 줄이거나 clock을 제어하고, 안정된 final state를 캡처합니다. motion 자체를 검증해야 하는 케이스는 screenshot 대신 video/trace marker와 frame timing을 별도로 봅니다." }, { q: "시간을 고정할 수 있나요?", answer: "CSS variable로 duration을 test token에 매핑하거나 Playwright clock, WAAPI control, library test mode를 활용할 수 있습니다. 다만 reduced motion branch까지 고정하면 실제 사용자 설정 경로가 빠지므로 별도 snapshot을 둡니다." }, { q: "어떤 상태만 자동화하나요?", answer: "핵심 route transition, modal enter/exit 후 focus, accordion final layout, reduced motion variant, scroll-linked jank 위험 구간을 우선 자동화합니다. 모든 easing 감각을 자동화하기보다 회귀 비용이 큰 상태를 고정합니다." }]),
      item("모션과 Web Vitals는 어떻게 연결되나요?", "불필요한 layout shift는 CLS, 입력 직후 long task는 INP, loading animation이 LCP를 지연할 수 있습니다.", "시각적으로 고급스러워 보여도 실제 사용자 지표를 악화시키면 제품 품질은 낮아집니다.", "Web Vitals attribution, Performance trace, LCP element audit, INP interaction log", [{ q: "animation은 CLS에 포함되나요?", answer: "transform animation은 보통 layout shift로 계산되지 않지만 width, height, top 같은 layout 변화는 CLS에 영향을 줄 수 있습니다. skeleton과 실제 콘텐츠 크기가 다르거나 late image fade-in이 공간을 바꾸면 CLS attribution으로 잡힙니다." }, { q: "LCP 이미지 fade-in은?", answer: "LCP element가 로드된 뒤 opacity fade가 길면 사용자가 실제 콘텐츠를 늦게 본다고 느낄 수 있습니다. 중요한 hero image는 decode와 render를 우선하고 fade duration을 짧게 두며 LCP timestamp와 시각 노출을 같이 확인합니다." }, { q: "INP와 animation 관계는?", answer: "입력 직후 animation을 시작하면서 JS 계산, layout 측정, 큰 paint가 같이 발생하면 presentation delay가 늘어 INP가 나빠질 수 있습니다. rapid click trace에서 handler time, long task, frame drop을 함께 봐야 합니다." }]),
      item("모션 시스템 리뷰에서 바로 막을 신호는 무엇인가요?", "reduced motion 미지원, layout property animation 남발, 무한 loop, focus trap 깨짐, 성능 증거 없음은 막아야 합니다.", "이 신호들은 취향 문제가 아니라 접근성·성능·사용성 결함으로 이어집니다.", "REDUCED MOTION RELEASE GATE, performance trace, a11y capture, motion token diff", [{ q: "무한 loop는 모두 나쁜가요?", answer: "모두 금지는 아니지만 loading, recording, live status처럼 현재 상태를 설명할 때만 제한적으로 써야 합니다. viewport 이탈, tab hidden, 완료 상태, reduced motion에서 멈추고 CPU trace로 비용을 확인해야 합니다." }, { q: "성능 증거 최소 기준은?", answer: "변경 화면의 Performance trace, target 저사양 기기 또는 throttle 캡처, animation property audit, FPS/long task 확인이 최소입니다. scroll-linked나 layout animation이면 INP/CLS attribution과 layer count도 같이 봅니다." }, { q: "출시 후 무엇을 모니터링하나요?", answer: "route별 INP/CLS/LCP, JS error, animation 관련 long task, low-end device segment, reduced motion 사용자 피드백을 봅니다. 새 motion token 릴리스는 version 또는 feature flag로 구분해 RUM에서 회귀를 추적합니다." }]),
      item("모션 경험이 적을 때 답변은 어떻게 방어하나요?", "직접 경험 범위를 밝히고, token, reduced motion, transform-only, performance trace, visual regression으로 검증하겠다고 답합니다.", "라이브러리 이름만 말하면 실제 motion 품질을 판단하는 기준이 없다고 평가받습니다.", "motion validation checklist, prototype plan, reduced motion fixture, performance budget", [{ q: "라이브러리를 몰라도 답할 수 있나요?", answer: "가능합니다. 특정 라이브러리보다 duration/easing token, transform/opacity 우선, interrupt/cancel, reduced motion, cleanup, Performance trace라는 원칙을 말하면 됩니다. 모르는 API는 작은 prototype으로 검증하겠다고 선을 긋습니다." }, { q: "디자인 감각 질문은?", answer: "감각만으로 답하지 말고 목적과 기준으로 풀어야 합니다. 어떤 상태 변화를 설명하는지, 얼마나 빠르게 피드백해야 하는지, reduced motion에서 의미가 유지되는지, token과 실제 캡처로 맞추겠다고 답합니다." }, { q: "실무 증거는 무엇으로 대체하나요?", answer: "운영 경험이 적다면 prototype recording, reduced motion fixture, before/after Performance trace, visual regression baseline, accessibility checklist를 제시합니다. 경험을 과장하기보다 검증 계획과 판단 기준을 구체화하는 편이 낫습니다." }]),
    ],
  },
  {
    id: "engineering-frontend-graphics-3d-qa",
    title: "프론트엔드 그래픽·3D·WebGL Q&A",
    source: "프론트엔드 그래픽·3D·WebGL",
    subtitle: "SVG, Canvas, WebGL, Three.js, asset pipeline, GPU 자원, fallback을 검증 가능한 답변으로 훈련합니다.",
    questions: [
      item("SVG, Canvas, WebGL은 어떻게 선택하나요?", "DOM 접근성과 벡터 선명도가 중요하면 SVG, 많은 픽셀/도형을 직접 그리면 Canvas, 3D/GPU 대량 렌더링이면 WebGL을 고릅니다.", "표현 도구를 유행으로 고르면 접근성, 성능, hit testing, 유지보수 비용이 맞지 않습니다.", "rendering decision matrix, element count benchmark, accessibility fallback, GPU trace", [{ q: "SVG가 느려지는 기준은?", answer: "DOM node가 수천 개로 늘거나 path/filter/clipPath가 많아져 style recalculation과 paint가 frame budget을 넘으면 느려집니다. DevTools에서 paint 비용과 node 수를 보고, 그 시점부터 Canvas나 WebGL batch 렌더링을 검토합니다." }, { q: "Canvas 접근성은 어떻게 보완하나요?", answer: "canvas가 그린 차트나 도형의 의미를 DOM 표, 리스트, aria description, keyboard 조작으로 따로 제공합니다. 클릭 가능한 영역은 focus 가능한 DOM control이나 좌표 기반 hit map과 연결하고, screen reader에서 같은 데이터에 접근할 수 있어야 합니다." }, { q: "WebGL이 과한 경우는?", answer: "정적 아이콘, 단순 차트, 소수의 벡터 도형처럼 GPU resource와 context 관리 비용이 표현 이득보다 크면 과합니다. context loss, texture budget, fallback, device matrix를 감당할 이유가 없으면 SVG나 Canvas 2D가 더 낫습니다." }]),
      item("Canvas에서 접근성은 어떻게 처리하나요?", "canvas 자체는 의미 구조가 부족하므로 DOM fallback, aria description, keyboard control, offscreen data table을 제공합니다.", "시각 결과만 그리면 screen reader와 keyboard 사용자는 정보를 얻거나 조작할 수 없습니다.", "a11y fallback DOM, keyboard test, screen reader note, canvas snapshot", [{ q: "차트 canvas는 어떻게 읽히게 하나요?", answer: "차트 제목, 축, 단위, series 요약, 원본 데이터를 DOM table이나 summary region으로 제공합니다. canvas는 `aria-label`로 요약하되 세부 값 탐색은 keyboard 가능한 legend, data table, tooltip 대체 UI에서 가능해야 합니다." }, { q: "hit target은 어떻게 구현하나요?", answer: "pointer 좌표를 canvas 좌표계로 변환할 때 DPR, CSS scale, canvas offset을 반영하고, 작은 점은 실제 시각 크기보다 넓은 hit radius를 둡니다. keyboard 사용자는 같은 대상에 DOM control이나 roving tabindex로 접근하게 합니다." }, { q: "fallback이 항상 필요한가요?", answer: "핵심 정보나 조작이 canvas 안에만 있으면 필요합니다. 장식용 particle이나 배경 texture라면 숨겨도 되지만, 차트와 지도처럼 의사결정에 쓰는 그래픽은 DOM/SVG/표 fallback으로 정보 parity를 맞춰야 합니다." }]),
      item("Three.js 장면을 운영 품질로 검증하려면?", "nonblank render, camera framing, asset load, resize, context loss, reduced motion, mobile GPU budget을 확인합니다.", "로컬 데모만 통과하면 production asset 404, canvas blank, memory leak, 저사양 기기 crash를 놓칩니다.", "canvas pixel check, renderer.info, asset loading log, context loss fixture", [{ q: "검은 화면은 어떻게 디버그하나요?", answer: "asset load 에러, renderer 생성, camera 위치와 near/far, scene에 mesh가 있는지, material과 light, render loop 호출 순서로 좁힙니다. Playwright에서 canvas pixel이 모두 같은 색인지 nonblank check를 하고 `renderer.info`로 draw call이 실제 발생하는지도 봅니다." }, { q: "camera clipping은?", answer: "모델 bounding box를 기준으로 camera 거리, target, near/far plane을 계산합니다. near가 너무 크면 앞면이 잘리고 far가 너무 작으면 뒤가 사라지며, far를 과하게 키우면 depth precision이 나빠져 z-fighting이 생길 수 있습니다." }, { q: "모바일 GPU 예산은?", answer: "저사양 Android와 iOS Safari를 포함한 device matrix에서 texture 크기, draw call, vertex 수, postprocessing pass, DPR cap을 제한합니다. `renderer.info.memory`와 frame time을 기록하고 context loss나 thermal throttling이 보이면 quality preset을 낮춥니다." }]),
      item("WebGL context loss는 어떻게 대응하나요?", "contextlost/contextrestored 이벤트를 처리하고 resource 재생성, 사용자 메시지, fallback을 준비합니다.", "GPU 메모리 부족이나 브라우저 정책으로 context가 사라지면 장면이 영구 blank가 될 수 있습니다.", "context loss simulation, resource reload test, fallback capture, error log", [{ q: "context loss를 어떻게 재현하나요?", answer: "브라우저의 `WEBGL_lose_context` extension으로 테스트에서 context를 강제로 잃게 만들고 restored 경로를 확인합니다. 저메모리 모바일, 큰 texture 조합, tab background 전환도 device matrix에 넣어 실제 context loss 로그를 수집합니다." }, { q: "texture는 다시 올려야 하나요?", answer: "네. context가 복구되면 GPU에 있던 texture, buffer, render target, shader program은 유효하지 않다고 보고 재생성해야 합니다. asset cache는 원본 Blob/ImageBitmap/URL을 보관하고, GPU upload 상태는 restored 이벤트 뒤에 다시 구축합니다." }, { q: "사용자에게 무엇을 보여주나요?", answer: "짧은 복구 중 상태와 재시도, 그리고 정적 이미지나 SVG fallback을 제공합니다. 장면이 핵심 기능이면 blank canvas를 방치하지 말고 복구 실패 시 사용 가능한 대체 정보와 오류 로깅 traceId를 보여줘야 합니다." }]),
      item("texture memory는 왜 중요한가요?", "이미지 해상도, mipmap, format, 개수에 따라 GPU memory를 크게 씁니다. 화면 표시 크기보다 큰 texture는 줄여야 합니다.", "고해상도 texture를 그대로 쓰면 모바일에서 context loss와 긴 load가 발생합니다.", "texture inventory, GPU memory estimate, renderer.info.memory, asset budget", [{ q: "이미지 용량과 texture memory는 같은가요?", answer: "다릅니다. JPEG 500KB라도 GPU에 올라가면 보통 width x height x 4 bytes에 mipmap 비용까지 먹습니다. 4096px texture는 화면에 작게 보여도 GPU memory와 upload time을 크게 쓰므로 표시 크기에 맞춰 리사이즈해야 합니다." }, { q: "mipmap은 언제 쓰나요?", answer: "texture가 화면에서 축소되어 보이거나 카메라 거리에 따라 크기가 변하면 aliasing을 줄이기 위해 씁니다. 대신 약 1/3 정도 추가 memory를 쓰므로 UI sprite처럼 크기가 고정된 texture는 mipmap을 끄는 선택도 가능합니다." }, { q: "압축 texture는?", answer: "KTX2/Basis 같은 압축 texture는 GPU memory와 전송량을 줄이지만 변환 pipeline과 브라우저/GPU format 호환성이 필요합니다. asset build 단계에서 변환하고 fallback format을 준비하며 로딩 로그로 실제 선택된 format을 확인합니다." }]),
      item("draw call은 무엇이고 왜 줄이나요?", "draw call은 GPU에 그리기 명령을 보내는 단위입니다. 너무 많으면 CPU-GPU submission 비용이 커집니다.", "객체 수가 적어 보여도 material이 쪼개지거나 instancing이 없으면 frame time이 증가합니다.", "renderer.info.render.calls, frame time trace, instancing benchmark, material audit", [{ q: "mesh 수와 draw call은 같은가요?", answer: "같지 않습니다. mesh가 하나라도 material pass가 여러 개면 draw call이 늘고, mesh가 많아도 instancing이나 batching으로 줄일 수 있습니다. Three.js에서는 `renderer.info.render.calls`를 보고 material, shadow, postprocessing pass까지 함께 셉니다." }, { q: "instancing은 언제?", answer: "같은 geometry와 material을 쓰는 marker, particle, 반복 오브젝트가 많을 때 효과적입니다. 개별 transform이나 색상은 instance attribute로 넘기고, 각 객체가 서로 다른 material이나 skeleton을 가지면 이득이 줄어듭니다." }, { q: "batching의 trade-off는?", answer: "draw call은 줄지만 개별 object culling, picking, animation, material 변경이 어려워질 수 있습니다. 지도 marker나 정적 prop에는 좋고, 자주 변하는 선택 상태나 raycasting 대상은 별도 layer로 남기는 편이 관리하기 쉽습니다." }]),
      item("3D asset pipeline에서 무엇을 표준화하나요?", "포맷(GLTF/GLB), polygon budget, texture size, naming, compression, origin/scale, license, preload policy를 표준화합니다.", "디자이너 asset을 그대로 넣으면 scale 불일치, load 지연, material 깨짐, 저작권 문제가 생깁니다.", "asset checklist, GLTF validation, size budget, loading waterfall", [{ q: "GLB와 GLTF 차이는?", answer: "GLB는 geometry, material, texture 참조를 단일 binary로 묶어 배포와 cache 관리가 단순합니다. GLTF는 JSON과 외부 bin/texture 파일로 나뉘어 diff와 개별 texture 교체가 쉽지만 request 수와 경로 관리가 늘어납니다." }, { q: "Draco 압축의 비용은?", answer: "mesh 전송량은 줄지만 client decode 시간이 추가되고 worker나 decoder asset 로딩이 필요합니다. 모바일 CPU가 약하면 첫 렌더가 늦어질 수 있으므로 size 감소와 decode time을 waterfall에서 같이 비교해야 합니다." }, { q: "asset license는 왜 보나요?", answer: "3D model, HDRI, texture는 재배포와 상업적 사용 조건이 제각각입니다. CDN에 포함되는 asset은 제품 코드처럼 배포되므로 source, license, attribution, 수정 가능 여부를 pipeline metadata로 남겨야 합니다." }]),
      item("3D scene loading UX는 어떻게 설계하나요?", "progress, skeleton/preview, error fallback, retry, low-quality placeholder를 준비합니다.", "큰 asset을 기다리는 동안 blank canvas만 보이면 사용자는 장애로 인식합니다.", "loading progress trace, fallback story, asset error fixture, LCP impact", [{ q: "progress가 정확하지 않으면?", answer: "압축 해제, GPU upload, shader compile은 네트워크 progress만으로 설명되지 않습니다. 퍼센트를 과장하지 말고 단계형 상태로 보여주거나 preview 이미지를 먼저 표시하고, asset load와 first nonblank render를 별도 marker로 측정합니다." }, { q: "preview 이미지는?", answer: "서버나 build pipeline에서 생성한 poster 이미지를 canvas 자리에 먼저 놓으면 LCP와 perceived loading이 좋아집니다. preview는 최종 camera framing과 비슷해야 하고 WebGL 실패 시에도 정적 fallback으로 재사용할 수 있습니다." }, { q: "로드 실패는 어떻게 복구하나요?", answer: "asset 404, CORS, decoder 실패, texture upload 실패를 구분해 로그를 남기고 retry를 제공합니다. 재시도해도 안 되면 정적 이미지, SVG 설명, 데이터 표 같은 fallback으로 핵심 정보를 유지합니다." }]),
      item("카메라와 컨트롤은 어떻게 검증하나요?", "초기 framing, clipping plane, orbit/pan/zoom 제한, keyboard/touch 대체 조작, reset view를 확인합니다.", "카메라가 모델을 벗어나거나 near/far 설정이 잘못되면 장면이 잘리거나 z-fighting이 생깁니다.", "camera fixture, viewport screenshot, control bounds test, reset action", [{ q: "near/far는 어떻게 잡나요?", answer: "모델 bounding sphere나 box를 계산해 필요한 깊이 범위만 포함하도록 잡습니다. near를 너무 작게, far를 너무 크게 잡으면 depth precision이 떨어지므로 장면 scale을 정리하고 clipping fixture로 가까운 면과 먼 면을 확인합니다." }, { q: "모바일 pinch는?", answer: "pinch zoom과 page scroll이 충돌하지 않도록 canvas 영역, passive listener, touch-action 정책을 정합니다. 최소/최대 zoom, inertia, reset view를 실제 iOS/Android에서 확인하고 작은 control은 44px 이상 touch target을 유지합니다." }, { q: "reset view가 필요한 이유는?", answer: "사용자가 orbit/pan/zoom으로 모델을 잃어버리거나 clipping 밖으로 밀어냈을 때 복구 경로가 필요합니다. reset은 camera position, target, zoom, selected object overlay까지 초기 상태로 돌리고 keyboard로도 실행 가능해야 합니다." }]),
      item("raycasting hit test에서 주의할 점은?", "좌표 변환, device pixel ratio, canvas offset, transparent object, hidden layer, interaction priority를 고려합니다.", "CSS scale이나 DPR을 무시하면 사용자가 클릭한 위치와 선택된 객체가 다릅니다.", "raycast fixture, DPR test, pointer coordinate log, selection overlay", [{ q: "transparent mesh도 hit되나요?", answer: "기본 raycaster는 material opacity와 별개로 geometry와 교차하면 hit할 수 있습니다. 보이지 않는 helper나 transparent plane이 선택을 가로채지 않게 layer, `raycast` override, hit priority를 명시해야 합니다." }, { q: "UI overlay와 충돌하면?", answer: "DOM overlay가 pointer를 가져야 하는 영역과 canvas raycast 영역을 분리합니다. overlay는 `pointer-events`, z-index, focus order를 명확히 하고, canvas 클릭 좌표는 overlay offset과 DPR을 반영해 변환합니다." }, { q: "터치 target은 어떻게 키우나요?", answer: "작은 3D point는 화면 좌표 기준 radius를 넓혀 hit test하거나, 선택 가능한 DOM list/label을 함께 제공합니다. 손가락 입력에서는 hover가 없으므로 선택 preview, confirm action, undo를 넣어 오탭 비용을 낮춥니다." }]),
      item("Canvas 해상도와 CSS 크기는 왜 다르나요?", "CSS 크기는 화면 배치, drawing buffer 크기는 실제 픽셀 해상도입니다. DPR을 반영하되 과도한 해상도는 성능 비용을 냅니다.", "CSS만 키우면 흐릿하고, DPR을 무제한 적용하면 GPU 메모리와 fill rate가 과해집니다.", "DPR matrix, canvas buffer size, sharpness capture, frame time metric", [{ q: "retina 대응은?", answer: "CSS 크기에 `devicePixelRatio`를 곱해 drawing buffer를 설정하고 context scale이나 renderer size를 맞춥니다. 다만 WebGL에서는 DPR을 2 이하로 cap하는 등 GPU memory와 fill rate를 지키는 제한이 필요합니다." }, { q: "resize 중에는?", answer: "ResizeObserver나 layout change에서 CSS size를 읽고 buffer size와 camera aspect, renderer viewport를 함께 갱신합니다. resize가 연속으로 발생하면 debounce하거나 다음 frame에 합쳐 처리해 texture 재할당과 layout thrash를 줄입니다." }, { q: "고DPR 기기에서 제한해야 하나요?", answer: "대부분 제한해야 합니다. DPR 3-4를 그대로 쓰면 render target과 postprocessing texture가 급증하므로 sharpness와 frame time을 비교해 quality preset별 DPR cap을 둡니다." }]),
      item("OffscreenCanvas나 worker는 언제 쓰나요?", "main thread에서 비싼 drawing이나 image processing이 입력을 막을 때 고려합니다.", "worker 전송 비용과 브라우저 지원을 보지 않으면 오히려 복잡도만 늘 수 있습니다.", "main-thread trace, worker timing, transfer size, browser support matrix", [{ q: "DOM은 worker에서 접근 가능한가요?", answer: "접근할 수 없습니다. worker는 DOM layout, CSSOM, document query를 직접 다루지 못하므로 필요한 size, theme, input event는 main thread에서 메시지로 넘기고 worker는 drawing이나 계산만 담당해야 합니다." }, { q: "ImageBitmap은 왜 쓰나요?", answer: "이미지 decode와 transfer 비용을 줄이고 worker나 WebGL texture upload 경로에 더 적합하게 만들 수 있습니다. 다만 생성 후 close 처리, CORS, 브라우저 지원을 확인하고 큰 bitmap을 반복 전송하지 않도록 cache합니다." }, { q: "fallback은?", answer: "OffscreenCanvas 미지원 브라우저에서는 main thread canvas로 같은 API를 실행하거나 정적 이미지/SVG fallback을 제공합니다. worker 경로와 fallback 경로가 같은 data contract를 쓰게 해야 rendering 차이를 줄일 수 있습니다." }]),
      item("WebGL 보안/프라이버시는 무엇을 보나요?", "cross-origin texture, canvas tainting, fingerprinting surface, untrusted shader/asset 처리를 봅니다.", "CORS가 맞지 않는 이미지를 그리면 canvas readback이 막히고, 외부 asset 로딩이 privacy surface를 늘립니다.", "CORS header check, tainted canvas fixture, asset allowlist, privacy review", [{ q: "canvas tainting은?", answer: "CORS 허용 없이 cross-origin image나 video를 canvas/WebGL texture로 그리면 canvas가 tainted 되어 `toDataURL`, `getImageData`, export가 막힙니다. export 기능이 있으면 asset CDN의 CORS header와 `crossOrigin` 설정을 fixture로 검증해야 합니다." }, { q: "외부 texture는?", answer: "외부 texture는 allowlist, CORS, cache, license, content moderation을 통과한 것만 로드합니다. 사용자 제공 URL을 바로 texture로 쓰면 추적 픽셀, tainting, 과도한 해상도, 악성 파일 처리 문제가 생깁니다." }, { q: "GPU 정보 수집은?", answer: "renderer/vendor 같은 GPU 정보는 fingerprinting surface가 될 수 있어 진단에 필요한 최소 범위로만 수집합니다. 가능하면 coarse device tier나 feature support 결과만 저장하고, 사용자 식별자와 결합할 때 privacy review를 거칩니다." }]),
      item("그래픽 fallback은 어떻게 설계하나요?", "WebGL unsupported, context loss, reduced motion, low power mode에서 정적 이미지, SVG, 표, 2D canvas로 대체합니다.", "fallback 없이 핵심 정보를 3D에만 담으면 일부 사용자는 제품 기능을 사용할 수 없습니다.", "feature detection, fallback screenshot, no-WebGL browser test, content parity check", [{ q: "fallback에도 같은 정보가 있어야 하나요?", answer: "핵심 의사결정 정보는 같아야 합니다. 3D 회전이나 shader 효과는 줄여도 모델 상태, 수치, 선택 가능한 항목, 오류 메시지는 SVG, 이미지, 표, 리스트 중 하나로 접근 가능해야 합니다." }, { q: "성능 낮은 기기 감지는?", answer: "WebGL support, context creation 실패, frame time, memory pressure, DPR, reduced motion, save-data 같은 신호를 조합합니다. 단일 user agent로 판단하지 말고 quality preset을 낮추거나 사용자가 static mode로 전환할 수 있게 합니다." }, { q: "사용자 선택권은?", answer: "있어야 합니다. 자동 degrade와 별개로 정적 보기, 2D 보기, 애니메이션 끄기, 데이터 표 보기 같은 명시적 전환을 제공하면 저사양 기기와 접근성 요구를 함께 다룰 수 있습니다." }]),
      item("shader를 쓸 때 운영 리스크는?", "브라우저/GPU별 컴파일 차이, precision, 성능, 디버깅 난이도, fallback을 고려해야 합니다.", "데스크톱 GPU에서만 확인한 shader가 모바일에서 깨지거나 compile fail을 낼 수 있습니다.", "shader compile log, device matrix, GPU timing, fallback material", [{ q: "precision qualifier는?", answer: "모바일 GPU에서는 `mediump` 정밀도가 부족해 banding, z 오류, 계산 불안정이 생길 수 있습니다. fragment shader에서 필요한 값은 `highp` 지원을 확인하고, 성능과 품질을 device matrix에서 비교합니다." }, { q: "shader error는 어디서 보나요?", answer: "compile/link log를 console과 telemetry에 남기고, Three.js material의 `onBeforeCompile` 변경도 로그로 추적합니다. 실패하면 fallback material로 바꾸고 canvas nonblank check가 shader compile 실패를 잡도록 테스트합니다." }, { q: "postprocessing 비용은?", answer: "대부분 fullscreen render pass와 render target texture를 추가로 씁니다. bloom, SSAO, DOF는 GPU memory와 fill rate를 크게 쓰므로 GPU timing, pass count, DPR cap, 모바일 off preset을 함께 설계해야 합니다." }]),
      item("WebGL memory leak은 어떻게 찾나요?", "geometry, material, texture dispose, render target, event listener cleanup을 확인합니다.", "React unmount 후 Three.js resource를 dispose하지 않으면 scene 전환마다 GPU memory가 증가합니다.", "renderer.info.memory, heap/GPU profile, route transition fixture, dispose audit", [{ q: "dispose는 무엇에 호출하나요?", answer: "Three.js에서는 geometry, material, texture, render target, skeleton 관련 resource에 `dispose()`를 호출합니다. scene에서 제거하는 것만으로 GPU buffer와 texture가 해제되지 않으므로 route 반복 fixture에서 `renderer.info.memory`가 되돌아오는지 봅니다." }, { q: "texture cache는?", answer: "재사용 texture는 reference count나 asset key cache로 관리하고 마지막 consumer가 사라질 때 dispose합니다. 무제한 cache는 route 이동마다 GPU memory를 붙잡으므로 max size, eviction, context loss 재업로드 정책이 필요합니다." }, { q: "React lifecycle과 어떻게 맞추나요?", answer: "`useEffect` cleanup에서 controls, RAF, loader subscription, geometry/material/texture를 정리하고, Suspense나 route 전환 중 중복 load가 생기지 않게 cache 경계를 정합니다. react-three-fiber도 자동 dispose 예외를 쓰면 수동 책임을 명확히 해야 합니다." }]),
      item("차트 라이브러리는 어떻게 고르나요?", "데이터 규모, interaction, 접근성, export, SSR, bundle size, theming, animation 비용을 비교합니다.", "예쁜 기본 차트만 보고 고르면 대량 데이터, keyboard 접근, custom tooltip, 성능에서 막힙니다.", "library decision matrix, bundle diff, data volume benchmark, a11y audit", [{ q: "SVG chart와 canvas chart 선택은?", answer: "축, label, 접근성, 적은 데이터 포인트가 중요하면 SVG가 좋고, 수만 개 point나 heatmap처럼 draw volume이 크면 Canvas/WebGL이 유리합니다. Canvas를 고르면 DOM table, keyboard legend, export 경로를 별도로 설계해야 합니다." }, { q: "tooltip 접근성은?", answer: "hover 전용 tooltip은 부족합니다. focus와 touch로 열리고 Escape로 닫히며, screen reader가 값과 series를 읽을 수 있게 `aria-describedby`나 별도 detail panel을 제공합니다." }, { q: "서버 렌더링은?", answer: "SVG 기반 차트는 SSR snapshot이 가능하지만 DOM 측정에 의존하는 라이브러리는 hydration mismatch가 날 수 있습니다. Canvas/WebGL 차트는 server에서 placeholder나 static image를 내고 client에서 nonblank render를 확인하는 편이 안전합니다." }]),
      item("데이터 시각화에서 왜 scale이 중요한가요?", "scale은 값을 화면 위치·색·크기로 매핑하는 계약입니다. domain, clamp, log/linear, missing value 처리를 명시해야 합니다.", "축 범위나 색상 scale이 임의이면 사용자가 차이를 과대/과소 해석합니다.", "scale spec, sample dataset, visual review, edge case snapshot", [{ q: "0 기준 축은 항상 필요하나요?", answer: "막대그래프처럼 길이로 크기를 비교하는 경우에는 0 기준이 기본입니다. 선그래프나 변화율 분석처럼 패턴을 보는 경우에는 잘린 축을 쓸 수 있지만 축 break, domain, 단위를 명확히 표시해야 합니다." }, { q: "log scale은 언제?", answer: "값 범위가 몇 자릿수 이상 차이 나고 비율 비교가 의미 있을 때 씁니다. 0이나 음수는 log에 직접 올릴 수 없으므로 missing/zero 처리 정책을 표시하고 tooltip에도 원값을 제공합니다." }, { q: "missing data는 어떻게 표시하나요?", answer: "0으로 채우지 말고 결측, 미수집, 적용 불가를 구분합니다. 선은 끊거나 pattern으로 표시하고, tooltip과 legend에 이유를 적어 사용자가 실제 값 0과 데이터 부재를 혼동하지 않게 합니다." }]),
      item("색상으로만 정보를 전달하면 왜 안 되나요?", "색각 다양성과 접근성을 고려해 pattern, label, shape, text를 함께 사용해야 합니다.", "위험/정상 상태를 색만으로 구분하면 일부 사용자는 의미를 알 수 없습니다.", "contrast check, color-blind simulation, legend audit, non-color cue test", [{ q: "WCAG contrast만 보면 충분한가요?", answer: "충분하지 않습니다. contrast는 읽기 가능성을 보지만, 빨강/초록처럼 색상 차이에만 의존한 category 구분은 여전히 실패할 수 있습니다. label, shape, pattern, icon, 직접 annotation을 같이 써야 합니다." }, { q: "legend는 어떻게?", answer: "색상 swatch만 두지 말고 series 이름, pattern, marker shape를 함께 표시합니다. interactive legend라면 keyboard focus, selected state, screen reader label이 필요하고 chart 요소와 연결되는 설명이 있어야 합니다." }, { q: "heatmap은?", answer: "연속 색상 scale에는 수치 범위와 midpoint를 명시하고, 색각 친화 palette와 text label 또는 tooltip 값을 제공합니다. 중요한 threshold는 색만 바꾸지 말고 contour, border, annotation으로도 드러냅니다." }]),
      item("그래픽 export 기능은 무엇을 고려하나요?", "해상도, 배경색, 폰트 로딩, CORS image, data attribution, 개인정보 마스킹을 봅니다.", "화면 캡처를 그대로 저장하면 깨진 폰트, 투명 배경, 외부 이미지 차단, 민감 정보 유출이 생길 수 있습니다.", "export fixture, pixel diff, CORS test, redaction checklist", [{ q: "SVG export와 PNG export 차이는?", answer: "SVG는 벡터라 확대와 편집에 좋지만 외부 font, image, CSS 의존성을 포함해야 합니다. PNG는 공유가 쉽고 canvas/WebGL 결과를 담기 좋지만 해상도와 배경색, DPR, tainted canvas 문제를 관리해야 합니다." }, { q: "폰트는 어떻게 포함하나요?", answer: "SVG export는 font-family만 적으면 다른 환경에서 바뀔 수 있어 path 변환, subset embed, 또는 시스템 fallback 정책을 정합니다. PNG export는 font load 완료 후 렌더링하고 pixel diff로 깨진 글꼴을 확인합니다." }, { q: "민감 정보는?", answer: "export 전에 사용자명, 위치, 계정 ID, 내부 annotation 같은 데이터를 redaction list로 처리합니다. canvas screenshot은 화면에 보이는 overlay까지 저장될 수 있으므로 export 전용 render path와 개인정보 fixture가 필요합니다." }]),
      item("3D와 React 상태를 어떻게 연결하나요?", "렌더 루프의 mutable scene state와 React declarative state 경계를 명확히 합니다. 자주 변하는 frame state는 React rerender로 밀어넣지 않습니다.", "매 프레임 React state를 업데이트하면 렌더링 비용과 input latency가 커집니다.", "render count, frame loop trace, state boundary note, interaction fixture", [{ q: "react-three-fiber는 어떻게 다르나요?", answer: "Three.js 객체를 React tree로 선언하지만 frame loop와 GPU resource는 여전히 Three.js 규칙을 따릅니다. `useFrame`에서 매 프레임 React state를 set하지 말고 refs나 external store를 쓰며, dispose와 invalidate 정책을 확인해야 합니다." }, { q: "state store를 써야 하나요?", answer: "선택 object, tool mode, camera preset처럼 UI와 scene이 공유하는 상태가 많으면 store가 유용합니다. 반면 particle 위치나 animation time 같은 frame state는 store에 넣지 말고 mutable buffer나 shader uniform으로 관리합니다." }, { q: "UI overlay와 scene state 동기화는?", answer: "raycast selection, camera projection, DOM overlay 위치를 같은 frame 기준으로 계산해야 합니다. resize, DPR 변경, camera 이동 시 overlay 좌표를 갱신하고 keyboard focus는 DOM overlay가 담당하게 분리합니다." }]),
      item("Animation loop는 언제 멈춰야 하나요?", "정적 장면, hidden tab, offscreen canvas, reduced motion에서는 demand-driven render나 pause를 고려합니다.", "항상 requestAnimationFrame을 돌리면 배터리와 CPU를 낭비합니다.", "RAF count, visibilitychange test, battery/CPU profile, renderer invalidation log", [{ q: "invalidate 방식은?", answer: "상태가 바뀔 때만 render를 요청하는 방식입니다. camera 조작, asset load 완료, resize, selection 변경에서는 invalidate하고 정적 장면에서는 RAF를 멈춰 CPU와 배터리를 줄입니다." }, { q: "tab hidden에서 브라우저가 알아서 줄이지 않나요?", answer: "대부분 throttle하지만 loader, video texture, worker, timer가 계속 비용을 만들 수 있습니다. `visibilitychange`에서 RAF, controls damping, video texture update, analytics sampling을 멈추고 복귀 시 한 번 invalidate합니다." }, { q: "동영상 texture는?", answer: "video texture는 매 frame GPU upload가 발생할 수 있어 보이지 않거나 hidden tab이면 pause해야 합니다. reduced motion에서는 정지 poster로 대체하고, 재생 중에는 resolution과 frame rate를 quality preset에 맞춥니다." }]),
      item("postprocessing은 어떤 비용이 있나요?", "bloom, SSAO, depth of field 등은 추가 render pass와 texture memory를 요구합니다.", "시각 효과를 많이 쌓으면 저사양 기기에서 frame budget을 초과합니다.", "render pass count, GPU timing, effect toggle benchmark, quality setting", [{ q: "bloom은 언제 과한가요?", answer: "텍스트, 데이터 label, UI overlay의 contrast를 흐리거나 bright pass 때문에 화면 대부분이 번지면 과합니다. threshold, radius, intensity를 제한하고 reduced motion/low quality preset에서는 끄거나 static highlight로 바꿉니다." }, { q: "quality preset은?", answer: "DPR cap, shadow map size, render target scale, postprocessing pass, texture LOD를 묶어 low/medium/high로 정의합니다. frame time과 `renderer.info`를 기준으로 자동 degrade하되 사용자가 고정 선택할 수 있게 합니다." }, { q: "모바일에서 끄나요?", answer: "기본은 보수적으로 끄거나 낮춥니다. 모바일 GPU는 fill rate와 thermal throttling에 취약하므로 bloom/SSAO/DOF를 효과별 toggle로 측정하고 핵심 정보 전달에 필요한 효과만 남깁니다." }]),
      item("WebGL 디버깅은 어떤 순서로 하나요?", "console error, shader compile, asset load, camera, material, light, render loop, context 상태를 순서대로 봅니다.", "검은 화면을 한 번에 추측하면 camera clipping, light 없음, material 문제, asset 경로 문제를 구분하지 못합니다.", "debug checklist, renderer.info, asset log, camera helper screenshot", [{ q: "scene에 있는데 안 보이면?", answer: "camera frustum, object scale과 position, layer, visibility, material side, clipping plane을 확인합니다. bounding box helper와 axes helper를 켜고 `renderer.info.render.calls`가 0인지, draw는 되지만 화면 밖인지 분리합니다." }, { q: "light 문제는?", answer: "PBR material은 light나 environment map이 없으면 거의 검게 보일 수 있습니다. 임시로 MeshBasicMaterial을 적용해 geometry와 camera를 확인한 뒤 light intensity, color space, tone mapping, HDRI load를 봅니다." }, { q: "material이 검게 나오면?", answer: "texture color space, normal map 방향, missing UV, shader compile error, environment map, alphaTest를 확인합니다. fallback material로 바꿨을 때 보이면 asset/material pipeline 문제이고, 여전히 안 보이면 camera나 geometry 문제일 가능성이 큽니다." }]),
      item("그래픽 기능의 테스트 자동화는 어떻게 하나요?", "canvas nonblank, pixel threshold, screenshot diff, interaction hit test, fallback rendering을 자동화합니다.", "DOM assertion만으로는 canvas/WebGL이 실제로 그려졌는지 알 수 없습니다.", "canvas pixel check, Playwright screenshot, hit test fixture, fallback test", [{ q: "픽셀 테스트가 flaky하면?", answer: "GPU, font, anti-aliasing 차이 때문에 전체 pixel exact match는 흔들릴 수 있습니다. nonblank 영역, 주요 색상 histogram, bounding box 위치, threshold diff처럼 목적에 맞는 신호를 쓰고 deterministic seed와 고정 camera를 둡니다." }, { q: "threshold는?", answer: "허용 diff는 배경 noise가 아니라 검증하려는 위험에 맞춥니다. canvas blank, asset 누락, camera 이탈은 낮은 threshold로 잡고, shader anti-aliasing 차이는 region별 허용치를 둬 false positive를 줄입니다." }, { q: "3D deterministic render는?", answer: "camera, time, random seed, asset version, DPR, renderer size, animation frame을 고정합니다. shadow나 postprocessing이 환경별로 흔들리면 테스트 preset에서는 효과를 낮추고 핵심 geometry와 fallback만 검증합니다." }]),
      item("그래픽 성능 예산은 어떻게 잡나요?", "target device, FPS, frame time, memory, asset size, initial load, interaction latency를 정합니다.", "데모 장비 기준으로만 잡으면 실제 사용자 기기에서 blank나 jank가 발생합니다.", "device performance matrix, renderer stats, asset budget, RUM custom metric", [{ q: "30fps도 괜찮은가요?", answer: "정적 탐색이나 비핵심 3D preview는 30fps도 수용될 수 있지만 drag, drawing, camera control처럼 입력과 붙은 상호작용은 더 높은 frame rate가 필요합니다. 목표는 device tier별로 frame time과 input latency를 같이 정합니다." }, { q: "asset budget은?", answer: "초기 GLB/texture 크기, decode time, GPU upload time, texture max size, polygon 수, draw call 수를 route별로 둡니다. `renderer.info`, loading waterfall, bundle analyzer를 연결해 asset pipeline에서 초과를 막습니다." }, { q: "사용자 기기별 degrade는?", answer: "저사양 기기에서는 DPR, shadow, postprocessing, texture LOD, instance count를 낮춥니다. degrade 결과가 기능 손실이 되지 않도록 fallback, quality setting, data table이나 static view를 함께 제공합니다." }]),
      item("지도/공간 UI에서 무엇을 주의하나요?", "tile loading, coordinate projection, clustering, marker count, hit testing, accessibility list fallback을 봅니다.", "모든 marker를 DOM으로 찍으면 성능이 떨어지고, 지도에만 정보를 두면 접근성이 낮습니다.", "marker benchmark, cluster test, tile waterfall, list fallback audit", [{ q: "clustering 기준은?", answer: "화면 zoom, marker 밀도, 사용자 task에 따라 기준을 잡습니다. 너무 빨리 묶으면 중요한 위치가 숨고, 너무 늦게 묶으면 DOM 또는 WebGL draw call이 늘어나므로 viewport별 benchmark와 hit test를 봅니다." }, { q: "좌표계 변환은?", answer: "위도/경도, tile projection, screen pixel 좌표 변환을 명확히 분리해야 합니다. DPR, map zoom, CSS transform을 반영하지 않으면 marker와 hit target이 어긋나므로 좌표 로그와 overlay screenshot으로 검증합니다." }, { q: "지도 없는 대체 UI는?", answer: "장소명, 거리, 상태, 필터 결과를 리스트나 표로 제공합니다. 지도 tile이나 WebGL layer가 실패해도 keyboard와 screen reader 사용자는 같은 장소를 찾고 선택할 수 있어야 합니다." }]),
      item("그래픽 PR 리뷰에서 막아야 할 위험은?", "fallback 없음, asset budget 없음, dispose 누락, context loss 미대응, 접근성 대체 없음, canvas blank 검증 없음입니다.", "이 항목들은 나중에 고치기 어렵고 사용자 환경별 장애로 바로 이어집니다.", "CANVAS WEBGL AUTOMATION GATE, renderer.info, fallback capture, a11y audit", [{ q: "최소 증거는?", answer: "canvas nonblank screenshot, fallback screenshot, `renderer.info` draw call/memory, asset waterfall, context loss 또는 no-WebGL 캡처, keyboard/a11y 대체 경로가 최소입니다. Three.js 변경이면 dispose audit과 mobile device capture도 요구합니다." }, { q: "디자인 시안만 있으면?", answer: "시안은 목표 화면일 뿐 운영 증거가 아닙니다. 실제 asset pipeline, texture 크기, camera framing, loading/error state, fallback, device matrix 캡처가 있어야 구현 가능성과 실패 경로를 판단할 수 있습니다." }, { q: "운영 모니터링은?", answer: "blank canvas signal, asset load error, context loss count, WebGL support 실패, frame time sample, quality preset 분포를 봅니다. release version과 device tier로 나눠야 특정 GPU나 브라우저 회귀를 찾을 수 있습니다." }]),
      item("그래픽 경험이 적을 때 어떻게 답변하나요?", "도구 이름보다 선택 기준, GPU 자원, fallback, 접근성, 자동화 검증을 말하고 직접 경험 범위를 분리합니다.", "Three.js API만 나열하면 운영 가능한 그래픽 기능을 설계할 수 있는지 증명하지 못합니다.", "graphics decision checklist, prototype validation plan, device matrix, fallback spec", [{ q: "Three.js를 깊게 몰라도?", answer: "깊은 API를 모른다면 SVG/Canvas/WebGL 선택 기준, texture와 draw call 예산, context loss, fallback, nonblank 테스트를 중심으로 답합니다. 모르는 부분은 작은 prototype에서 `renderer.info`와 device matrix로 검증하겠다고 범위를 분리합니다." }, { q: "수학 질문이 나오면?", answer: "vector, matrix, camera projection 같은 기본 개념을 아는 범위에서 설명하고, 필요한 계산은 라이브러리 helper와 visual fixture로 검증한다고 답합니다. 중요한 건 수식 암기가 아니라 clipping, hit test, 좌표 변환 오류를 테스트로 잡는 태도입니다." }, { q: "포트폴리오 증거는?", answer: "완성 데모만보다 loading/error/fallback 화면, mobile capture, canvas pixel test, asset budget, texture 최적화 전후, context loss 대응 로그가 더 설득력 있습니다. 운영 품질을 보여주는 체크리스트와 측정값을 함께 제시합니다." }]),
    ],
  },
  {
    id: "engineering-frontend-performance-qa",
    title: "프론트엔드 성능·진단 Q&A",
    source: "프론트엔드 성능·진단",
    subtitle: "Web Vitals, 번들, 렌더링, DevTools, React Profiler, RUM을 수치와 증거로 답합니다.",
    questions: [
      item("프론트엔드 성능을 어디서부터 진단하나요?", "사용자 영향 지표인 LCP, INP, CLS, error rate, route별 RUM을 먼저 보고 network, main thread, rendering, backend wait로 분해합니다.", "Lighthouse 점수만 보면 실제 사용자 기기·네트워크·로그인 상태의 병목을 놓칩니다.", "RUM dashboard, Web Vitals attribution, Performance trace, network waterfall", [{ q: "실험실 점수와 RUM이 다르면?", answer: "lab은 고정 기기와 네트워크에서 회귀를 재현하는 데 좋고, RUM은 실제 브라우저·지역·로그인 상태의 p75를 보여줍니다. 차이가 나면 route, device tier, connection, release version으로 RUM을 나누고 같은 조건을 Lighthouse나 WebPageTest에 맞춰 재현합니다." }, { q: "route별로 봐야 하는 이유는?", answer: "홈, 검색, checkout, dashboard는 LCP element, API chain, JS chunk, third-party 의존성이 다릅니다. 전체 평균만 보면 핵심 route의 p75 LCP나 INP 악화를 내부 페이지의 좋은 수치가 가릴 수 있습니다." }, { q: "성능 문제를 백엔드와 어떻게 나누나요?", answer: "waterfall에서 DNS/TLS, TTFB, download, render-blocking, JS execution을 분리하고 Server-Timing header로 backend 처리 시간을 표시합니다. TTFB 이후 LCP resource 발견이나 hydration이 늦으면 프론트 병목이고, TTFB 자체가 route별로 높으면 API·SSR·edge cache를 같이 봅니다." }]),
      item("LCP가 느릴 때 무엇을 보나요?", "TTFB, render-blocking resource, LCP element load priority, image size/format, client rendering delay를 나눠 봅니다.", "이미지만 압축하면 서버 응답 지연이나 JS hydration 지연 때문에 개선이 안 될 수 있습니다.", "LCP attribution, server timing, priority hint, image audit", [{ q: "LCP element가 바뀌면?", answer: "viewport, 로그인 상태, A/B variant마다 LCP 후보가 hero image, 제목, skeleton, video poster로 바뀔 수 있습니다. Web Vitals attribution으로 실제 element selector를 기록하고 각 후보의 size, priority, cache hit, render delay를 따로 봅니다." }, { q: "preload는 언제?", answer: "초기 viewport의 LCP 이미지나 핵심 font처럼 브라우저가 늦게 발견하지만 반드시 필요한 resource에만 씁니다. preload 후 실제 사용되지 않거나 너무 많이 걸면 bandwidth 경쟁으로 JS/CSS와 LCP 이미지 우선순위가 꼬일 수 있습니다." }, { q: "SSR이 항상 LCP에 좋은가요?", answer: "항상 그렇지 않습니다. SSR은 초기 HTML 표시를 앞당길 수 있지만 서버 TTFB가 크거나 hydration JS가 무거우면 LCP와 INP가 같이 나빠집니다. SSR, SSG, CSR을 같은 route에서 TTFB, LCP render delay, hydration cost로 비교해야 합니다." }]),
      item("INP가 나쁠 때 어떻게 좁히나요?", "느린 interaction을 찾고 event handler, long task, render cost, layout, third-party script를 분해합니다.", "평균 입력 지연이 괜찮아도 특정 컴포넌트의 긴 작업이 p75/p98을 망칠 수 있습니다.", "INP attribution, long task trace, React Profiler, interaction marker", [{ q: "FID와 INP 차이는?", answer: "FID는 첫 입력의 delay만 봤지만 INP는 페이지 생애 전체 interaction의 latency를 대표합니다. 그래서 최초 클릭은 빠르더라도 필터 변경, 검색 입력, 모달 열기에서 long task나 큰 commit이 있으면 INP가 나빠집니다." }, { q: "debounce로 해결되나요?", answer: "일부 입력 처리에는 도움이 되지만 클릭 후 화면 반응 자체가 늦거나 render commit이 길면 debounce만으로는 부족합니다. expensive calculation을 worker로 옮기거나 render 범위를 줄이고, immediate feedback을 먼저 보여 INP interaction delay와 presentation delay를 줄여야 합니다." }, { q: "React rerender와 INP 연결은?", answer: "interaction 뒤에 넓은 context 구독, 큰 list render, 불필요한 memo miss가 발생하면 main thread가 막혀 INP가 올라갑니다. React Profiler의 interaction commit과 DevTools Performance의 long task를 marker로 맞춰 어떤 component commit이 느린지 확인합니다." }]),
      item("CLS는 왜 생기나요?", "이미지/광고/폰트/동적 콘텐츠의 크기 예약 부족, late injection, hydration 차이로 layout shift가 생깁니다.", "시각적으로 작은 이동도 사용자가 버튼을 잘못 누르게 만들 수 있습니다.", "CLS attribution, layout shift rectangles, image dimension audit, font loading strategy", [{ q: "animation도 CLS인가요?", answer: "transform과 opacity 기반 animation은 보통 layout shift로 잡히지 않지만 top, height, margin처럼 layout을 바꾸는 animation은 CLS를 만들 수 있습니다. Performance 패널의 layout shift rectangle로 움직인 요소와 입력 직후 shift 예외 여부를 확인합니다." }, { q: "skeleton이 CLS를 줄이나요?", answer: "skeleton이 최종 콘텐츠와 같은 높이, aspect-ratio, spacing을 예약하면 줄입니다. 반대로 skeleton 높이가 실제 카드나 광고보다 작거나 hydration 후 DOM 구조가 바뀌면 skeleton 자체가 CLS 원인이 됩니다." }, { q: "font swap은?", answer: "font-display swap은 텍스트를 빨리 보이게 하지만 fallback과 웹폰트 metrics가 다르면 글줄이 밀려 CLS가 생깁니다. size-adjust, ascent/descent override, subset, preload를 조합해 FOIT와 layout shift 사이를 조정합니다." }]),
      item("번들 크기는 어떻게 줄이나요?", "route-level code splitting, dependency audit, tree shaking, dynamic import, polyfill 점검, asset 압축을 순서대로 봅니다.", "무작정 minify만 하면 큰 dependency, 중복 polyfill, 초기 route에 묶인 admin code는 남아 있습니다.", "bundle analyzer, coverage tab, route chunk map, dependency diff", [{ q: "dynamic import는 어디에?", answer: "초기 route의 LCP와 interaction에 필요 없는 admin panel, editor, chart, modal, locale data, heavy validator에 우선 적용합니다. import boundary가 너무 잘게 쪼개져 request overhead가 커지지 않도록 route chunk map과 waterfall을 같이 봅니다." }, { q: "tree shaking이 안 되는 이유는?", answer: "package가 sideEffects를 과하게 선언했거나 CommonJS, namespace import, top-level side effect 때문에 bundler가 제거하지 못할 수 있습니다. bundle analyzer에서 남은 module을 확인하고 ESM entry, 직접 import, dependency 교체를 검토합니다." }, { q: "gzip만 보면 충분한가요?", answer: "충분하지 않습니다. gzip/brotli 전송량이 작아도 parse, compile, execute 비용은 남고 모바일 CPU에서는 JS 실행이 INP와 hydration readiness를 늦춥니다. compressed size와 uncompressed JS, coverage, main-thread execution time을 같이 봅니다." }]),
      item("React 렌더링 병목은 어떻게 찾나요?", "Profiler로 commit duration, render count, why-did-render 원인, context 구독 범위, memoization 효과를 봅니다.", "useMemo/useCallback을 무작정 넣으면 비용은 늘고 실제 rerender 원인은 그대로일 수 있습니다.", "React Profiler export, render count, flamegraph, memoization benchmark", [{ q: "memo는 언제 효과가 있나요?", answer: "같은 props로 자주 렌더되는 비싼 component가 있고 parent update가 잦을 때 효과가 있습니다. props identity가 매번 바뀌거나 render 비용이 작으면 비교 비용만 늘 수 있으므로 Profiler에서 commit duration과 render count 개선을 확인해야 합니다." }, { q: "context가 왜 문제인가요?", answer: "하나의 큰 context value가 바뀌면 그 값을 구독하는 넓은 subtree가 다시 렌더될 수 있습니다. state를 분리하거나 selector 기반 store를 쓰고, theme·auth·filter처럼 갱신 빈도가 다른 값은 provider를 나눠 commit 범위를 줄입니다." }, { q: "key 변경은 어떤 영향을 주나요?", answer: "key가 바뀌면 React는 기존 subtree를 재사용하지 않고 unmount/remount합니다. list reorder나 route param 처리에서 key를 잘못 주면 state 손실, effect 재실행, image/font 재로드, 큰 commit으로 INP 악화가 생길 수 있습니다." }]),
      item("list virtualization은 언제 필요한가요?", "DOM node 수와 render cost가 사용자 기기에서 frame budget을 넘을 때 사용합니다.", "무조건 virtualization을 넣으면 accessibility, find-in-page, dynamic height, scroll restoration이 어려워집니다.", "DOM node count, scroll FPS, virtualization fixture, a11y fallback", [{ q: "동적 높이는?", answer: "동적 높이는 측정 cache, estimated size, ResizeObserver, overscan 조정이 필요합니다. 높이 추정이 틀리면 scroll jump와 CLS처럼 보이는 이동이 생기므로 row measurement invalidation과 scroll restoration fixture를 둡니다." }, { q: "SEO 콘텐츠에도 쓰나요?", answer: "검색 노출이 중요한 본문이나 상품 목록의 핵심 콘텐츠에는 조심해야 합니다. crawler와 no-JS 환경에서 콘텐츠가 사라질 수 있으므로 SSR/SSG로 의미 있는 초기 목록을 제공하거나 페이지네이션을 우선 검토합니다." }, { q: "가상 리스트에서 focus는?", answer: "focus된 row가 unmount되지 않게 overscan과 active item 보존을 설계해야 합니다. keyboard 이동, screen reader announce, scroll restoration을 테스트하고, DOM에 없는 항목 수와 위치는 aria-setsize나 별도 상태로 설명합니다." }]),
      item("image optimization은 무엇을 포함하나요?", "format, responsive srcset, intrinsic size, lazy loading, priority, CDN caching, decoding 전략을 포함합니다.", "모든 이미지를 lazy로 두면 hero LCP가 늦어지고, 원본 해상도를 그대로 쓰면 네트워크 비용이 큽니다.", "image waterfall, LCP element audit, srcset test, CDN cache header", [{ q: "WebP/AVIF 선택은?", answer: "AVIF는 압축률이 좋지만 인코딩 비용과 decode 지연이 있을 수 있고, WebP는 호환성과 decode 안정성이 좋습니다. 사진, 투명 이미지, 썸네일별로 byte size와 decode time을 비교하고 picture/source fallback을 둡니다." }, { q: "lazy loading의 함정은?", answer: "초기 viewport의 hero나 LCP 이미지를 lazy로 두면 브라우저가 요청을 늦게 시작합니다. fold 근처 이미지는 적절한 rootMargin이나 eager loading을 쓰고, below-the-fold만 lazy로 두어 waterfall에서 LCP request가 앞에 있는지 확인합니다." }, { q: "priority는 언제 높이나요?", answer: "초기 viewport에서 LCP 후보인 이미지나 poster처럼 사용자에게 첫 화면을 만드는 resource에만 높입니다. 여러 이미지에 fetchpriority high를 주면 CSS, font, JS와 경쟁해 전체 LCP가 느려질 수 있습니다." }]),
      item("font가 성능에 미치는 영향은?", "font file size, preload, display strategy, subset, fallback metric이 LCP와 CLS에 영향을 줍니다.", "웹폰트를 늦게 로드하거나 fallback metrics가 다르면 텍스트가 밀리고 CLS가 생깁니다.", "font waterfall, font-display audit, CLS attribution, subset diff", [{ q: "font-display swap은 항상 좋은가요?", answer: "읽기 시작을 빠르게 하지만 fallback과 실제 font의 폭·높이가 다르면 텍스트 재배치가 생깁니다. 브랜드 font가 필수인 hero는 preload와 metric override를 쓰고, 본문은 system font fallback으로 LCP와 CLS를 안정화할 수 있습니다." }, { q: "variable font는?", answer: "여러 weight/style 파일을 하나로 줄이면 request와 cache 관리가 좋아질 수 있지만, 필요한 축보다 파일이 크면 오히려 손해입니다. 실제 사용하는 weight, unicode-range, compression 후 size를 비교하고 unused axis를 제거합니다." }, { q: "한글 폰트 최적화는?", answer: "한글은 glyph 수가 많아 subset과 unicode-range 전략이 중요합니다. 핵심 화면에 필요한 글자만 preload하고 나머지는 지연 로드하거나 system fallback을 쓰며, font waterfall과 CLS attribution으로 효과를 확인합니다." }]),
      item("third-party script는 어떻게 관리하나요?", "비즈니스 가치, load timing, async/defer, sandbox, consent, long task 영향, 장애 격리를 봅니다.", "analytics/chat script가 main thread를 막거나 개인정보 동의 전에 실행될 수 있습니다.", "third-party inventory, long task attribution, consent test, script loading policy", [{ q: "defer와 async 차이는?", answer: "defer는 HTML parsing을 막지 않고 실행 순서를 보존하며 DOMContentLoaded 전에 실행됩니다. async는 다운로드 완료 즉시 실행되어 순서가 보장되지 않아 tag 간 의존성이 있거나 hydration 중 main thread를 빼앗으면 INP와 초기 렌더를 흔들 수 있습니다." }, { q: "태그 매니저 위험은?", answer: "코드 리뷰 밖에서 script가 추가되고 consent, CSP, performance budget을 우회할 수 있습니다. tag inventory, owner, trigger 조건, long task attribution, 개인정보 동의 상태를 정기적으로 점검해야 합니다." }, { q: "서드파티 장애는 어떻게 격리하나요?", answer: "timeout, async loading, iframe sandbox, consent gate, circuit breaker를 두고 핵심 UI render path와 분리합니다. third-party가 느리거나 실패해도 LCP element, checkout action, analytics queue flush가 멈추지 않는 fixture를 둡니다." }]),
      item("Network waterfall에서 무엇을 읽나요?", "DNS, TCP/TLS, TTFB, download, priority, blocking, request chain, cache hit/miss를 봅니다.", "총 시간만 보면 우선순위 문제, render-blocking chain, cache 미스 원인을 놓칩니다.", "HAR, DevTools waterfall, cache header, priority column", [{ q: "TTFB가 크면 무조건 백엔드인가요?", answer: "아닙니다. DNS/TLS, edge miss, redirect, server queue, SSR data fetch, auth middleware가 모두 TTFB에 포함될 수 있습니다. Server-Timing, CDN cache status, redirect chain을 같이 봐야 API 처리와 네트워크·edge 문제를 나눌 수 있습니다." }, { q: "HTTP/2면 waterfall이 사라지나요?", answer: "사라지지 않습니다. multiplexing으로 connection 병목은 줄지만 priority, request discovery, server push 오용, 큰 JS download 경쟁은 여전히 보입니다. waterfall에서는 resource가 언제 발견됐고 어떤 요청이 LCP resource를 밀었는지 봅니다." }, { q: "cache hit은 어디서 보나요?", answer: "DevTools size column의 memory/disk cache, response header의 Age, x-cache, cf-cache-status 같은 CDN header, RUM resource timing의 transferSize로 확인합니다. cache hit인데 느리면 main thread decode나 render delay도 같이 봐야 합니다." }]),
      item("Service Worker는 성능에 어떻게 쓰나요?", "offline, precache, runtime cache, navigation preload, stale-while-revalidate에 쓸 수 있지만 versioning과 cache invalidation이 핵심입니다.", "잘못된 SW는 오래된 JS를 계속 제공해 배포 후 장애를 만들 수 있습니다.", "SW lifecycle log, cache inventory, update flow test, offline fixture", [{ q: "skipWaiting은 위험한가요?", answer: "새 SW가 즉시 활성화되면 현재 탭의 HTML은 이전 bundle을 참조하는데 cache는 새 asset으로 바뀌는 식의 version mismatch가 생길 수 있습니다. reload prompt, clients.claim 조건, manifest version 검사를 설계해야 합니다." }, { q: "API cache는?", answer: "읽기 전용이고 freshness 허용 범위가 있는 API에만 runtime cache를 적용합니다. 사용자별 응답, 권한, 결제, 재고처럼 stale data가 문제를 만드는 endpoint는 no-store나 짧은 revalidation을 쓰고 cache key에 auth scope를 섞지 않도록 주의합니다." }, { q: "오래된 bundle은 어떻게 제거하나요?", answer: "SW activate 단계에서 현재 precache manifest에 없는 cache를 정리하고, content hash asset과 HTML cache policy를 분리합니다. release 후 cache inventory와 update flow 테스트로 사용자가 이전 JS에 갇히지 않는지 확인합니다." }]),
      item("SSR/SSG/CSR 성능 trade-off는?", "SSR은 초기 HTML과 SEO에 유리하지만 서버 비용과 hydration 비용이 있고, CSR은 단순하지만 초기 표시가 늦을 수 있습니다. SSG는 변경 빈도와 개인화 제약을 봅니다.", "렌더링 방식을 하나의 정답으로 고르면 데이터 개인화, cache, 배포 복잡도에서 실패합니다.", "rendering decision record, TTFB/LCP comparison, hydration trace, cache policy", [{ q: "SSR이면 SEO가 끝인가요?", answer: "아닙니다. SSR은 crawler가 볼 HTML을 제공하지만 metadata, canonical, structured data, status code, robots 정책, hydration 후 content mismatch까지 맞아야 합니다. 성능 쪽에서는 SSR HTML 이후 LCP resource와 JS hydration도 함께 봅니다." }, { q: "hydration 비용은?", answer: "SSR HTML을 interactive하게 만들기 위해 JS를 download, parse, execute하고 event handler를 붙이는 비용입니다. component tree가 크면 초기 LCP는 좋아도 INP readiness가 늦어질 수 있어 hydration trace와 JS coverage로 줄입니다." }, { q: "ISR은 언제?", answer: "콘텐츠가 자주 바뀌지만 요청마다 SSR할 필요는 없고, 일정 시간 stale을 허용할 수 있을 때 적합합니다. revalidate 주기, cache purge, preview, 개인화 제외 조건을 명확히 해야 stale content와 cache stampede를 피합니다." }]),
      item("Hydration 성능은 어떻게 개선하나요?", "JS 크기, component island, lazy hydration, server component, event handler 수, browser-only code를 줄입니다.", "HTML은 빨리 보이는데 상호작용이 늦으면 사용자는 페이지가 멈췄다고 느낍니다.", "hydration trace, JS coverage, INP after load, interaction readiness marker", [{ q: "partial hydration은?", answer: "페이지 전체를 한 번에 hydrate하지 않고 실제 상호작용이 필요한 island만 hydrate하는 방식입니다. static content와 interactive widget을 분리하면 JS 실행과 event handler 수가 줄어 LCP 이후 INP readiness가 좋아질 수 있습니다." }, { q: "server component 장점은?", answer: "client로 보내는 JS와 data fetching waterfall을 줄일 수 있습니다. 다만 client boundary가 많거나 큰 props를 넘기면 이득이 줄고, cache와 streaming 전략을 함께 설계해야 합니다." }, { q: "interactive marker는 어떻게?", answer: "사용자가 누를 수 있는 주요 control이 실제 handler를 받을 준비가 된 시점에 performance.mark를 남깁니다. hydration complete, first input handled, route transition ready 같은 marker를 RUM과 trace에 연결해 보이는 시점과 조작 가능한 시점을 구분합니다." }]),
      item("CSS 성능은 어디서 문제가 되나요?", "selector 비용보다 style recalculation, layout invalidation, CSS size, unused rules, critical CSS가 실무에서 더 중요합니다.", "거대한 CSS와 late loaded stylesheet는 render blocking과 style 계산 비용을 키웁니다.", "Coverage tab, style recalculation trace, critical CSS audit, CSS bundle diff", [{ q: "복잡한 selector는?", answer: "현대 브라우저에서는 selector 자체보다 DOM 규모, style invalidation 범위, 자주 바뀌는 class가 더 큰 영향을 주는 경우가 많습니다. 그래도 deep descendant selector와 전역 rule이 많은 화면은 style recalculation trace와 Coverage로 정리합니다." }, { q: "CSS-in-JS는 느린가요?", answer: "런타임에 style을 생성·삽입하는 방식은 초기 render와 interaction 중 style recalculation 비용을 만들 수 있습니다. build-time extraction, critical CSS, stable className, theme 변경 범위를 확인해 실제 trace로 판단합니다." }, { q: "critical CSS는 언제?", answer: "초기 viewport 렌더에 필요한 CSS가 큰 stylesheet 뒤에 묶여 LCP가 늦을 때 씁니다. inline critical CSS가 너무 커지면 HTML TTFB와 cache 효율이 나빠지므로 route별 above-the-fold에 제한합니다." }]),
      item("메모리 누수는 어떻게 찾나요?", "heap snapshot, allocation timeline, detached DOM, event listener, timer, cache growth, WebGL resource를 봅니다.", "route를 반복 이동할 때 memory가 계속 증가하면 결국 tab crash나 성능 저하로 이어집니다.", "heap snapshot diff, detached node count, listener audit, route loop test", [{ q: "React에서 흔한 누수는?", answer: "unmount 후 남은 event listener, interval, subscription, pending promise, observer, query cache가 흔합니다. route loop 테스트로 mount/unmount를 반복하고 heap snapshot에서 detached DOM과 retained component tree를 비교합니다." }, { q: "closure가 왜 문제인가요?", answer: "closure가 큰 data, DOM node, previous props를 참조한 채 listener나 timer에 남으면 GC가 회수하지 못합니다. handler cleanup과 dependency 관리를 확인하고 allocation timeline에서 interaction 후 retained object가 줄어드는지 봅니다." }, { q: "cache는 언제 비워야 하나요?", answer: "route, user, filter 조합으로 무한히 커지는 image/data/cache는 TTL, max size, LRU, logout cleanup이 필요합니다. cache hit 이득과 memory growth를 같이 보고, WebGL texture나 blob URL은 명시적으로 dispose/revoke합니다." }]),
      item("성능 budget은 어떻게 정하나요?", "target device와 business route별 LCP/INP/CLS, JS size, image size, request count, long task 기준을 잡습니다.", "전체 앱에 하나의 budget만 두면 checkout 같은 핵심 route와 내부 admin route의 우선순위가 섞입니다.", "performance budget policy, CI budget check, route RUM, bundle threshold", [{ q: "budget 초과 시 배포를 막나요?", answer: "핵심 route의 bundle, LCP, INP 같은 guardrail은 차단 대상으로 두고, 낮은 위험 변경은 승인 기록과 후속 작업으로 처리할 수 있습니다. 차단 여부는 RUM impact, release urgency, rollback 가능성을 기준으로 미리 정책화합니다." }, { q: "기준 수치는 어떻게 잡나요?", answer: "Core Web Vitals 권장 기준을 출발점으로 삼되 실제 target device, p75 RUM, 경쟁 제품, 업무 SLA를 반영합니다. 예를 들어 checkout은 LCP 2.5초 이하와 INP 200ms 이하를 강하게 두고 내부 admin은 chart render time을 별도 budget으로 둘 수 있습니다." }, { q: "예외는 어떻게 승인하나요?", answer: "예외는 route, metric, 초과량, 사용자 영향, 만료일, 보완 계획을 남겨 승인합니다. 영구 예외가 되지 않도록 release dashboard와 backlog ticket에 연결하고 다음 PR에서 budget을 다시 확인합니다." }]),
      item("DevTools Performance 패널에서 무엇을 보나요?", "main thread flame chart, long task, layout/paint, network, screenshots, user timing marker를 봅니다.", "녹화만 하고 총 시간만 보면 어떤 interaction이 무엇 때문에 느린지 알 수 없습니다.", "Performance trace, user timing markers, bottom-up analysis, screenshots", [{ q: "Bottom-Up과 Call Tree 차이는?", answer: "Call Tree는 호출 경로 중심으로 비용을 보여주고 Bottom-Up은 전체 녹화에서 비용이 큰 함수나 작업을 합산해 보여줍니다. 특정 handler 경로를 볼 때는 Call Tree, 반복적으로 비싼 utility나 layout 작업을 찾을 때는 Bottom-Up이 유용합니다." }, { q: "user timing은 왜 넣나요?", answer: "route transition, data loaded, hydration ready, filter applied 같은 제품 이벤트를 trace에 표시해 브라우저 작업과 사용자 행동을 연결합니다. marker가 없으면 긴 task가 어느 기능의 결과인지 추적하기 어렵습니다." }, { q: "녹화 환경은?", answer: "대상 device class, CPU throttling, network throttling, cache 상태, 로그인 데이터, browser extension 여부를 고정합니다. lab trace는 재현성이 중요하므로 RUM에서 나쁜 segment와 최대한 같은 조건으로 맞춥니다." }]),
      item("React Profiler와 브라우저 Performance 차이는?", "React Profiler는 React render/commit 원인을, Performance는 전체 browser main thread와 rendering pipeline을 보여줍니다.", "Profiler만 보면 layout, paint, network, third-party script를 놓칠 수 있습니다.", "Profiler export, Performance trace, correlation marker, render commit log", [{ q: "둘을 어떻게 연결하나요?", answer: "interaction 시작과 commit 시점에 user timing marker를 남기고 같은 시나리오를 Profiler와 Performance에서 녹화합니다. Profiler의 긴 commit이 Performance flame chart의 scripting, layout, paint 중 어디로 이어졌는지 맞춰 봅니다." }, { q: "commit이 길면?", answer: "긴 commit은 DOM mutation, layout effect, ref callback, 많은 component update가 한 번에 몰렸다는 신호입니다. component tree를 나누고 memoization, context 분리, virtualization을 적용한 뒤 commit duration과 INP 변화를 비교합니다." }, { q: "render가 빨라도 느린 이유는?", answer: "React render가 짧아도 network wait, image decode, font swap, layout/paint, third-party long task가 main thread를 막을 수 있습니다. 그래서 Profiler 수치만 보지 말고 Performance trace와 Web Vitals attribution을 함께 봅니다." }]),
      item("Core Web Vitals를 CI에서만 보면 안 되는 이유는?", "CI/lab은 재현성과 회귀 탐지에 좋고, RUM은 실제 사용자 환경을 보여줍니다. 둘을 함께 봐야 합니다.", "CI가 빠른 네트워크와 고정 기기로 돌면 실제 저사양 모바일 문제를 놓칩니다.", "Lighthouse CI, RUM p75, device segmentation, field/lab diff", [{ q: "p75 기준은 왜?", answer: "평균은 빠른 기기와 느린 기기가 섞여 문제를 가립니다. p75는 상당수 사용자가 경험하는 하위 품질을 대표해 Core Web Vitals 판단에 쓰이며, p95/p98은 심각한 tail latency 분석에 함께 봅니다." }, { q: "RUM 표본이 적으면?", answer: "기간을 늘리거나 route/device segment를 합치되, release version과 traffic 변화가 섞이지 않게 봅니다. 표본이 너무 작으면 lab trace와 synthetic monitoring으로 회귀 여부를 보조하고 결론에는 신뢰 구간을 표시합니다." }, { q: "실험실 재현은 어떻게?", answer: "RUM에서 나쁜 segment의 device, network, viewport, route, login state, cache state를 가져와 Lighthouse, WebPageTest, DevTools throttling에 반영합니다. 재현 trace에는 Web Vitals attribution과 waterfall, CPU profile을 같이 붙입니다." }]),
      item("cache header는 어떻게 성능에 영향을 주나요?", "immutable asset은 긴 max-age와 content hash, HTML/API는 freshness와 revalidation 정책을 분리합니다.", "HTML을 길게 cache하면 새 배포가 보이지 않고, hashed asset을 짧게 cache하면 네트워크 비용이 늘어납니다.", "Cache-Control audit, CDN hit ratio, release cache test, ETag validation", [{ q: "no-store와 no-cache 차이는?", answer: "no-store는 저장 자체를 막고, no-cache는 저장은 가능하지만 사용 전 재검증을 요구합니다. 개인정보나 결제 응답은 no-store가 맞고, HTML처럼 최신성은 필요하지만 revalidation으로 충분한 resource는 no-cache나 짧은 max-age를 쓸 수 있습니다." }, { q: "stale-while-revalidate는?", answer: "캐시된 응답을 즉시 보여주면서 백그라운드에서 새 응답을 받아 다음 요청에 반영하는 전략입니다. API와 HTML에 적용할 때는 사용자가 stale data를 봐도 되는 시간과 갱신 표시 방식을 정해야 합니다." }, { q: "CDN purge는 언제?", answer: "잘못된 HTML, critical CSS, config, 이미지 변환 결과처럼 content hash로 회피할 수 없는 asset을 즉시 교체해야 할 때 씁니다. 일반 JS/CSS는 content hash와 긴 immutable cache를 쓰고 purge 의존도를 낮추는 편이 안정적입니다." }]),
      item("preload, prefetch, preconnect는 어떻게 쓰나요?", "critical resource는 preload, 다음 탐색 후보는 prefetch, 외부 origin 연결 비용은 preconnect로 줄입니다.", "과하게 쓰면 bandwidth 경쟁과 우선순위 역전으로 오히려 LCP가 느려집니다.", "resource hint audit, waterfall priority, LCP before/after, bandwidth trace", [{ q: "preload 누락 경고는?", answer: "preload한 resource가 곧 사용되지 않으면 브라우저가 경고를 냅니다. as 속성, crossorigin, media 조건, 실제 사용 시점이 맞는지 확인하고, LCP나 critical font가 아니면 preload 대신 normal discovery를 두는 편이 낫습니다." }, { q: "prefetch는 모바일에서?", answer: "모바일에서는 데이터 비용, 배터리, Save-Data, 느린 네트워크를 고려해야 합니다. 다음 route 가능성이 높고 resource가 작을 때만 idle time에 prefetch하고, RUM에서 cache hit 증가와 LCP/INP 부작용을 확인합니다." }, { q: "preconnect가 너무 많으면?", answer: "각 origin마다 DNS, TCP, TLS 준비 비용과 socket 자원을 쓰므로 중요한 외부 origin 몇 개로 제한해야 합니다. analytics, font, API 중 초기 화면에 필요한 origin만 남기고 waterfall에서 connection setup이 실제로 줄었는지 봅니다." }]),
      item("성능 개선 결과는 어떻게 보고하나요?", "변경 전후 조건, p75/p95, route, device, sample size, 부작용, rollback 조건을 함께 씁니다.", "단일 Lighthouse 점수만 보고하면 실제 사용자 개선인지 판단하기 어렵습니다.", "performance regression packet, RUM comparison, trace attachment, release note", [{ q: "수치가 흔들리면?", answer: "동일 조건의 반복 lab run과 RUM 기간 비교를 나눠 보고, release traffic, cache warmup, bot/internal traffic, seasonality를 표시합니다. 개선 폭이 noise보다 작은 경우에는 결론을 보류하거나 더 큰 표본으로 다시 판단합니다." }, { q: "표본은 얼마나?", answer: "route와 device segment별 p75를 볼 수 있을 만큼 필요합니다. 절대 숫자는 트래픽에 따라 다르지만, 작은 표본에서는 p75 변화보다 trace diff와 synthetic run을 보조 증거로 쓰고 sample size를 보고서에 명시합니다." }, { q: "부작용은 무엇을 보나요?", answer: "LCP가 좋아졌어도 INP, CLS, error rate, conversion, a11y keyboard flow, analytics event 누락이 나빠질 수 있습니다. 성능 PR에는 개선 metric과 함께 기능 smoke, visual diff, rollback 조건을 붙입니다." }]),
      item("성능과 접근성이 충돌할 때 어떻게 하나요?", "접근성 필수 의미 구조와 keyboard 흐름은 유지하고, 비용이 큰 부분은 점진 렌더링이나 fallback으로 조정합니다.", "성능을 이유로 semantic DOM이나 focus 처리를 제거하면 품질 기준을 낮추는 것입니다.", "a11y/performance decision note, DOM count, keyboard test, RUM metric", [{ q: "가상화와 screen reader는?", answer: "가상화는 DOM에 일부 row만 남기기 때문에 screen reader가 전체 목록을 탐색하기 어려울 수 있습니다. 핵심 목록은 pagination이나 accessible summary를 제공하고, 가상화가 필요하면 aria count, focus 보존, keyboard navigation을 별도 검증합니다." }, { q: "aria를 줄이면 빨라지나요?", answer: "ARIA attribute 자체가 성능 병목인 경우는 드뭅니다. 느린 원인은 보통 큰 DOM, 잦은 rerender, layout 계산이므로 의미 정보를 제거하기보다 render 범위와 update 빈도를 줄이는 방식으로 해결합니다." }, { q: "성능 budget 예외는?", answer: "접근성 요구를 충족하기 위해 추가 DOM이나 text가 필요하다면 예외를 줄 수 있습니다. 대신 route별 Web Vitals 영향, 대체 최적화, keyboard/screen reader 증거를 남겨 품질 기준이 임의로 흔들리지 않게 합니다." }]),
      item("대시보드 성능은 어떤 지표가 중요한가요?", "initial load, filter interaction latency, chart render time, data refresh cost, memory growth를 봅니다.", "첫 로드만 빠르고 필터 변경마다 전체 chart를 다시 그리면 업무 도구로는 느립니다.", "interaction timing, chart render benchmark, data cache trace, memory profile", [{ q: "차트가 많으면?", answer: "초기 viewport chart만 먼저 렌더하고 나머지는 lazy render나 virtualization, canvas/WebGL batch rendering을 검토합니다. chart library bundle size, data transform cost, tooltip interaction INP, memory growth를 함께 측정합니다." }, { q: "필터 변경 최적화는?", answer: "filter input에는 immediate feedback을 주고 비싼 aggregation은 debounce, memoized selector, worker, server aggregation으로 분리합니다. 이전 결과 cache와 optimistic loading state를 쓰되 stale data 표시와 cancelation을 명확히 합니다." }, { q: "자동 refresh는?", answer: "polling 간격, tab visibility, user activity, network 상태에 맞춰 조절해야 합니다. refresh가 chart rerender와 API waterfall을 계속 만들면 INP와 memory가 나빠지므로 incremental update와 backoff, pause control을 둡니다." }]),
      item("성능 회귀를 어떻게 막나요?", "bundle budget, Web Vitals alert, visual/performance smoke, profiler evidence requirement, dependency review를 둡니다.", "한 번 최적화하고 끝내면 새 dependency나 UI 변경으로 금방 회귀합니다.", "CI budget, RUM alert, dependency diff, PR checklist", [{ q: "경고 기준은?", answer: "route별 p75 LCP/INP/CLS, JS chunk size, long task count, image weight 같은 기준을 둡니다. 작은 변동은 noise로 처리하고, core journey나 특정 browser segment에서 연속 악화가 보이면 alert를 올립니다." }, { q: "false positive는?", answer: "CI lab fluctuation, CDN warmup, test data 변화, browser update로 발생할 수 있습니다. 반복 run, baseline 갱신 절차, RUM corroboration을 두고 false positive도 기록해 threshold를 조정합니다." }, { q: "리뷰어가 뭘 봐야 하나요?", answer: "새 dependency, initial chunk 증가, render 범위 확대, image/font priority 변경, cache header 변경, third-party script 추가를 봐야 합니다. PR에는 bundle diff, Profiler trace, Web Vitals 예상 영향, rollback 경로가 있어야 리뷰가 가능합니다." }]),
      item("성능 문제를 제품 우선순위로 설득하려면?", "사용자 영향, conversion, task completion, support ticket, infra cost와 연결해 말합니다.", "개발자 체감 느림만 말하면 다른 기능 우선순위에 밀릴 수 있습니다.", "business metric correlation, funnel drop, RUM segment, user session replay", [{ q: "수익 영향이 없으면?", answer: "task completion, support ticket, retention, search crawl, internal labor time, infra cost 같은 대체 지표로 연결합니다. 예를 들어 dashboard filter INP가 높으면 업무 처리 시간이 늘고 오류 재시도가 증가한다는 식으로 설명합니다." }, { q: "내부 도구 성능은?", answer: "사용자 수가 적어도 반복 업무 시간이 길면 비용이 큽니다. 특정 화면의 interaction latency, chart render time, memory crash, employee time loss를 수치화해 기능 개발과 같은 우선순위 언어로 바꿉니다." }, { q: "기술부채로 어떻게 표현하나요?", answer: "느린 dependency, 거대한 shared chunk, 캐시 불일치, profiler 없는 복잡한 화면이 앞으로 기능 추가 비용과 장애 위험을 키운다고 설명합니다. 개선 범위를 bundle split, render isolation, cache policy처럼 작은 투자 단위로 나눠 제안합니다." }]),
      item("성능 답변에서 senior-level 증거는 무엇인가요?", "원인 분해 trace, 사용자 지표, 변경 전후 비교, 재발 방지 budget, rollback 기준입니다.", "빠르게 만들었다는 말만 있고 수치와 trace가 없으면 검증 가능한 답변이 아닙니다.", "PERFORMANCE REGRESSION PACKET, trace, RUM chart, budget policy", [{ q: "수치가 없으면 어떻게 답하나요?", answer: "수치가 없었다고 말하고 다음에는 어떤 지표를 잡을지 구체화합니다. 예를 들어 LCP attribution, INP interaction marker, bundle analyzer, Profiler export, RUM p75 dashboard를 만들고 전후 비교 조건을 정하겠다고 답합니다." }, { q: "추정과 사실을 어떻게 나누나요?", answer: "사실은 trace, RUM, bundle diff처럼 확인된 데이터로 말하고, 추정은 가설로 표시한 뒤 검증 방법을 붙입니다. 예를 들어 TTFB가 높다는 사실과 edge cache miss가 원인일 가능성을 분리합니다." }, { q: "외부 검증에서 보여줄 증거는?", answer: "before/after Performance trace, Web Vitals p75 chart, route별 bundle diff, React Profiler screenshot, network waterfall, PR checklist를 보여줍니다. 같은 조건에서 재현한 lab 결과와 배포 후 RUM 변화를 함께 제시하면 신뢰도가 높습니다." }]),
      item("성능 경험이 적을 때 답변은 어떻게 구성하나요?", "Web Vitals 기준, DevTools 진단 순서, React Profiler 사용, RUM/lab 차이, 개선 검증 계획을 말합니다.", "도구 이름만 나열하면 병목을 분해할 수 있는지 드러나지 않습니다.", "diagnostic checklist, lab reproduction, RUM plan, before/after template", [{ q: "Lighthouse만 써봤다면?", answer: "Lighthouse는 lab baseline으로 쓰되 실제 답변에서는 LCP/INP/CLS attribution, network waterfall, Coverage, Performance trace를 어떻게 확인할지 말합니다. 배포 후에는 RUM p75와 device segment로 검증하겠다고 보완합니다." }, { q: "React가 아니면?", answer: "핵심은 framework가 아니라 main thread, DOM update, network, rendering pipeline입니다. Vue, Svelte, vanilla에서도 browser Performance trace, bundle analyzer, component profiler에 해당하는 도구, RUM Web Vitals로 같은 방식으로 좁힙니다." }, { q: "백엔드 병목이면?", answer: "TTFB, Server-Timing, API waterfall, cache hit ratio로 백엔드 병목임을 보여주고 프론트에서 할 수 있는 fallback도 구분합니다. skeleton, streaming, prefetch, edge cache 조정은 프론트와 플랫폼이 함께 볼 수 있습니다." }]),
    ],
  },
  {
    id: "engineering-frontend-seo-analytics-qa",
    title: "SEO·AEO·GEO·애널리틱스 Q&A",
    source: "SEO·AEO·GEO·애널리틱스",
    subtitle: "검색 발견성, AI 답변 가능성, 구조화 데이터, 이벤트 측정, attribution을 답변으로 훈련합니다.",
    questions: [
      item("기술 SEO의 핵심은 무엇인가요?", "검색 엔진이 URL을 발견, 크롤링, 렌더링, 색인, 이해할 수 있게 만드는 것입니다. sitemap, robots, canonical, status code, structured data, 성능이 함께 작동해야 합니다.", "메타 태그만 수정하면 duplicate URL, blocked resource, JS rendering 실패, canonical 오류를 놓칩니다.", "technical SEO release packet, Search Console, crawl test, canonical audit", [{ q: "SEO와 성능은 어떻게 연결되나요?", answer: "LCP, INP, CLS가 나쁘면 사용자가 이탈하고 Search Console의 Core Web Vitals 품질도 낮아집니다. SSR HTML, image priority, JS bundle, render blocking CSS를 줄이면 crawler rendering과 사용자 경험이 함께 좋아집니다." }, { q: "CSR 페이지도 색인되나요?", answer: "가능하지만 crawler가 JS를 렌더링해야 하므로 발견과 색인이 늦거나 실패할 수 있습니다. 중요한 title, canonical, 본문, internal links, structured data는 SSR이나 pre-rendered HTML에서 확인되게 두는 편이 안전합니다." }, { q: "canonical은 언제 위험한가요?", answer: "서로 다른 콘텐츠가 같은 canonical을 가리키거나, canonical URL이 noindex/blocked/redirect chain에 걸리면 ranking signal이 잘못 합쳐질 수 있습니다. 배포 전 rendered HTML과 Search Console 선택 canonical을 함께 확인해야 합니다." }]),
      item("AEO/GEO는 SEO와 무엇이 다른가요?", "SEO가 검색 결과 노출을 목표로 한다면 AEO/GEO는 답변 엔진과 생성형 검색이 인용·요약하기 쉬운 구조와 근거를 제공합니다.", "키워드만 반복하면 AI 답변에서 신뢰 가능한 근거로 선택되기 어렵습니다.", "answer-first block, citation structure, entity schema, AI answer quality review", [{ q: "FAQ schema만 넣으면 되나요?", answer: "아닙니다. FAQ schema는 보조 신호일 뿐이고 실제 화면의 질문, 짧은 답, 근거, 최신성, 작성 주체가 일치해야 합니다. 보이지 않는 FAQ를 JSON-LD에만 넣으면 rich result와 답변 인용 모두에 불리합니다." }, { q: "LLM이 좋아하는 문서 구조는?", answer: "질문형 heading 아래에 직접 답을 먼저 쓰고, 조건, 예외, 근거 링크, 표를 이어 붙이는 구조가 유리합니다. entity 이름을 일관되게 쓰고 제품명, 조직, 기능 관계를 schema와 internal links로 보강합니다." }, { q: "근거 출처는 어떻게 표시하나요?", answer: "주장 옆에 공식 문서, 데이터 출처, 업데이트 날짜를 가까이 둡니다. AI 답변이 인용할 수 있도록 원문 URL, 저자/조직, 통계 기준 기간을 명확히 쓰고 오래된 수치는 갱신 기록을 남깁니다." }]),
      item("검색 의도는 어떻게 문서에 반영하나요?", "informational, navigational, transactional, comparison 의도를 분리하고, 첫 화면과 heading에 답변 방향을 명확히 둡니다.", "검색어만 보고 콘텐츠를 만들면 사용자가 실제로 해결하려는 질문과 CTA가 어긋납니다.", "query intent map, SERP review, content outline, CTR/engagement metric", [{ q: "같은 키워드에 의도가 섞이면?", answer: "SERP의 상위 결과와 Search Console query를 나눠 informational, comparison, transactional 블록을 분리합니다. 한 페이지에서 모두 다루면 heading과 CTA를 명확히 나누고, intent가 강하게 다르면 별도 landing URL과 canonical을 둡니다." }, { q: "롱테일은?", answer: "롱테일은 질문형 heading, FAQ, 비교 표, 사용 사례로 받습니다. 검색량이 작아도 전환 의도가 강할 수 있으므로 GA4 landing conversion과 Search Console impression/CTR을 같이 봅니다." }, { q: "의도 변화는 어떻게 감지하나요?", answer: "Search Console query, CTR, average position, SERP feature 변화, 내부 검색어, funnel drop을 release annotation과 함께 봅니다. 특정 query의 CTR이 떨어지면 title/description 문제가 아니라 SERP 의도 자체가 바뀌었는지 확인합니다." }]),
      item("canonical은 왜 중요한가요?", "같은 콘텐츠가 여러 URL로 접근될 때 대표 URL을 알려 중복 색인과 ranking signal 분산을 줄입니다.", "필터/정렬/추적 파라미터가 모두 색인되면 검색 품질과 crawl budget이 낭비됩니다.", "canonical tag audit, URL parameter policy, Search Console duplicate report, crawl sample", [{ q: "canonical과 redirect 차이는?", answer: "redirect는 사용자를 대표 URL로 실제 이동시키고, canonical은 접근 가능한 중복 URL에서 대표 색인 URL을 힌트로 알려줍니다. 영구 이동이나 통합은 301이 맞고, 정렬/UTM처럼 열어 둘 URL은 canonical로 대표를 지정합니다." }, { q: "페이지네이션 canonical은?", answer: "각 페이지에 고유 콘텐츠가 있으면 page=2가 자기 자신을 canonical로 가져야 합니다. 모두 1페이지로 canonical 처리하면 뒤쪽 상품이나 글이 색인과 internal link 신호에서 사라질 수 있습니다." }, { q: "다국어 canonical은?", answer: "각 locale URL은 자기 자신을 canonical로 두고 hreflang으로 대체 언어 관계를 연결합니다. 한국어 페이지가 영어 URL을 canonical로 가리키면 한국어 콘텐츠가 중복으로 처리되어 노출이 약해질 수 있습니다." }]),
      item("robots.txt와 noindex 차이는 무엇인가요?", "robots.txt는 크롤링 접근을 제어하고, noindex는 색인 제외 신호입니다. 크롤링이 막히면 noindex를 보지 못할 수 있습니다.", "민감 페이지를 robots.txt만으로 숨기면 URL 존재가 노출될 수 있고 보안 수단도 아닙니다.", "robots test, meta robots audit, Search Console coverage, security review", [{ q: "robots로 보안이 되나요?", answer: "안 됩니다. robots.txt는 협조적인 crawler에 대한 요청일 뿐 URL 노출을 막지 못합니다. 개인정보, admin, 결제 페이지는 인증/인가와 no-store cache가 필요하고 검색 제외는 noindex나 접근 차단 정책으로 따로 관리합니다." }, { q: "nofollow는?", answer: "nofollow는 링크 대상에 ranking signal을 전달하지 말라는 힌트입니다. 스팸성 사용자 생성 링크나 유료 링크에는 rel 속성을 쓰고, 내부 핵심 페이지 발견을 막는 용도로 남용하면 crawler discovery가 약해질 수 있습니다." }, { q: "noarchive는 언제?", answer: "검색 엔진의 저장된 사본 노출을 원하지 않을 때 씁니다. 가격, 재고, 법적 문구처럼 최신성이 민감한 페이지에서 검토하지만 색인 제외가 아니라 cache 표시 제한이라는 점을 구분해야 합니다." }]),
      item("structured data는 어떻게 검증하나요?", "schema.org 타입, required/recommended fields, 실제 화면 콘텐츠와의 일치, validation error를 확인합니다.", "보이지 않는 정보를 구조화 데이터에만 넣으면 검색 정책 위반과 rich result 누락이 생길 수 있습니다.", "Rich Results Test, schema validator, content parity check, release checklist", [{ q: "JSON-LD가 좋은 이유는?", answer: "DOM 구조와 분리해 schema를 명확히 유지할 수 있고 SSR HTML에 넣기 쉽습니다. 다만 rendered HTML에서 실제 콘텐츠와 같은 값인지, product price나 availability가 hydration 후 바뀌지 않는지 검증해야 합니다." }, { q: "FAQ schema 남용은?", answer: "화면에 없는 질문이나 홍보성 답변을 넣으면 rich result 정책 위반이 될 수 있습니다. FAQ는 실제 사용자가 묻는 질문과 페이지 주제에 가까운 답만 두고, 반복 boilerplate는 줄이는 것이 좋습니다." }, { q: "오류가 있으면 색인이 막히나요?", answer: "대부분 structured data 오류만으로 색인이 막히지는 않습니다. 하지만 rich result 자격을 잃거나 entity 이해가 약해질 수 있으므로 Rich Results Test와 Search Console enhancement report에서 오류와 경고를 구분해 처리합니다." }]),
      item("sitemap은 무엇을 담아야 하나요?", "색인시키려는 canonical URL과 lastmod 등 discovery에 필요한 정보를 담고, blocked/noindex/중복 URL은 빼야 합니다.", "모든 URL을 넣으면 crawler가 중요하지 않은 페이지에 예산을 씁니다.", "sitemap diff, canonical match test, Search Console sitemap report, URL inventory", [{ q: "lastmod는 정확해야 하나요?", answer: "정확해야 합니다. 모든 URL의 lastmod를 매일 갱신하면 crawler가 신호를 신뢰하지 않을 수 있습니다. 본문, metadata, canonical, structured data처럼 색인 가치가 있는 변경에 맞춰 업데이트합니다." }, { q: "동적 사이트맵은?", answer: "대규모 서비스는 DB나 CMS 기준으로 canonical, indexable, status 200 URL만 동적으로 생성합니다. sitemap index로 분할하고 생성 시 robots/noindex/redirect URL이 섞이지 않도록 테스트합니다." }, { q: "삭제 URL은?", answer: "삭제된 URL은 sitemap에서 제거하고 404나 영구 삭제라면 410을 반환합니다. 대체 페이지가 있으면 관련성 높은 URL로 301 처리하고 internal link도 함께 정리해야 crawl error가 줄어듭니다." }]),
      item("SSR이 SEO를 항상 해결하나요?", "SSR은 초기 HTML 제공에 유리하지만 canonical, metadata, structured data, status code, content quality, performance가 함께 필요합니다.", "SSR만 도입하고 hydration 오류나 빈 콘텐츠를 내보내면 검색 품질이 좋아지지 않습니다.", "rendered HTML snapshot, metadata audit, hydration log, crawl test", [{ q: "CSR도 검색될 수 있나요?", answer: "검색될 수 있지만 JS rendering queue와 client error에 의존합니다. 핵심 landing, 상품, 문서 페이지는 SSR/pre-render로 본문과 internal links를 제공하고 CSR 전용 상태는 색인 대상에서 제외하는 편이 안정적입니다." }, { q: "pre-render는?", answer: "변경 빈도가 낮은 페이지를 build time이나 edge에서 HTML로 만들어 crawler와 사용자에게 빠르게 제공하는 방식입니다. 가격, 재고, 개인화처럼 자주 바뀌는 데이터는 ISR, cache revalidation, canonical consistency를 함께 설계해야 합니다." }, { q: "status code는 왜 중요하나요?", answer: "SSR 페이지가 오류 화면을 200으로 내보내면 soft 404나 잘못된 색인이 생깁니다. 삭제는 404/410, 영구 이동은 301, 권한 필요 페이지는 검색 색인 대상에서 제외되도록 HTTP status와 meta robots를 맞춰야 합니다." }]),
      item("metadata는 어떻게 설계하나요?", "title, description, Open Graph, Twitter card, canonical, hreflang을 페이지 목적과 검색 의도에 맞게 만듭니다.", "모든 페이지가 같은 title/description이면 검색 결과에서 구분되지 않고 CTR이 떨어집니다.", "metadata snapshot, duplicate title report, SERP preview, social card test", [{ q: "description은 ranking 요소인가요?", answer: "직접 ranking 요소로 보기보다는 검색 결과 snippet과 CTR에 영향을 주는 요소로 봅니다. query 의도에 맞는 요약과 차별점을 쓰고, 중복 description은 Search Console과 crawl report로 찾아 고칩니다." }, { q: "OG와 SEO title은?", answer: "SEO title은 검색 의도와 query 매칭에 맞추고, OG title은 공유 맥락에서 클릭을 설명하게 조정할 수 있습니다. 서로 완전히 다르면 브랜드와 canonical URL 인식이 흐려질 수 있어 핵심 entity와 페이지 목적은 맞춥니다." }, { q: "동적 metadata는?", answer: "route param이나 CMS 데이터로 생성하되 SSR HTML에 title, canonical, hreflang, OG가 완성되어 있어야 합니다. fallback title이 색인되지 않도록 loading/error 상태의 metadata와 404 status를 별도로 테스트합니다." }]),
      item("hreflang은 언제 필요하고 무엇이 어렵나요?", "다국어/다지역 동일 콘텐츠에서 언어와 지역 대체 URL을 알려줄 때 필요합니다.", "상호 참조, canonical, locale URL이 어긋나면 검색 엔진이 잘못된 언어 페이지를 보여줄 수 있습니다.", "hreflang matrix, reciprocal link test, locale URL audit, Search Console international report", [{ q: "x-default는?", answer: "언어를 특정하기 어려운 글로벌 선택 페이지나 기본 landing을 지정할 때 씁니다. x-default도 hreflang set에 포함하고 canonical이 자기 자신을 가리키는지 확인해야 합니다." }, { q: "자동 번역 페이지는?", answer: "품질 낮은 자동 번역은 색인 품질과 브랜드 신뢰를 떨어뜨릴 수 있습니다. locale별로 사용자에게 보이는 번역 품질, currency/region 정보, local schema를 검수한 뒤 hreflang에 포함합니다." }, { q: "canonical과 충돌하면?", answer: "hreflang URL이 다른 언어 URL을 canonical로 가리키면 검색 엔진이 대체 언어 관계를 무시할 수 있습니다. 각 언어 페이지는 self-canonical을 두고 모든 locale이 reciprocal hreflang으로 서로를 참조해야 합니다." }]),
      item("애널리틱스 이벤트는 어떻게 정의하나요?", "DOM 클릭이 아니라 사용자 의도, action, target, result, error, context를 담는 product event로 정의합니다.", "button_text만 보내면 퍼널, 실패, 재시도, 권한 차단을 분석할 수 없습니다.", "event spec template, tracking plan, QA event log, privacy review", [{ q: "page_view와 action event 차이는?", answer: "page_view는 사용자가 어떤 화면을 봤는지 기록하고, action event는 그 화면에서 어떤 의도와 결과가 있었는지 기록합니다. SPA에서는 route change page_view와 CTA click, form submit, error result를 분리해야 funnel이 해석됩니다." }, { q: "event naming은?", answer: "동사와 대상이 드러나는 일관된 이름을 씁니다. 예를 들어 signup_submit, plan_compare_open처럼 action과 object를 고정하고, button_text나 locale처럼 바뀌는 값은 parameter로 둡니다." }, { q: "result 필드는 왜?", answer: "성공, 실패, 차단, 취소를 구분해야 같은 action의 전환율과 오류율을 계산할 수 있습니다. result와 error_code가 없으면 funnel drop이 UX 문제인지 API 실패인지 privacy consent 차단인지 알기 어렵습니다." }]),
      item("GA4 같은 도구를 붙일 때 주의할 점은?", "consent, PII 금지, 중복 이벤트, SPA route tracking, UTM 보존, debug view 검증을 봅니다.", "태그만 설치하면 route 변경 누락, consent 이전 전송, 중복 page_view가 생길 수 있습니다.", "GA4 debug view, consent mode test, route tracking fixture, event dedupe log", [{ q: "SPA page_view는?", answer: "history push/replace나 router afterEach에서 page_location, page_path, page_title을 갱신해 명시 전송합니다. 초기 page_view와 client route page_view가 중복되지 않도록 debug view와 network log로 한 route당 한 번만 찍히는지 봅니다." }, { q: "PII 예시는?", answer: "email, phone, 이름, 주소, 주민번호, 자유 입력 메시지, 검색어에 포함된 개인정보가 대표적입니다. GA4 event parameter, UTM, page URL query에 PII가 섞이지 않도록 redaction과 allowlist 방식 schema를 둡니다." }, { q: "중복 이벤트는 어떻게 찾나요?", answer: "DebugView, Tag Assistant, network request, QA event log에서 event_id, route, timestamp를 비교합니다. React strict mode, 중복 tag manager 설치, hydration 중 effect 재실행, route listener 중복 등록이 흔한 원인입니다." }]),
      item("UTM은 어떻게 관리하나요?", "source, medium, campaign, content, term의 naming convention과 대소문자, redirect 보존 정책을 정합니다.", "임의 UTM이 쌓이면 attribution report가 분산되어 캠페인 성과를 해석할 수 없습니다.", "UTM naming policy, redirect test, campaign report, normalization rule", [{ q: "대소문자는?", answer: "GA4와 리포트에서 값이 분리될 수 있으므로 소문자 기준을 정하고 수집 단계나 리포트 단계에서 normalize합니다. utm_source=Newsletter와 newsletter가 다른 캠페인으로 잡히지 않게 naming policy를 운영합니다." }, { q: "내부 링크에 UTM을?", answer: "권장하지 않습니다. 내부 링크 UTM은 original attribution을 덮어 acquisition 분석을 망칠 수 있습니다. 내부 배너나 추천 영역 성과는 별도 internal_promo event나 click parameter로 추적합니다." }, { q: "short link redirect는?", answer: "301/302 redirect 과정에서 query string이 유지되는지 테스트해야 합니다. short link, ad platform, CDN redirect가 UTM을 누락하면 landing session attribution이 direct나 referral로 잘못 잡힙니다." }]),
      item("conversion funnel은 어떻게 설계하나요?", "노출, 진입, 핵심 행동, 실패, 완료를 단계별 event로 나누고 denominator를 명확히 합니다.", "완료 이벤트만 보면 어디서 이탈했는지, 오류 때문인지 의도 변경 때문인지 알 수 없습니다.", "funnel spec, event sequence test, drop-off report, error correlation", [{ q: "분모는 어떻게 정하나요?", answer: "funnel의 질문에 맞춰 eligible user, landing session, CTA exposure, form start 중 하나를 명시합니다. 예를 들어 결제 전환율은 checkout_start 기준과 product_view 기준이 다르므로 리포트 이름에 denominator를 포함합니다." }, { q: "부분 완료는?", answer: "step_completed, save_draft, validation_error처럼 중간 상태를 별도 event로 둡니다. 이렇게 해야 drop-off가 의도적 중단인지 field error, API error, payment failure 때문인지 구분할 수 있습니다." }, { q: "A/B 실험과 연결은?", answer: "각 funnel event에 experiment_id, variant, assignment_id나 exposure id를 붙입니다. 전환 이벤트만 variant를 붙이면 노출되지 않은 사용자가 섞일 수 있으므로 exposure 이후의 세션과 사용자를 기준으로 분석합니다." }]),
      item("privacy와 analytics는 어떻게 균형 잡나요?", "목적 제한, 최소 수집, 익명화/가명화, consent, retention, redaction을 기본으로 둡니다.", "분석 편의를 위해 user input이나 email을 보내면 법적·신뢰 리스크가 큽니다.", "privacy review, PII scanner, consent log, data retention policy", [{ q: "IP는 개인정보인가요?", answer: "지역과 법제에 따라 개인정보 또는 개인정보에 준하는 식별자로 취급될 수 있습니다. client analytics에서는 IP를 직접 parameter로 보내지 않고, 도구의 IP anonymization, regional processing, retention 정책을 확인합니다." }, { q: "userId는 보내도 되나요?", answer: "내부 userId도 식별자이므로 목적, consent, access control, retention을 정해야 합니다. 외부 분석 도구에는 raw DB id보다 scoped pseudonymous id를 쓰고 email이나 phone으로 join하지 않습니다." }, { q: "삭제 요청은?", answer: "사용자 삭제 요청이 오면 analytics identity, event store, warehouse, CRM 연동까지 영향을 확인해야 합니다. user deletion API, retention window, backup 처리 기준을 문서화하고 이벤트에서 재식별 가능한 parameter를 줄입니다." }]),
      item("Search Console에서 무엇을 보나요?", "index coverage, crawl errors, Core Web Vitals, query/CTR, canonical 선택, sitemap 상태를 봅니다.", "순위만 보면 색인 문제, technical error, CTR 문제를 분리하지 못합니다.", "Search Console export, coverage report, query report, URL inspection", [{ q: "impression이 줄면?", answer: "색인 coverage, sitemap 제출 상태, robots/noindex, canonical 선택, average position, query demand 변화를 나눠 봅니다. release annotation과 함께 보면 metadata 변경, redirect, SSR 오류, 계절성 중 무엇이 원인인지 좁힐 수 있습니다." }, { q: "CTR이 낮으면?", answer: "query와 landing page가 맞는지, title/description이 SERP 의도와 다른지, rich result나 브랜드 신뢰 신호가 약한지 봅니다. position이 유지되는데 CTR만 떨어지면 snippet, SERP feature 변화, 경쟁 결과를 우선 확인합니다." }, { q: "URL inspection은 언제?", answer: "신규 URL, canonical 의심, 색인 누락, robots/noindex 변경, SSR rendering 문제를 확인할 때 씁니다. live test로 rendered HTML, HTTP status, blocked resource를 확인하고 indexed page와 live page 차이를 비교합니다." }]),
      item("SEO 성과는 어떤 지표로 봐야 하나요?", "impression, CTR, average position, landing conversion, indexed pages, crawl errors, Web Vitals를 함께 봅니다.", "traffic만 보면 브랜드 캠페인, 계절성, 검색 의도 변화와 technical SEO 효과를 구분하기 어렵습니다.", "SEO health window, Search Console, analytics landing report, release annotation", [{ q: "순위가 올라도 전환이 낮으면?", answer: "query intent와 landing CTA가 맞지 않거나 traffic quality가 낮을 수 있습니다. Search Console query, GA4 landing conversion, funnel step error, page speed, internal link 다음 행동을 함께 봐야 합니다." }, { q: "계절성은?", answer: "전년 동기간, campaign calendar, search trend, 브랜드 노출 변화를 baseline으로 둡니다. release 효과를 보려면 비슷한 query group이나 unaffected page를 비교군으로 두고 annotation을 붙입니다." }, { q: "release annotation은 왜?", answer: "metadata, canonical, SSR, sitemap, tracking 변경이 언제 배포됐는지 알아야 impression, CTR, conversion 변화를 해석할 수 있습니다. annotation이 없으면 검색 알고리즘 변화와 제품 변경을 분리하기 어렵습니다." }]),
      item("콘텐츠 구조는 AI 답변에 어떻게 유리하게 만드나요?", "질문형 heading, 짧은 결론, 근거 bullet, 표, 정의-조건-예외 구조, 최신성 표시를 둡니다.", "긴 마케팅 문단만 있으면 답변 엔진이 구체적 근거를 추출하기 어렵습니다.", "answer block audit, entity coverage, citation snippet review, AI query test", [{ q: "표가 좋은 이유는?", answer: "비교 기준, 조건, 예외를 구조적으로 보여줘 답변 엔진이 항목 관계를 추출하기 쉽습니다. 제품 비교, 가격, 기능 지원 여부는 table과 schema를 함께 맞추면 entity 이해에도 도움이 됩니다." }, { q: "FAQ는 어디에?", answer: "페이지 주제와 가까운 section 하단에 실제 사용자 질문을 배치합니다. 핵심 답은 본문에서도 다루고 FAQ는 query variant와 edge case를 보완하게 두며, FAQ schema는 화면 콘텐츠와 일치시킵니다." }, { q: "날짜 표시는?", answer: "통계, 가격, 정책, 기술 지원 범위처럼 변하는 정보에는 작성일과 업데이트일을 표시합니다. sitemap lastmod와 페이지의 visible updated date가 크게 어긋나지 않게 관리합니다." }]),
      item("entity SEO는 무엇인가요?", "브랜드, 제품, 사람, 장소, 개념의 관계를 명확히 해 검색 엔진이 주제를 이해하게 하는 접근입니다.", "키워드만 반복하면 어떤 대상에 대한 신뢰 정보인지 모호합니다.", "entity map, organization schema, internal link graph, knowledge panel check", [{ q: "schema만 넣으면?", answer: "충분하지 않습니다. Organization, Product, Person schema는 실제 화면 콘텐츠, author, about page, sameAs, internal links와 맞아야 합니다. schema와 본문이 다르면 entity 신뢰가 약해집니다." }, { q: "내부 링크 역할은?", answer: "관련 entity 간 관계를 crawler가 따라가게 만듭니다. 제품 페이지에서 기능 문서, 사례, 가격, FAQ로 연결하고 anchor text에 실제 entity와 관계를 담으면 topic authority가 쌓입니다." }, { q: "브랜드 검색은?", answer: "브랜드 query는 entity 인식과 신뢰를 보여주는 지표입니다. Search Console의 branded query, knowledge panel, sitelinks, organization schema, social profile sameAs를 같이 관리합니다." }]),
      item("internal linking은 왜 중요한가요?", "사용자 탐색과 crawler discovery, topic authority 전달에 영향을 줍니다.", "관련 페이지가 고립되면 좋은 콘텐츠도 발견과 ranking signal을 얻기 어렵습니다.", "internal link audit, orphan page report, anchor text review, crawl depth metric", [{ q: "anchor text는?", answer: "대상 페이지의 주제와 사용자 기대를 설명해야 합니다. '여기'보다 'GA4 이벤트 스키마 예시'처럼 구체적인 anchor가 crawler와 사용자 모두에게 의미를 줍니다." }, { q: "footer 링크만으로 충분?", answer: "대부분 충분하지 않습니다. footer 링크는 전역 navigation 신호는 주지만 본문 맥락의 관련성을 약하게 전달합니다. 핵심 topic cluster는 본문, related content, breadcrumb로 연결해야 합니다." }, { q: "링크가 너무 많으면?", answer: "중요도 신호가 희석되고 사용자가 탐색하기 어려워집니다. crawl depth, click data, orphan page report를 보고 핵심 페이지 중심으로 정리하며 faceted navigation은 robots/canonical 정책과 함께 제한합니다." }]),
      item("404/redirect는 SEO에서 어떻게 다루나요?", "삭제, 이동, 통합 목적에 따라 404/410/301/302를 고르고 internal link와 sitemap을 정리합니다.", "모든 오류를 홈으로 redirect하면 soft 404와 사용자 혼란이 생깁니다.", "redirect map, crawl error report, status code test, sitemap cleanup", [{ q: "410은 언제?", answer: "콘텐츠가 영구 삭제됐고 대체 페이지가 없을 때 씁니다. 410은 제거 의도를 더 명확히 주지만, 내부 링크와 sitemap에서 해당 URL을 제거하지 않으면 crawler error가 계속 남습니다." }, { q: "302와 301 차이는?", answer: "301은 영구 이동, 302는 임시 이동 신호입니다. URL 통합이나 slug 변경은 301로 ranking signal을 넘기고, 캠페인 임시 landing이나 재고 일시 전환은 302를 검토합니다." }, { q: "soft 404는?", answer: "HTTP 200으로 빈 페이지, 오류 메시지, 관련 없는 홈 redirect를 반환해 검색 엔진이 실질적으로 없는 페이지로 판단하는 상태입니다. 없는 콘텐츠는 적절한 404/410을 주고 대체가 있으면 관련성 높은 301을 씁니다." }]),
      item("SPA에서 route analytics는 어떻게 해야 하나요?", "client route change를 page_view로 명시 전송하고 title/path/referrer context를 정확히 갱신합니다.", "초기 로드만 추적하면 대부분의 화면 이동이 분석에서 사라집니다.", "route tracking test, debug view, history listener audit, duplicate guard", [{ q: "hash route는?", answer: "hash 기반 route도 실제 화면 의미가 바뀌면 page_view나 screen_view로 기록해야 합니다. GA4 page_location에 hash를 포함할지 page_path parameter로 정규화할지 정책을 정하고 중복 전송을 막습니다." }, { q: "modal route는 page_view인가요?", answer: "공유 가능한 URL과 독립적인 intent가 있으면 page_view로 볼 수 있습니다. 단순 확인 dialog는 action event가 더 맞고, modal open/close와 conversion을 funnel 단계로 추적합니다." }, { q: "referrer는?", answer: "SPA 내부 이동에서는 browser document.referrer가 갱신되지 않을 수 있습니다. 이전 route를 app context로 저장해 page_view parameter에 넣고, external referrer와 internal previous_path를 구분합니다." }]),
      item("A/B 테스트 이벤트는 어떻게 설계하나요?", "exposure, variant, assignment id, conversion, guardrail metric을 명확히 기록합니다.", "노출 이벤트 없이 전환만 보면 실제로 실험을 본 사용자와 보지 않은 사용자가 섞입니다.", "experiment spec, exposure log, guardrail dashboard, sample ratio check", [{ q: "SRM은?", answer: "Sample Ratio Mismatch로, 기대한 variant 비율과 실제 노출 비율이 어긋난 상태입니다. assignment logic, bot/internal filtering, consent 누락, client tracking 실패를 확인하고 SRM이 있으면 전환 해석을 보류합니다." }, { q: "동시 실험 충돌은?", answer: "같은 화면, 같은 funnel, 같은 metric을 건드리는 실험은 상호작용을 만들 수 있습니다. namespace, mutual exclusion, layer policy를 두고 event에는 active experiment list를 남겨 분석에서 분리합니다." }, { q: "guardrail metric은?", answer: "주요 전환 외에 악화되면 안 되는 지표입니다. 예를 들어 signup 실험이면 error rate, page speed, unsubscribe, refund, privacy consent opt-out 같은 metric을 함께 봅니다." }]),
      item("마케팅 script와 성능의 균형은?", "비즈니스 가치와 성능 비용을 비교하고 consent 이후 지연 로드, sandbox, server-side tagging을 검토합니다.", "모든 태그를 초기 로드에 넣으면 LCP/INP와 개인정보 기준을 동시에 해칠 수 있습니다.", "tag inventory, long task attribution, consent test, business owner map", [{ q: "태그 삭제 기준은?", answer: "소유자, 목적, 최근 사용 리포트, 전환 기여, privacy basis, 성능 비용이 불명확하면 제거 후보입니다. Long task와 network waterfall에서 LCP/INP 영향이 큰 태그는 business value와 비교해 지연 로드나 삭제를 결정합니다." }, { q: "server-side tagging은?", answer: "브라우저에서 직접 여러 vendor로 보내는 요청을 서버 endpoint로 모아 관리하는 방식입니다. client JS와 third-party cookie 의존을 줄일 수 있지만 consent, IP 처리, event schema, dedupe 책임이 서버로 이동합니다." }, { q: "chat widget은?", answer: "초기 LCP 전에 로드하지 말고 consent와 사용자 의도 이후 lazy load하는 편이 좋습니다. widget이 main thread long task, layout shift, tracking cookie를 만드는지 RUM과 tag inventory에서 확인합니다." }]),
      item("SEO 릴리스 체크리스트에는 무엇이 들어가나요?", "metadata, canonical, robots, sitemap, structured data, status code, Web Vitals, analytics, Search Console 확인이 들어갑니다.", "콘텐츠 배포만 하고 technical gate가 없으면 색인 누락과 측정 누락을 늦게 발견합니다.", "TECHNICAL SEO RELEASE PACKET, URL inspection, metadata snapshot, event QA", [{ q: "릴리스 직후 무엇을 보나요?", answer: "대표 URL의 HTTP status, rendered HTML, title/description, canonical, robots, structured data, sitemap 포함 여부, GA4 page_view/event 전송을 확인합니다. Search Console URL inspection과 analytics debug view를 함께 봅니다." }, { q: "색인은 언제 확인?", answer: "즉시 ranking을 기대하기보다 URL inspection의 crawl 가능 여부와 sitemap 수집 상태를 먼저 확인합니다. 며칠 동안 indexed pages, canonical 선택, crawl error, impression 변화를 health window로 추적합니다." }, { q: "롤백 기준은?", answer: "대량 noindex, canonical 오지정, robots 차단, 5xx/soft 404 증가, GA4 핵심 funnel 누락처럼 discovery나 측정이 크게 깨지면 rollback합니다. 콘텐츠 typo만 있는 경우에는 forward fix가 더 빠를 수 있습니다." }]),
      item("analytics 데이터 품질은 어떻게 보장하나요?", "tracking plan, typed event schema, QA 환경 검증, 중복 방지, bot/internal traffic filtering을 둡니다.", "잘못 수집된 데이터는 나중에 보정하기 어렵고 제품 결정을 왜곡합니다.", "event schema, QA log, anomaly alert, data quality dashboard", [{ q: "이벤트 스키마 변경은?", answer: "새 parameter 추가는 backward compatible하게 하고 이름 변경이나 의미 변경은 versioning과 migration window를 둡니다. downstream dashboard, warehouse model, experiment analysis가 깨지지 않도록 tracking plan과 release note를 업데이트합니다." }, { q: "내부 트래픽은?", answer: "직원, QA, staging, preview deployment traffic은 별도 property나 parameter로 분리하고 운영 리포트에서는 제외합니다. IP만으로 부족하면 auth role, environment, build channel을 함께 사용합니다." }, { q: "bot은 어떻게?", answer: "known bot filter, user agent, 비정상 event rate, no-JS pattern, datacenter IP, impossible funnel sequence로 걸러냅니다. SEO crawler traffic과 analytics event traffic은 목적이 다르므로 Search Console crawl stats와 GA4 사용자 지표를 섞지 않습니다." }]),
      item("SEO/AEO 답변에서 senior-level 포인트는?", "검색 엔진의 처리 흐름, 사용자 의도, 기술 구현, 측정, privacy, 릴리스 후 health window를 연결하는 것입니다.", "메타 태그와 키워드만 말하면 제품 성장과 기술 품질을 함께 보는 역량이 부족해 보입니다.", "DISCOVERY AND MEASUREMENT MODEL, event spec, SEO health report, release annotation", [{ q: "개발자가 콘텐츠까지 알아야 하나요?", answer: "전문 copywriter가 아니어도 검색 의도, heading 구조, canonical 대상, schema와 화면 콘텐츠 일치 여부는 이해해야 합니다. 기술 구현이 콘텐츠 의미를 훼손하면 crawl, index, rank 단계 모두에 영향을 줍니다." }, { q: "성과가 늦게 나오는 문제는?", answer: "SEO는 crawl과 reindex 시간이 있어 즉시 전환으로만 판단하기 어렵습니다. 대신 배포 직후에는 indexability와 tracking 품질을 보고, 이후 impression, CTR, position, landing conversion을 기간별로 나눠 봅니다." }, { q: "외부 검증 증거는?", answer: "Search Console coverage/query export, URL inspection 결과, Rich Results Test, rendered HTML snapshot, GA4 debug log, sitemap diff, redirect map을 제시합니다. 실무 답변에서는 추정이 아니라 이 증거로 변경 영향을 설명합니다." }]),
      item("SEO 경험이 적으면 어떻게 답변하나요?", "crawl-index-render-rank 흐름, canonical/metadata/schema 기본, Search Console 검증, 이벤트 측정 계획을 구체적으로 말합니다.", "블로그식 팁만 말하면 실제 릴리스에서 무엇을 확인할지 불분명합니다.", "SEO validation checklist, sample URL audit, Search Console plan, event spec draft", [{ q: "포트폴리오 증거는?", answer: "개인 사이트나 샘플 URL에서 rendered HTML, metadata, canonical, sitemap, robots, structured data, Search Console 설정 화면, GA4 debug event를 캡처해 보여줄 수 있습니다. 숫자가 작아도 검증 흐름을 보여주는 것이 중요합니다." }, { q: "AEO는 어떻게 연습?", answer: "기존 문서를 질문형 heading, 답변 요약, 근거 링크, 표, entity schema로 재구성해 보고 AI 검색 질의에서 인용 가능성을 비교합니다. FAQ schema보다 실제 콘텐츠 구조와 출처 표시를 먼저 연습합니다." }, { q: "수치가 없으면?", answer: "수치가 없다고 말하고 다음 측정 계획을 구체화합니다. Search Console impression/CTR, indexed pages, GA4 landing conversion, event QA log, crawl error baseline을 만들겠다고 답하면 실무 연결이 됩니다." }]),
    ],
  },
  {
    id: "engineering-frontend-quality-qa",
    title: "프론트엔드 품질·릴리스 Q&A",
    source: "프론트엔드 품질·릴리스",
    subtitle: "보안, 테스트, 배포, sourcemap, CDN cache, rollback, 릴리스 증거를 답변으로 훈련합니다.",
    questions: [
      item("프론트엔드 릴리스 품질 기준은 무엇인가요?", "기능 성공뿐 아니라 보안, 접근성, 성능, 브라우저 호환성, observability, rollback 가능성을 통과해야 합니다.", "로컬에서 보이는 화면만 확인하면 CDN cache, env, sourcemap, 권한, 실제 사용자 성능 문제를 놓칩니다.", "release checklist, E2E trace, Web Vitals, error dashboard, rollback drill", [{ q: "작은 변경도 릴리스 게이트가 필요한가요?", answer: "문구 수정처럼 위험이 낮은 변경은 가벼운 smoke와 리뷰로 충분할 수 있지만, 인증·결제·권한·라우팅·캐시·분석 이벤트를 건드리면 작은 diff라도 강한 게이트가 필요합니다. 변경 크기보다 사용자 영향 경로와 복구 비용으로 등급을 나눕니다." }, { q: "게이트를 자동화하려면?", answer: "CI에서 lint, typecheck, unit, component, 핵심 E2E, axe smoke, bundle budget, sourcemap 업로드 검증을 자동으로 돌립니다. 수동 확인이 필요한 항목은 release checklist에 증거 링크를 남기고, 실패 시 배포를 막는 항목과 경고만 주는 항목을 구분합니다." }, { q: "배포 후 몇 시간 보나요?", answer: "트래픽 패턴에 맞춰 최소 한 번의 핵심 사용 시간대를 봅니다. 보통 첫 30분은 error spike와 blank screen, 2~4시간은 Web Vitals와 conversion, 24시간은 브라우저·지역·버전 segment를 확인하고 release version 기준으로 이전 배포와 비교합니다." }]),
      item("프론트엔드 XSS 방어는 source와 sink를 어떻게 끊나요?", "untrusted source가 HTML/JS execution sink로 들어갈 때 발생합니다. escaping, sanitization, Trusted Types, CSP, unsafe sink 금지가 필요합니다.", "React가 기본 escape를 해도 dangerouslySetInnerHTML, markdown, SVG, URL, third-party widget에서 우회 경로가 생깁니다.", "source-sink map, XSS fixture, CSP violation report, sanitizer test", [{ q: "React면 XSS가 없나요?", answer: "없어지는 것이 아닙니다. JSX 텍스트 interpolation은 escape되지만 dangerouslySetInnerHTML, ref로 DOM을 직접 쓰는 코드, URL href, SVG, third-party widget, 번역 문자열의 HTML 삽입은 별도 검증이 필요합니다. source-to-sink 표로 어떤 값이 어느 sink에 닿는지 확인합니다." }, { q: "markdown 렌더링은?", answer: "markdown은 HTML을 허용하는 순간 사용자 입력이 DOM sink로 들어갑니다. 허용 태그와 속성을 whitelist로 제한하고, javascript: URL, event handler, style 속성, SVG payload를 fixture로 테스트해야 합니다. sanitizer 버전과 설정도 보안 리뷰 대상입니다." }, { q: "CSP는 무엇을 막나요?", answer: "CSP는 inline script, 외부 script, frame, image, connect 대상 같은 실행·로드 경계를 제한해 XSS의 폭발 반경을 줄입니다. 하지만 취약한 sink를 고치는 대체재는 아니며, report-only로 violation을 수집한 뒤 nonce 또는 hash 기반 정책으로 단계적으로 강화합니다." }]),
      item("CSRF와 프론트엔드의 관계는?", "cookie 기반 인증에서는 브라우저가 자동으로 cookie를 보내므로 SameSite, CSRF token, origin 검증이 필요합니다.", "token을 JS에서 직접 보내는 구조와 cookie 세션 구조를 혼동하면 방어가 빠집니다.", "SameSite policy, CSRF negative test, request header audit, server validation log", [{ q: "SameSite=Lax면 충분한가요?", answer: "기본 방어로는 유용하지만 충분하다고 단정하면 안 됩니다. 브라우저 차이, top-level navigation, legacy client, OAuth redirect, iframe 요구가 있으면 예외가 생깁니다. 상태 변경 요청에는 서버가 검증하는 CSRF token과 Origin 또는 Referer 검증을 같이 둡니다." }, { q: "CORS와 CSRF 차이는?", answer: "CORS는 다른 origin의 응답을 브라우저 JS가 읽을 수 있는지를 제한합니다. CSRF는 응답을 읽지 못해도 인증 쿠키가 자동 전송되어 상태 변경 요청이 실행되는 문제입니다. CORS를 닫아도 CSRF 토큰 검증이 없으면 POST 부작용은 남을 수 있습니다." }, { q: "SPA도 CSRF가 있나요?", answer: "cookie 세션이나 httpOnly refresh cookie를 쓰는 SPA라면 있습니다. Authorization header에 bearer token을 직접 붙이는 구조는 CSRF보다 XSS 탈취 위험이 커지고, cookie 기반 구조는 SameSite, token, credentials 설정, preflight 정책을 함께 검증해야 합니다." }]),
      item("토큰 저장은 어떻게 판단하나요?", "XSS, CSRF, refresh rotation, session revocation, UX 요구를 기준으로 httpOnly secure cookie, memory, storage를 비교합니다.", "access token을 localStorage에 두면 XSS 시 탈취되기 쉽고, cookie는 CSRF 방어가 필요합니다.", "token storage decision, threat model, logout test, rotation log", [{ q: "httpOnly cookie 단점은?", answer: "JS에서 읽을 수 없어 탈취면에서는 강하지만, 브라우저가 자동 전송하므로 CSRF 방어가 필요합니다. SameSite, Secure, domain/path 범위, CORS credentials, logout revocation, multi-subdomain 요구를 함께 설계해야 합니다." }, { q: "memory 저장은 새로고침 때?", answer: "memory 저장은 XSS로 영구 탈취되는 위험을 줄이지만 새로고침, 탭 복제, 앱 재시작에서 access token이 사라집니다. 짧은 access token과 httpOnly refresh cookie, silent refresh 실패 시 명확한 re-auth UX를 조합하는 방식이 흔합니다." }, { q: "refresh token은 어디에?", answer: "브라우저에서 refresh token을 직접 읽을 수 있는 storage에 두는 것은 위험합니다. 가능하면 httpOnly Secure cookie에 저장하고 rotation, reuse detection, device/session revocation, logout 시 서버 폐기를 적용합니다. 모바일 WebView나 BFF 구조라면 저장 경계가 달라질 수 있습니다." }]),
      item("프론트엔드 secret은 왜 존재하면 안 되나요?", "브라우저 bundle은 사용자에게 전달되므로 API key나 secret은 노출된 값으로 봐야 합니다.", "환경변수 이름이 SECRET이어도 build 시 bundle에 들어가면 누구나 볼 수 있습니다.", "bundle scan, source map audit, secret scanning, network request review", [{ q: "public API key는?", answer: "지도나 analytics처럼 public key가 전제인 서비스도 있습니다. 이 경우 secret으로 보지 말고 origin 제한, quota, scope, abuse monitoring, server-side proxy 필요성을 검토합니다. 결제 secret, admin token, private API credential은 절대 bundle에 넣지 않습니다." }, { q: "env prefix는?", answer: "Vite의 VITE_, Next의 NEXT_PUBLIC_처럼 public prefix가 붙으면 브라우저 번들에 노출됩니다. 이름에 SECRET이 들어가도 public prefix로 주입되면 공개 값입니다. build output과 source map에서 실제 문자열이 포함되는지 스캔해야 합니다." }, { q: "노출된 secret은 어떻게 대응?", answer: "이미 배포된 값은 회수됐다고 봐야 합니다. 즉시 revoke 또는 rotate하고, 사용 로그에서 악용 여부를 확인하며, 해당 값이 들어간 sourcemap과 CDN asset의 purge 범위를 정리합니다. 이후 secret scanning과 PR gate로 재발을 막습니다." }]),
      item("CORS 오류를 어떻게 진단하나요?", "브라우저 보안 정책, origin, preflight, credentials, allowed headers/methods, server response를 확인합니다.", "프론트에서 header를 억지로 추가해 해결하려 하면 실제로는 서버 CORS 정책이 맞지 않는 경우가 많습니다.", "preflight capture, response header audit, credentials test, server config diff", [{ q: "CORS는 보안인가요?", answer: "CORS는 브라우저가 cross-origin 응답을 JS에 노출할지 결정하는 정책입니다. 서버 자체를 보호하는 인증·인가를 대신하지 않습니다. 악성 서버나 curl은 CORS를 따르지 않으므로 API는 별도의 auth, rate limit, input validation을 가져야 합니다." }, { q: "credentials true이면?", answer: "cookie나 client certificate을 포함하려면 fetch credentials와 서버의 Access-Control-Allow-Credentials가 맞아야 합니다. 이때 Access-Control-Allow-Origin은 *를 쓸 수 없고, 허용 origin을 정확히 반사하거나 allowlist로 검증해야 합니다." }, { q: "wildcard origin은 왜 위험?", answer: "인증이 필요 없는 public resource에는 가능할 수 있지만, 사용자별 데이터나 credentials가 얽히면 다른 origin이 응답을 읽는 길이 열릴 수 있습니다. origin allowlist, method/header 최소화, preflight cache 정책을 서버 config diff로 확인합니다." }]),
      item("E2E 테스트는 무엇을 검증해야 하나요?", "핵심 사용자 여정의 실제 브라우저 동작, route, network, auth, accessibility smoke, visual state를 검증합니다.", "모든 케이스를 E2E로 넣으면 느리고 flaky해지며, 반대로 하나도 없으면 통합 회귀를 놓칩니다.", "Playwright trace, critical journey list, flake report, test pyramid", [{ q: "무엇을 E2E로 올리나요?", answer: "로그인, 결제, 저장, 권한 변경, 검색, 대시보드 조회처럼 여러 컴포넌트와 API가 이어지는 핵심 여정을 올립니다. 단일 컴포넌트의 조건 분기는 component test로 두고, E2E는 실제 라우팅·네트워크·브라우저 동작이 깨지는지 확인합니다." }, { q: "mock과 real API 선택은?", answer: "릴리스 게이트에서는 계약이 안정적인 mock으로 빠른 회귀를 잡고, 별도 smoke나 staging에서는 real API로 auth, CORS, schema, latency를 확인합니다. mock은 OpenAPI/GraphQL schema나 contract sample과 동기화해야 drift를 줄일 수 있습니다." }, { q: "flaky는 어떻게 줄이나요?", answer: "고정 sleep을 줄이고 locator, network wait, test id, deterministic fixture를 사용합니다. 테스트별 독립 계정과 데이터 reset을 보장하고, Playwright trace와 retry report로 race, animation, backend latency 원인을 분류해 제거합니다." }]),
      item("컴포넌트 테스트는 어디까지 하나요?", "props/state 조합, 사용자 이벤트, 접근성 role/name, error/loading 상태를 검증합니다.", "구현 세부 DOM 구조만 테스트하면 리팩터링에 취약하고 실제 사용자 행동을 검증하지 못합니다.", "Testing Library queries, user-event test, story coverage, axe check", [{ q: "snapshot test는?", answer: "넓은 DOM snapshot은 작은 markup 변경에도 깨져 신호가 약합니다. 디자인 시스템 토큰이나 serializable output처럼 안정적인 대상에는 제한적으로 쓰고, 대부분은 role, name, visible text, user-event 결과를 검증하는 편이 낫습니다." }, { q: "role query가 좋은 이유는?", answer: "사용자가 보조기술로 인식하는 의미와 테스트가 같은 기준을 쓰게 됩니다. getByRole로 버튼 이름, dialog 제목, form field label을 찾으면 접근성 이름 누락과 잘못된 semantic element를 빨리 발견할 수 있습니다." }, { q: "CSS는 어떻게 검증?", answer: "순수 스타일 값은 unit test보다 visual regression과 story viewport가 맞습니다. 상태별 class나 data attribute는 component test로 확인하고, overflow, focus ring, responsive break는 screenshot diff와 브라우저 matrix에서 봅니다." }]),
      item("시각 회귀 테스트는 언제 필요한가요?", "디자인 시스템, 핵심 화면, 차트/그래픽, responsive layout처럼 시각 깨짐 비용이 큰 곳에 필요합니다.", "단위 테스트가 통과해도 spacing, overflow, z-index, 반응형 깨짐은 놓칠 수 있습니다.", "visual baseline, viewport matrix, diff threshold, review workflow", [{ q: "threshold는?", answer: "픽셀 차이를 무조건 0으로 두면 font rendering이나 antialiasing 때문에 불안정해질 수 있습니다. 컴포넌트 성격에 따라 threshold를 작게 두되, 버튼 위치·텍스트 overflow·z-index·차트 축처럼 의미 있는 변화는 reviewer가 확인하도록 diff workflow를 둡니다." }, { q: "동적 데이터는?", answer: "날짜, 랜덤 아바타, 실시간 수치, 애니메이션은 fixture와 clock freeze로 고정합니다. 외부 이미지나 chart 데이터는 deterministic sample을 쓰고, skeleton·loading·error 상태도 별도 baseline으로 관리합니다." }, { q: "모든 페이지에 필요?", answer: "모든 페이지에 같은 강도로 적용하면 유지비가 커집니다. 디자인 시스템 primitive, 고매출 funnel, 복잡한 responsive grid, chart, editor, 3D/canvas preview처럼 시각 오류 비용이 큰 곳부터 coverage를 둡니다." }]),
      item("접근성 테스트 자동화의 한계는?", "axe 같은 도구는 일부 규칙을 잡지만 keyboard flow, screen reader 맥락, 문구 의미는 사람이 확인해야 합니다.", "자동 검사 통과를 접근성 완료로 보면 focus order와 실제 announcement 문제를 놓칩니다.", "axe report, manual keyboard recording, screen reader smoke, WCAG checklist", [{ q: "자동화로 몇 퍼센트 잡나요?", answer: "정확한 비율보다 어떤 유형을 못 잡는지 아는 것이 중요합니다. color contrast, missing label, landmark 같은 규칙은 잘 잡지만, 업무 문맥에 맞는 오류 문구, focus 이동 의도, screen reader announcement의 자연스러움은 수동 확인이 필요합니다." }, { q: "수동 테스트 최소 기준은?", answer: "키보드만으로 핵심 여정을 완료하고, focus가 보이며, dialog와 menu가 열리고 닫힐 때 focus가 올바르게 이동해야 합니다. form error summary, live region, route change heading, screen reader smoke를 릴리스 전 체크에 포함합니다." }, { q: "디자인 단계에서?", answer: "색 대비, touch target, focus order, error message 위치, dialog 구조, reduced motion 요구는 구현 후보다 디자인 단계에서 잡는 편이 비용이 낮습니다. Figma annotation이나 design checklist에 accessible name과 keyboard behavior를 같이 적습니다." }]),
      item("sourcemap은 어떻게 운영하나요?", "에러 추적에는 필요하지만 공개 접근, source 노출, release id mapping, 업로드 보안 정책을 관리해야 합니다.", "sourcemap을 공개 CDN에 그대로 두면 내부 소스 구조와 주석이 노출될 수 있습니다.", "sourcemap upload log, release id, access policy, error stack deobfuscation", [{ q: "sourcemap을 배포하지 않으면?", answer: "사용자 오류 stack이 minified 위치로만 남아 원인 분석 시간이 크게 늘어납니다. 공개 CDN에 노출하지 않더라도 Sentry 같은 error tracker에는 private sourcemap을 업로드하고 release id와 commit sha를 맞춰 deobfuscation되게 해야 합니다." }, { q: "private sourcemap은?", answer: "빌드 산출물과 별도 artifact로 저장하고 접근 권한을 제한합니다. 업로드 로그, 보존 기간, 프로젝트별 token scope를 관리하며, sourceContent 포함 여부와 민감 주석·내부 URL 노출 가능성을 audit합니다." }, { q: "release id는 왜?", answer: "브라우저가 실행한 bundle version과 sourcemap artifact를 정확히 연결하기 위해 필요합니다. CDN 캐시나 canary가 섞이면 같은 오류도 version별 원인이 다를 수 있으므로 release id, build id, commit sha를 error event에 포함합니다." }]),
      item("CDN cache 때문에 배포가 깨지는 경우는?", "HTML과 JS asset cache 정책이 어긋나면 새 HTML이 오래된 JS를 참조하거나 반대 상황이 생깁니다.", "content hash 없는 asset을 길게 cache하면 사용자가 오래된 코드를 계속 받습니다.", "cache header audit, asset hash, purge log, stale bundle fixture", [{ q: "HTML은 어떻게 cache?", answer: "HTML은 최신 asset manifest를 가리켜야 하므로 짧은 TTL이나 revalidation을 둡니다. 정적 asset과 달리 오래 cache하면 새 라우트나 chunk 이름을 못 찾아 blank screen이 날 수 있어 cache-control과 CDN purge 정책을 함께 검증합니다." }, { q: "immutable asset은?", answer: "content hash가 붙은 JS/CSS/image는 긴 max-age와 immutable을 줄 수 있습니다. 같은 URL의 내용을 바꾸지 않는 것이 핵심이고, hash 없는 vendor.js 같은 파일에 immutable을 주면 rollback과 partial deployment에서 stale 코드가 남습니다." }, { q: "rollback과 cache는?", answer: "이전 HTML이 새 asset을 참조하거나 새 HTML이 purge된 asset을 참조하는 조합을 피해야 합니다. rollback artifact를 보존하고, CDN purge 순서, service worker cache, chunk compatibility를 smoke fixture로 확인합니다." }]),
      item("환경변수 drift는 어떻게 막나요?", "환경별 required env schema, build-time/runtime 구분, validation, release diff를 둡니다.", "staging에는 있고 production에는 없는 env가 배포 후 런타임 오류를 만들 수 있습니다.", "env schema, startup validation, release config diff, smoke test", [{ q: "프론트 env는 왜 build-time인가요?", answer: "대부분의 프론트 env는 build 시 bundle에 문자열로 치환됩니다. 배포 후 서버 env만 바꿔도 이미 생성된 JS에는 반영되지 않으므로 API base URL, feature flag default, public key 변경은 rebuild나 runtime config endpoint 전략을 명확히 해야 합니다." }, { q: "secret env는?", answer: "브라우저로 전달되는 env는 secret이 아닙니다. secret이 필요한 API 호출은 서버나 BFF에서 처리하고, 프론트에는 public identifier만 전달합니다. env schema에서 public/private 구분과 prefix 규칙을 검증해야 합니다." }, { q: "기본값을 코드에 넣어도?", answer: "dev 편의 기본값은 production에서 위험할 수 있습니다. production build에서는 required env가 없으면 실패하게 하고, staging·preview·production의 config diff를 release note에 남깁니다. fallback URL이나 debug flag가 운영으로 들어가지 않게 테스트합니다." }]),
      item("배포 후 모니터링은 무엇을 보나요?", "client error rate, route-specific Web Vitals, API failure, conversion, blank screen signal, release adoption을 봅니다.", "서버가 정상이어도 프론트 bundle 오류나 특정 브라우저 오류로 사용자는 장애를 겪을 수 있습니다.", "release dashboard, error tracking, RUM by version, synthetic smoke", [{ q: "몇 시간 봐야 하나요?", answer: "첫 10~30분은 syntax error, chunk load failure, 5xx, auth loop처럼 즉시 드러나는 문제를 봅니다. 이후 주요 트래픽 시간대까지 Web Vitals, conversion, route-specific error, browser segment를 보고, 하루 단위로 long-tail 기기와 CDN region을 확인합니다." }, { q: "브라우저별 segment는?", answer: "Safari iOS, Android WebView, 오래된 Chromium, enterprise browser처럼 runtime 차이가 큰 segment를 따로 봅니다. release version, route, device memory, network type과 묶어야 특정 브라우저에서만 나는 blank screen이나 CSS 깨짐을 발견할 수 있습니다." }, { q: "blank screen은 어떻게 감지?", answer: "window error만으로는 부족합니다. root element가 일정 시간 비어 있는지, critical route marker가 렌더됐는지, chunk load failure와 hydration error가 있었는지 client heartbeat로 보냅니다. synthetic smoke도 대표 route를 주기적으로 열어 확인합니다." }]),
      item("rollback 기준은 어떻게 정하나요?", "error rate, core journey failure, Web Vitals regression, conversion drop, security issue 같은 threshold를 미리 정합니다.", "감으로 결정하면 복구가 늦고, 반대로 작은 오류에 과도하게 rollback할 수 있습니다.", "rollback playbook, release health window, threshold alert, decision log", [{ q: "forward fix와 rollback 선택은?", answer: "원인이 명확하고 수정·검증·배포가 rollback보다 빠르면 forward fix를 선택할 수 있습니다. 인증, 결제, blank screen, 보안 노출처럼 영향이 큰 문제는 원인 분석을 기다리지 않고 rollback이나 flag off로 사용자 영향을 먼저 줄입니다." }, { q: "DB/API 변경이 있으면?", answer: "프론트만 되돌려도 API contract나 데이터 migration이 이미 바뀌었으면 깨질 수 있습니다. backward compatible API, expand-contract 순서, feature flag, migration rollback 가능성을 릴리스 전에 확인하고 playbook에 책임자를 명시합니다." }, { q: "feature flag로 충분?", answer: "flag가 문제 코드를 완전히 우회하고 default off가 안전하면 빠른 완화 수단이 됩니다. 하지만 bundle load error, shared dependency 회귀, CSS 전역 깨짐, 보안 secret 노출은 flag로 해결되지 않을 수 있어 artifact rollback 경로가 필요합니다." }]),
      item("feature flag 릴리스는 어떻게 검증하나요?", "flag default, targeting, exposure logging, kill switch, stale cleanup, permission과의 차이를 검증합니다.", "flag가 켜진 사용자와 꺼진 사용자의 cache/state가 섞이면 재현 어려운 버그가 생깁니다.", "flag matrix, exposure event, kill switch drill, cleanup ticket", [{ q: "flag default는?", answer: "네트워크 실패나 flag service 장애 때 어떤 값으로 동작할지 정해야 합니다. 보안·결제·권한 기능은 fail closed가 맞을 수 있고, 읽기 전용 UI는 fail open이 더 나을 수 있습니다. default는 코드, 문서, 테스트 fixture가 일치해야 합니다." }, { q: "서버와 프론트 flag 불일치는?", answer: "서버는 새 API를 열었는데 프론트는 off거나 반대인 경우가 생깁니다. flag key, rollout condition, permission, API contract를 한 matrix에서 검증하고 exposure event에 flag version과 user segment를 남겨 재현 가능하게 합니다." }, { q: "실험과 rollout 차이는?", answer: "실험은 variant별 효과 측정을 위해 assignment, exposure, guardrail metric, SRM 확인이 중요합니다. rollout은 위험을 줄이기 위한 점진 노출이 목적이라 kill switch, error threshold, canary segment, cleanup ticket이 핵심입니다." }]),
      item("브라우저 호환성은 어떻게 관리하나요?", "지원 브라우저 matrix, polyfill, transpilation target, CSS feature support, 테스트 범위를 명시합니다.", "개발자 최신 Chrome에서만 확인하면 Safari/iOS/WebView에서 깨질 수 있습니다.", "browser matrix, caniuse review, cross-browser E2E, CSS support audit", [{ q: "Safari 이슈가 많은 이유는?", answer: "WebKit의 API 지원 시점, form control 동작, viewport unit, video/autoplay, storage 제한, CSS 기능 차이가 Chrome과 다릅니다. iOS의 모든 브라우저가 WebKit 기반인 점도 고려해 실제 iPhone 또는 WebKit runner로 핵심 여정을 확인합니다." }, { q: "polyfill 비용은?", answer: "polyfill은 bundle 크기, parse time, 전역 객체 변경, 오래된 브라우저 성능 비용을 만듭니다. 지원 비율과 기능 중요도를 보고 route별 동적 로딩이나 progressive enhancement로 대체할 수 있는지 검토합니다." }, { q: "지원 종료는 어떻게?", answer: "RUM의 브라우저 사용률, 매출·계약 영향, 보안 지원, 장애 비용을 근거로 결정합니다. 종료 전 공지, fallback 화면, browserslist 변경, E2E matrix 축소, 고객지원 대응 문구를 함께 준비해야 합니다." }]),
      item("프론트엔드 보안 리뷰에서 source-sink 분석은?", "입력 source가 어느 변환을 거쳐 dangerous sink로 가는지 추적합니다. HTML, URL, script, style, postMessage sink를 구분합니다.", "입력 검증만 보고 실제 sink를 보지 않으면 sanitizer bypass와 DOM XSS를 놓칩니다.", "source-sink table, negative fixture, sanitizer config, Trusted Types report", [{ q: "URL도 sink인가요?", answer: "네. href, src, location.assign, window.open, CSS url()은 사용자 입력이 javascript:, data:, file:, open redirect로 이어질 수 있는 sink입니다. URL parser로 protocol과 host를 검증하고 allowlist와 rel=noopener 정책을 적용합니다." }, { q: "style injection은?", answer: "style 속성이나 CSS 변수에 사용자 입력을 넣으면 url(), expression legacy, layout overlay, clickjacking 보조 경로가 될 수 있습니다. 허용 값은 enum이나 numeric range로 제한하고 raw CSS 문자열 조합을 피합니다." }, { q: "postMessage는?", answer: "message event의 data는 외부 source입니다. origin, source window, schema version을 검증하지 않고 routing, token 전달, DOM update에 쓰면 cross-origin 주입이 됩니다. 수신부를 source-sink table에 포함해야 합니다." }]),
      item("postMessage는 어떻게 안전하게 쓰나요?", "targetOrigin을 구체적으로 지정하고, 수신 시 origin/source/schema를 검증합니다.", "wildcard와 schema 검증 누락은 다른 origin이 메시지를 주입하는 경로가 됩니다.", "postMessage fixture, origin allowlist, schema parser, security test", [{ q: "targetOrigin *는 언제 위험?", answer: "민감 데이터, auth 상태, user id, payment result를 보낼 때 *를 쓰면 의도하지 않은 frame이 메시지를 받을 수 있습니다. 수신 origin을 정확히 알고 있으면 명시하고, 동적 origin은 allowlist 검증 뒤에만 사용합니다." }, { q: "iframe source는?", answer: "event.origin만 보지 말고 event.source가 기대한 iframe.contentWindow인지 확인합니다. 같은 origin을 쓰는 여러 frame이나 popup이 있으면 message channel, nonce, session id로 어떤 창과 대화하는지 고정합니다." }, { q: "메시지 버전은?", answer: "schema version을 넣어 필드 추가·삭제 시 하위 호환을 관리합니다. zod 같은 parser로 type과 enum을 검증하고, 알 수 없는 version은 무시하거나 안전한 fallback으로 처리합니다. 테스트에는 악성 origin과 malformed payload fixture를 포함합니다." }]),
      item("dependency 보안은 어떻게 관리하나요?", "lockfile, audit, maintainer 신뢰, transitive dependency, bundle impact, update test를 봅니다.", "보안 패치만 보고 major update를 무검증 적용하면 runtime 회귀가 생길 수 있습니다.", "dependency diff, npm audit, changelog review, smoke test", [{ q: "audit false positive는?", answer: "취약한 package가 실제 bundle에 들어가는지, 취약 API를 호출하는지, dev dependency인지, exploit path가 브라우저에 도달하는지 확인합니다. false positive라도 근거를 남기고, reachable이면 patch, override, 대체 package를 검토합니다." }, { q: "pinning은?", answer: "lockfile은 재현 가능한 설치를 보장하지만 오래 고정하면 보안 패치를 놓칠 수 있습니다. Renovate 같은 자동 PR, changelog review, bundle diff, smoke test를 묶어 주기적으로 업데이트하고 critical patch는 별도 fast lane을 둡니다." }, { q: "supply chain 위험은?", answer: "maintainer 변경, install script, typosquatting, 과도한 transitive dependency, prebuilt binary, publish 권한 탈취를 봅니다. package provenance, npm token 정책, lockfile diff, SRI 또는 registry policy로 위험을 줄입니다." }]),
      item("프론트엔드 테스트 데이터는 어떻게 관리하나요?", "fixture, factory, mock server, contract sample을 분리하고 PII 없는 데이터를 씁니다.", "실제 사용자 데이터를 테스트에 넣으면 개인정보와 재현성 문제가 생깁니다.", "fixture inventory, mock contract, PII scan, deterministic seed", [{ q: "MSW는 언제?", answer: "컴포넌트와 브라우저 테스트에서 실제 fetch 흐름을 유지하면서 API 응답만 제어하고 싶을 때 유용합니다. loading, 401, 403, 500, timeout, partial data를 fixture로 고정하고, handler가 실제 contract와 어긋나지 않게 schema 검증을 붙입니다." }, { q: "fixture가 오래되면?", answer: "API 필드가 바뀌어도 테스트가 계속 통과하는 drift가 생깁니다. contract sample을 backend schema나 OpenAPI에서 갱신하고, fixture inventory에 owner와 마지막 검토일을 두며, production shape와 다른 테스트 전용 shortcut을 줄입니다." }, { q: "계약 샘플은 누가 관리?", answer: "API owner와 frontend owner가 함께 관리해야 합니다. backend가 schema 변경 PR에서 sample을 갱신하고, frontend는 UI 상태 matrix에 필요한 edge case를 추가합니다. PII가 들어가지 않도록 synthetic data와 redaction scan을 사용합니다." }]),
      item("API mocking의 위험은 무엇인가요?", "mock이 실제 API와 drift되면 테스트는 통과하지만 production에서 깨집니다. contract test나 schema sync가 필요합니다.", "너무 완벽한 mock은 latency, error, partial failure를 숨깁니다.", "mock/schema diff, contract test, error fixture, latency simulation", [{ q: "mock server와 stub 차이는?", answer: "stub은 특정 테스트에서 짧게 응답을 대체하는 경우가 많고, mock server는 앱이 실제 네트워크 계층을 타는 것처럼 여러 endpoint와 상태를 제공합니다. 핵심 여정 E2E에는 mock server가 drift를 줄이지만 contract sync가 없으면 가짜 현실이 됩니다." }, { q: "에러 케이스는?", answer: "400 field error, 401 refresh 실패, 403 권한 제거, 409 conflict, 429 rate limit, 500, timeout, malformed response를 포함합니다. 성공 path만 mock하면 retry, rollback, toast, form error, monitoring event가 릴리스 전 검증되지 않습니다." }, { q: "GraphQL mock은?", answer: "schema와 operation document를 기준으로 mock을 생성하고, nullable field, union/interface, partial error, persisted query 실패를 fixture로 둡니다. resolver가 실제 permission이나 pagination 규칙을 지나치게 단순화하면 production 회귀를 못 잡습니다." }]),
      item("릴리스 노트에는 무엇을 남겨야 하나요?", "변경 범위, 영향 사용자, flag, migration, rollback, 모니터링 지표, known risk를 남깁니다.", "커밋 메시지만 있으면 운영자가 장애 시 어떤 변경이 영향을 줬는지 파악하기 어렵습니다.", "release note, change log, flag list, risk register", [{ q: "내부 릴리스도?", answer: "내부 도구라도 권한, 데이터 수정, 업무 마감 시간, 관리자 기능에 영향을 주면 릴리스 노트가 필요합니다. 영향 route, feature flag, API contract, rollback 방법, 모니터링 dashboard 링크를 남겨 운영자가 장애 시 빠르게 판단하게 합니다." }, { q: "사용자 공지는?", answer: "사용자가 워크플로 변경, 데이터 표시 변경, 중단 시간, 브라우저 지원 종료를 체감하면 공지가 필요합니다. 단순 버그 수정은 내부 changelog면 충분할 수 있지만, UI 위치 변경이나 권한 정책 변경은 help center와 support script를 함께 갱신합니다." }, { q: "known issue는?", answer: "사소한 결함을 숨기지 말고 영향 범위, 회피 방법, 수정 예정, rollback 기준을 적습니다. 예를 들어 Safari에서 chart tooltip이 느린 문제처럼 segment가 명확하면 모니터링 조건과 고객지원 대응을 같이 남깁니다." }]),
      item("프론트엔드 장애 postmortem은 무엇을 다루나요?", "영향 route, browser/device segment, release version, detection gap, rollback time, 재발 방지 action을 다룹니다.", "서버 장애 형식만 복사하면 bundle/cache/browser-specific 원인을 놓칩니다.", "frontend incident timeline, RUM segment, error stack, action item", [{ q: "고객 영향은 어떻게 산정?", answer: "영향 route의 방문자 수, 실패 event, conversion drop, support ticket, browser/device segment, release adoption 비율을 합쳐 봅니다. 서버 uptime이 정상이어도 프론트 blank screen이나 chunk error가 있으면 실제 사용자 실패로 계산해야 합니다." }, { q: "원인 하나면 충분?", answer: "직접 원인만 쓰면 재발 방지가 약합니다. 예를 들어 stale CDN asset이 직접 원인이어도, cache header 검증 부재, canary 부족, alert 지연, rollback artifact 미보존 같은 contributing factor를 함께 다룹니다." }, { q: "액션 아이템 좋은 기준은?", answer: "소유자, 기한, 검증 방법이 있어야 합니다. cache smoke 추가, sourcemap release id 검증, Safari E2E 추가, flag kill switch drill처럼 다음 릴리스에서 실제로 같은 장애를 잡을 수 있는 항목이어야 합니다." }]),
      item("보안 헤더는 프론트 품질과 어떻게 연결되나요?", "CSP, HSTS, X-Frame-Options/frame-ancestors, Referrer-Policy, Permissions-Policy는 브라우저 실행 환경을 제한합니다.", "헤더는 백엔드/인프라에서 설정되지만 프론트 기능과 충돌할 수 있어 함께 검증해야 합니다.", "security header audit, CSP report, clickjacking fixture, permissions policy test", [{ q: "CSP rollout은?", answer: "처음부터 강제하면 기존 inline script나 third-party tag가 깨질 수 있습니다. report-only로 violation을 수집하고, nonce/hash, script-src, connect-src, frame-src를 서비스별로 정리한 뒤 핵심 route에서 강제 정책을 적용합니다." }, { q: "frame-ancestors와 X-Frame-Options?", answer: "둘 다 clickjacking 방어와 관련 있지만 CSP frame-ancestors가 더 세밀하고 현대적입니다. embed가 필요한 파트너 origin이 있으면 allowlist를 명확히 하고, 그렇지 않으면 none 또는 sameorigin으로 막습니다." }, { q: "Referrer-Policy는?", answer: "외부 이동 시 URL path나 query에 포함된 민감 정보가 넘어가지 않도록 제한합니다. analytics attribution과 privacy 사이에서 정책을 정하고, UTM·token·email 같은 값이 URL에 섞이지 않도록 route 설계도 함께 고칩니다." }]),
      item("품질 게이트가 개발 속도를 늦추지 않게 하려면?", "위험 기반으로 필수 자동화와 수동 증거를 나누고, 변경 범위별 checklist를 다르게 둡니다.", "모든 변경에 같은 무거운 절차를 요구하면 팀이 우회하고 품질 체계가 무력화됩니다.", "risk tier matrix, CI duration, checklist by change type, escape hatch policy", [{ q: "핫픽스는?", answer: "핫픽스는 절차를 없애는 것이 아니라 최소 생존 게이트를 둡니다. 영향 route smoke, typecheck, targeted E2E, rollback 확인, owner 승인, 배포 후 짧은 health watch를 수행하고, 빠진 테스트는 후속 ticket로 닫습니다." }, { q: "문서 변경은?", answer: "순수 문서라면 전체 E2E는 과합니다. 링크 검사, markdown build, 검색 색인 생성, 접근성 heading 구조 정도면 충분할 수 있습니다. 다만 docs site의 route, SEO metadata, sitemap을 바꾸면 해당 영역 smoke를 추가합니다." }, { q: "예외 승인은?", answer: "예외는 구두로 넘기지 않고 위험, 만료 시점, 보상 통제, 승인자, 후속 조치를 기록합니다. 예외가 반복되면 게이트가 현실과 맞지 않는 신호이므로 CI 시간, flaky 테스트, 소유권을 개선해야 합니다." }]),
      item("릴리스 Q&A에서 senior-level 답변은?", "성공 빌드보다 실제 사용자 영향, 보안 경계, 관측성, rollback, 재발 방지를 먼저 말합니다.", "테스트 통과만 말하면 production 운영 책임을 이해하지 못한 답변으로 보입니다.", "FRONTEND RELEASE QUALITY MODEL, release health window, security fixture, rollback log", [{ q: "테스트가 충분한지 어떻게?", answer: "테스트 수가 아니라 위험 경로 coverage로 판단합니다. 인증, 결제, 권한, 데이터 손실, XSS/CSRF, CDN cache, sourcemap, 브라우저 호환성, Web Vitals, analytics event가 변경 영향 안에 있으면 각각 어떤 증거로 닫았는지 설명해야 합니다." }, { q: "빌드 성공 후 무엇을?", answer: "artifact가 의도한 env로 빌드됐는지, sourcemap과 release id가 맞는지, CDN cache header가 올바른지, smoke route가 열리는지, error tracker와 RUM이 새 version을 받는지 확인합니다. 빌드는 릴리스 검증의 시작일 뿐입니다." }, { q: "외부 검증 증거는?", answer: "Playwright trace, error dashboard, RUM release segment, CSP report, bundle diff, cache header capture, URL별 smoke screenshot, rollback drill log가 증거가 됩니다. 답변에서는 추상적 자신감보다 이 자료를 어떤 순서로 확인했는지를 말합니다." }]),
      item("품질 경험이 적으면 어떻게 답변하나요?", "test pyramid, XSS/CSRF 기본 threat model, sourcemap/cache/env/rollback 체크리스트, 배포 후 모니터링 계획을 구체화합니다.", "막연히 꼼꼼히 테스트한다고 말하면 검증 가능한 기준이 없습니다.", "quality checklist, sample threat model, release runbook, smoke test plan", [{ q: "실제 장애 경험이 없으면?", answer: "없다고 인정하고 대신 샘플 프로젝트에서 만든 runbook을 설명합니다. 예를 들어 chunk load failure, stale CDN cache, XSS markdown fixture, 401 refresh 실패를 가정해 재현, 탐지 지표, rollback 기준, 후속 테스트를 어떻게 만들었는지 말하면 실무 사고를 보여줄 수 있습니다." }, { q: "보안 질문이 깊어지면?", answer: "모르는 세부 exploit은 추측하지 말고 threat model 경계로 답합니다. XSS는 source와 sink, CSRF는 cookie 자동 전송, token 저장은 탈취와 revocation, CORS는 브라우저 응답 노출 정책으로 나누고 확인할 로그와 fixture를 제시합니다." }, { q: "테스트 수치가 없으면?", answer: "coverage percentage를 꾸며내지 말고 앞으로의 측정 계획을 말합니다. 핵심 여정 E2E 수, component state matrix, axe violation, visual baseline, error budget, release health window를 정의하고 첫 릴리스부터 dashboard와 회고에 남기겠다고 답합니다." }]),
    ],
  },
];

const coverageAdditions = {
  "engineering-frontend-core-qa": [
    item("브라우저 호환성 이슈는 어떻게 답변하나요?", "표준 지원 여부, browser matrix, polyfill, progressive enhancement, fallback을 기준으로 답합니다.", "최신 Chrome 기준으로만 구현하면 Safari, iOS WebView, 저사양 Android에서 핵심 흐름이 깨질 수 있습니다.", "browser support matrix, caniuse audit, cross-browser E2E, fallback screenshot", [{ q: "polyfill은 언제 넣나요?", answer: "지원 브라우저에서 핵심 사용자 흐름에 필요한 API가 없고 fallback만으로 제품 요구를 만족할 수 없을 때 넣습니다. polyfill의 bundle 비용, 전역 오염, 오래된 브라우저 성능을 확인하고 route별 로딩도 고려합니다." }, { q: "지원 브라우저를 줄이려면?", answer: "사용자 비율, 매출·업무 영향, 장애 비용, 대체 접근 가능성을 데이터로 보고 결정합니다. 단순히 개발 편의로 줄이지 않고 browser matrix, RUM segment, 고객 공지와 graceful fallback 계획을 함께 둡니다." }, { q: "progressive enhancement는?", answer: "기본 HTML과 form, link, 읽기 가능한 콘텐츠로 핵심 작업을 제공하고 지원 환경에서만 고급 API를 더하는 방식입니다. 예를 들어 Web Share나 View Transition이 없어도 저장, 제출, 탐색은 계속 동작해야 합니다." }]),
    item("API 오류를 UI 상태로 어떻게 매핑하나요?", "HTTP status, domain error code, retryable 여부, field error, global error, auth error를 화면 상태와 연결합니다.", "모든 오류를 toast로만 처리하면 사용자가 무엇을 고쳐야 하는지, 재시도 가능한지 알 수 없습니다.", "error contract, UI state matrix, negative fixture, retry event log", [{ q: "500과 network error는?", answer: "500은 서버가 응답했지만 처리에 실패한 상태라 traceId와 재시도 또는 문의 경로를 줄 수 있습니다. network error는 응답 자체가 없을 수 있으므로 offline, timeout, CORS 실패를 구분하고 연결 복구나 retry 상태를 보여줘야 합니다." }, { q: "field error와 form error는?", answer: "field error는 email 형식, 중복 이름처럼 특정 입력 옆에서 고칠 수 있는 오류입니다. form error는 인증 만료, 결제 승인 실패, 서버 장애처럼 제출 전체에 영향을 주는 오류라 상단 summary와 recovery action이 필요합니다." }, { q: "traceId를 보여줘야 하나요?", answer: "사용자에게 문의나 지원 연결이 필요한 오류라면 짧은 오류 코드나 traceId를 보여주는 것이 좋습니다. 다만 내부 stack, token, 원본 payload를 노출하지 말고 client log와 server log를 연결할 식별자만 제공합니다." }]),
  ],
  "engineering-frontend-interaction-qa": [
    item("인터랙션에서 permission change는 어떻게 처리하나요?", "사용자가 화면에 머무는 동안 권한이나 소유권이 바뀔 수 있으므로 action 직전 서버 결과를 기준으로 UI를 수렴시켜야 합니다.", "초기 렌더 때 보인 버튼만 믿으면 만료된 권한으로 실패하거나 잘못된 optimistic UI를 보여줄 수 있습니다.", "permission fixture, 403 recovery flow, stale permission test, audit log", [{ q: "버튼을 숨기면 충분한가요?", answer: "충분하지 않습니다. 숨김은 사용성 힌트일 뿐이고 서버가 action 직전에 권한을 다시 판단해야 합니다. 버튼이 보이는 상태에서 권한이 내려가는 fixture, keyboard shortcut이나 command palette 우회, optimistic mutation reject를 함께 검증합니다." }, { q: "403 후 화면은?", answer: "서버 최종 결과를 기준으로 optimistic 변경을 되돌리고, action 영역에는 권한이 사라졌다는 persistent 상태를 보여줍니다. focus는 오류 설명이나 다음 가능한 action으로 보내고, audit log와 analytics error result에는 403과 대상 action을 남깁니다." }, { q: "권한 cache는 어떻게?", answer: "권한 cache는 짧은 staleTime이나 서버 push/invalidation과 함께 써야 하며 보안 판단의 원본이 되면 안 됩니다. route loader, menu filtering, command palette가 같은 permission source를 쓰게 하고 role change fixture로 cache 수렴을 확인합니다." }]),
  ],
  "engineering-frontend-motion-qa": [
    item("모션과 디자인 토큰은 어떻게 연결하나요?", "duration, easing, distance, opacity, scale을 token으로 관리하고 컴포넌트 상태별 사용 범위를 제한합니다.", "코드에 임의 숫자가 퍼지면 브랜드 일관성, reduced motion 대응, 회귀 검증이 어려워집니다.", "motion token diff, component usage audit, visual regression, reduced-motion token", [{ q: "토큰이 너무 많아지면?", answer: "컴포넌트마다 새 duration/easing을 만들지 말고 feedback, overlay, navigation, emphasis처럼 용도별 token으로 묶습니다. 예외 token은 사용처와 이유를 기록하고 reduced motion 대체 값까지 같이 정의해야 관리 가능한 시스템이 됩니다." }, { q: "제품별 예외는?", answer: "브랜드나 플랫폼 차이 때문에 예외가 필요하면 base token을 덮는 product alias로 관리합니다. 핵심 interaction의 interrupt, accessibility, performance budget은 공통 기준을 유지하고 값만 product theme에서 조정하는 방식이 안전합니다." }, { q: "디자인 변경 반영은?", answer: "Figma token과 코드 token의 이름을 맞추고 diff가 생기면 영향 컴포넌트, visual regression, reduced motion snapshot을 함께 확인합니다. duration/easing 변경은 감성 변경처럼 보여도 INP, focus timing, transition cleanup에 영향을 줄 수 있습니다." }]),
  ],
  "engineering-frontend-graphics-3d-qa": [
    item("그래픽 기능에서 progressive enhancement는 어떻게 적용하나요?", "핵심 정보는 HTML/SVG/정적 이미지로 제공하고, 지원 환경에서 Canvas/WebGL 상호작용을 강화합니다.", "고급 렌더링이 실패하면 핵심 기능까지 사라지는 구조는 제품 기능으로 보기 어렵습니다.", "feature detection, fallback parity test, no-WebGL capture, content audit", [{ q: "fallback 정보량은?", answer: "핵심 데이터, 선택 가능한 대상, 상태 메시지는 WebGL 버전과 같아야 합니다. shader 효과나 3D orbit은 빠져도 되지만 SVG, 정적 이미지, 표, 리스트로 사용자가 같은 판단과 작업을 할 수 있어야 합니다." }, { q: "성능 낮은 기기에는?", answer: "DPR cap, texture LOD, draw call 제한, postprocessing off, static preview 같은 low preset을 먼저 적용합니다. 그래도 frame time이나 context loss가 나쁘면 Canvas/SVG/HTML fallback으로 전환하고 device tier와 renderer.info를 로그로 남깁니다." }, { q: "사용자가 직접 전환할 수 있나요?", answer: "가능해야 합니다. 자동 감지와 별개로 정적 보기, 데이터 표 보기, 애니메이션 끄기, 저품질 렌더링 같은 control을 제공하면 접근성 요구와 배터리/저사양 환경을 사용자가 직접 조정할 수 있습니다." }]),
  ],
  "engineering-frontend-performance-qa": [
    item("성능 최적화가 기능 회귀를 만들지 않게 하려면?", "변경 전후 사용자 여정, 접근성, analytics event, visual state를 함께 검증합니다.", "렌더 횟수를 줄이려다 stale UI, 누락된 announcement, 잘못된 cache invalidation을 만들 수 있습니다.", "before/after trace, E2E journey, a11y smoke, event QA log", [{ q: "memoization 회귀는?", answer: "memoization은 stale props, stale closure, 잘못된 dependency로 최신 상태를 막을 수 있습니다. Profiler로 render count와 commit duration 개선을 확인하면서 E2E로 필터, 권한, analytics event, screen reader announcement가 최신 상태로 갱신되는지 검증합니다." }, { q: "cache 최적화 위험은?", answer: "runtime cache나 SW cache가 stale API, 오래된 bundle, 권한 변경 누락을 만들 수 있습니다. cache key, TTL, invalidation, release version을 명확히 하고 network waterfall과 RUM error segment에서 cache hit 후 기능 오류가 늘지 않는지 봅니다." }, { q: "성능 PR 증거는?", answer: "PR에는 before/after Web Vitals 또는 lab trace, bundle diff, React Profiler export, network waterfall, 영향 route와 device 조건을 붙입니다. 동시에 기능 smoke, a11y keyboard flow, visual diff, rollback 조건을 함께 남겨 최적화가 기능을 깨지 않았음을 보여줍니다." }]),
  ],
  "engineering-frontend-seo-analytics-qa": [
    item("crawl budget은 언제 신경 써야 하나요?", "대규모 URL, 필터 파라미터, 중복 콘텐츠, 자주 바뀌는 페이지가 많을 때 중요합니다.", "중요하지 않은 URL이 많이 열리면 검색 엔진이 핵심 페이지를 늦게 발견하거나 덜 자주 갱신합니다.", "crawl stats, URL parameter policy, sitemap inventory, internal link audit", [{ q: "작은 사이트도 필요한가요?", answer: "작은 사이트는 보통 crawl budget 자체보다 indexability가 더 중요합니다. 그래도 robots, sitemap, canonical, internal links가 잘못되어 핵심 URL이 발견되지 않는 문제는 동일하게 생기므로 Search Console coverage와 URL inspection은 봐야 합니다." }, { q: "필터 URL은?", answer: "색인 가치가 없는 정렬, 가격 범위, tracking parameter URL은 canonical, robots, parameter policy로 제한합니다. 검색 수요가 있는 필터 조합만 별도 landing URL로 만들고 sitemap과 internal links에 포함합니다." }, { q: "크롤링 빈도는 어떻게 보나요?", answer: "Search Console crawl stats, server log, CDN log에서 Googlebot 요청 URL, status code, response time, fetch volume을 봅니다. 중요한 URL이 드물게 크롤링되면 sitemap lastmod, internal link depth, duplicate URL 낭비를 확인합니다." }]),
    item("analytics dashboard를 신뢰하려면 무엇을 확인하나요?", "event schema, 중복 수집, consent 누락, bot/internal traffic, release annotation, sampling을 확인합니다.", "대시보드 수치가 있어도 수집 품질이 낮으면 잘못된 제품 결정을 하게 됩니다.", "data quality dashboard, debug event log, anomaly alert, tracking plan review", [{ q: "수치가 갑자기 변하면?", answer: "먼저 release annotation, tag 변경, consent banner 변경, bot/internal filter, UTM campaign, sampling 조건을 확인합니다. 제품 변화인지 tracking 품질 문제인지 가르려면 raw event count, GA4 DebugView, warehouse ingest log를 같이 봅니다." }, { q: "이벤트 누락은?", answer: "tracking plan의 필수 event를 route와 funnel 단계별로 QA하고, client log와 collector 수신 로그를 대조합니다. SPA route change, lazy-loaded form, consent 이전 차단, ad blocker 영향이 누락 원인인지 분리합니다." }, { q: "샘플링은?", answer: "샘플링이 있으면 작은 segment나 funnel step의 수치가 왜곡될 수 있습니다. GA4 탐색 보고서, warehouse export, BI aggregation의 sampling 여부를 표시하고 의사결정용 dashboard는 가능하면 unsampled source를 씁니다." }]),
  ],
  "engineering-frontend-quality-qa": [
    item("canary release는 프론트엔드에서 어떻게 적용하나요?", "사용자 세그먼트, route, feature flag, release version 기준으로 점진 노출하고 error/Web Vitals/conversion guardrail을 봅니다.", "전체 사용자에게 한 번에 배포하면 브라우저·기기 특정 회귀의 blast radius가 커집니다.", "canary dashboard, guardrail threshold, release version RUM, rollback log", [{ q: "canary 표본은?", answer: "트래픽이 너무 작으면 브라우저별 오류나 conversion 하락을 볼 수 없고, 너무 크면 장애 반경이 커집니다. 내부 사용자, 저위험 계정, 특정 region, 1% 외부 트래픽처럼 단계별로 키우며 error rate, Web Vitals p75, chunk load failure, 핵심 funnel을 봅니다." }, { q: "flag와 canary 차이는?", answer: "canary는 새 artifact나 release version을 일부 사용자에게 노출하는 배포 전략이고, feature flag는 코드 안의 기능 경로를 켜고 끄는 제어 장치입니다. 둘을 함께 쓰면 새 bundle의 안정성과 특정 기능의 안정성을 분리해서 볼 수 있습니다." }, { q: "성공 판정은?", answer: "정해둔 guardrail을 이전 release와 비교해 통과해야 합니다. client error, blank screen, Web Vitals, API failure, conversion, support ticket이 threshold 안에 있고, 특정 브라우저·route segment에서 spike가 없으면 다음 단계로 확대합니다." }]),
    item("dependency rollback은 왜 준비해야 하나요?", "프론트엔드 dependency는 build output, runtime behavior, polyfill, CSS까지 바꿀 수 있어 빠른 되돌리기 경로가 필요합니다.", "패키지 업데이트 후 빌드는 통과해도 특정 브라우저나 route에서 런타임 오류가 날 수 있습니다.", "dependency diff, lockfile review, smoke test, rollback branch", [{ q: "patch update도 위험한가요?", answer: "semantic versioning상 patch라도 bundler plugin, CSS-in-JS runtime, sanitizer, polyfill, date library처럼 전역 동작에 가까운 패키지는 회귀를 만들 수 있습니다. lockfile diff와 bundle diff를 보고 핵심 route smoke와 브라우저 matrix를 최소 확인합니다." }, { q: "lockfile은?", answer: "lockfile은 실제 설치되는 transitive dependency를 고정하므로 리뷰 대상입니다. dependency PR에서는 package.json뿐 아니라 lockfile 변경, 새 install script, registry source, duplicate version, bundle size 변화를 함께 확인해야 재현 가능한 rollback이 됩니다." }, { q: "보안 업데이트면?", answer: "critical 취약점이면 빠르게 올리되 무검증 배포는 피합니다. exploit reachability, patch changelog, override 가능성, sanitizer나 auth 관련 회귀 테스트를 확인하고, 문제가 생기면 이전 버전으로 되돌릴지 대체 패키지로 갈지 playbook을 둡니다." }]),
  ],
};

for (const page of pages) {
  page.questions.push(...(coverageAdditions[page.id] ?? []));
}

const escapeHtml = (value) =>
  value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

const renderQuestion = (question, index) => `<section id="qa-${index + 1}">
<div class="ch-head"><span class="ch-code">Q${String(index + 1).padStart(2, "0")}</span><h2>${escapeHtml(question.q)}</h2></div>
<p class="lede">${escapeHtml(question.decision)}</p>
<p>${escapeHtml(question.failure)}</p>
<table>
<tr><th>꼬리질문</th><th>꼬리질문 답변</th></tr>
${question.followups
  .map((followup) => {
    if (typeof followup === "string") {
      throw new Error(`String follow-up is not allowed for ${question.q}: ${followup}`);
    }

    if (!followup?.q || !followup?.answer) {
      throw new Error(`Invalid follow-up for ${question.q}`);
    }

    return `<tr><td>${escapeHtml(followup.q)}</td><td>${escapeHtml(followup.answer)}</td></tr>`;
  })
  .join("\n")}
</table>
<div class="semantic-card">
<span class="sc-label">TRAINING EVIDENCE</span>
${escapeHtml(question.evidence)}
</div>
</section>`;

function renderPage(page) {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8"><meta name="robots" content="noindex, nofollow, noarchive, nosnippet">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(page.title)}</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css">
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<style>${css}</style>
</head>
<body>
<div class="shell">
<nav aria-label="목차">
  <div class="nav-brand">FRONTEND Q&amp;A</div>
  <div class="nav-title">${escapeHtml(page.title)}</div>
  <a href="#overview"><span class="code">GUIDE</span>훈련 방식</a>
${page.questions
  .map(
    (q, index) =>
      `  <a href="#qa-${index + 1}"><span class="code">Q${String(index + 1).padStart(2, "0")}</span>${escapeHtml(q.q)}</a>`,
  )
  .join("\n")}
  <a href="#drill"><span class="code">DRILL</span>꼬리질문 반복 훈련</a>
  <a href="#rubric"><span class="code">RUBRIC</span>통과 기준</a>
</nav>
<main>
<header class="hero">
  <div class="hero-serial">
    <span>DOC : ${page.id.toUpperCase()}</span>
    <span>SOURCE : ${escapeHtml(page.source)}</span>
    <span>MODE : QUESTION · ANSWER · FOLLOW-UP</span>
  </div>
  <h1>${escapeHtml(page.title)}</h1>
  <p class="hero-sub">${escapeHtml(page.subtitle)}</p>
  <div class="hero-meta">TRAINING : 30초 답변 → 90초 확장 → 꼬리질문 방어 → 증거 패킷 확인</div>
</header>

<section id="overview">
<div class="ch-head"><span class="ch-code">GUIDE</span><h2>훈련 방식</h2></div>
<p class="lede">각 문항은 API 암기나 라이브러리 사용법이 아니라, 사용자 흐름, 브라우저 비용, 접근성, 성능, 보안, 운영 증거를 연결해 답하는 훈련용입니다.</p>
<div class="snippet-card"><code>frontend_answer_loop:
  1_user_impact: "사용자가 겪는 변화와 실패 비용을 먼저 말한다"
  2_runtime_boundary: "DOM, network, rendering, cache, browser policy 중 경계를 잡는다"
  3_tradeoff: "선택 기준과 포기하는 것을 분리한다"
  4_failure_mode: "race, stale data, accessibility, device variance, cache drift를 점검한다"
  5_evidence: "trace, screenshot, test, metric, release log 중 하나를 증거로 든다"</code></div>
</section>

${page.questions.map(renderQuestion).join("\n\n")}

<section id="drill">
<div class="ch-head"><span class="ch-code">DRILL</span><h2>꼬리질문 반복 훈련</h2></div>
<table>
<tr><th>라운드</th><th>방법</th><th>통과 기준</th></tr>
<tr><td>1회차</td><td>각 질문을 30초 답변으로 녹음한다.</td><td>결론, 사용자 영향, 브라우저/런타임 경계가 빠지지 않는다.</td></tr>
<tr><td>2회차</td><td>꼬리질문 3개를 90초 답변으로 확장한다.</td><td>실패 모드와 검증 증거를 하나 이상 말한다.</td></tr>
<tr><td>3회차</td><td>실제 프로젝트 경험 또는 대체 검증 계획으로 연결한다.</td><td>직접 경험, 추론, 계획을 섞지 않고 구분한다.</td></tr>
</table>
</section>

<section id="rubric">
<div class="ch-head"><span class="ch-code">RUBRIC</span><h2>통과 기준</h2></div>
<div class="semantic-card">
<span class="sc-label">FRONTEND QA TRAINING PACKET</span>
통과 답변은 기능 구현 방법에서 멈추지 않고 사용자 영향, 브라우저 내부 동작, 접근성, 성능, 보안, 테스트, 운영 관측 증거를 함께 닫는다.
</div>
<div class="callout gm">
<span class="co-label">외부 검증 대응</span>
<p>모르는 주제가 나오면 직접 경험처럼 꾸미지 않는다. 대신 어떤 경계에서 문제가 생기는지, 어떤 도구로 재현할지, 어떤 지표와 테스트로 검증할지 구체적으로 답한다.</p>
</div>
</section>

<footer>FRONTEND QA TRAINING PACKET · ${escapeHtml(page.title)} · generated for handbook practice</footer>
</main>
</div>
</body>
</html>`;
}

await mkdir(outDir, { recursive: true });
for (const page of pages) {
  await writeFile(path.join(outDir, `${page.id}-handbook.html`), renderPage(page), "utf8");
}

console.log(`generated ${pages.length} frontend Q&A handbooks`);
